window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cardiologia-car-3"]={"block":"medcurso:medcurso-cardiologia-car-3","label":"Medcurso · CAR 3","count":421,"questions":[{"id":"medcurso-cardiologia-car-3-281102","number":"281102","sourceNumber":"281102","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 46 anos, hipertenso e tabagista, refere dor na região anterior do tórax, que\npiora com decúbito, de início há 6 horas.\nSinais vitais na admissão: PA 160/100mmHg, FV 100bpm,\nTemp.axilar 37,5ºC, FR 30mrpm. Com base nos dados clínicos e no ECG abaixo, qual seria a\nhipótese diagnóstica mais provável?","options":{"A":"Pericardite aguda","B":"Cardiomiopatia hipertrófica","C":"Disseção aórtica","D":"Taquiarritmia supraventricular por reentrada","E":"Síndrome coronariana aguda"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/281102.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-281103","number":"281103","sourceNumber":"281103","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 55 anos de idade com história de infarto do miocárdio há 3 meses, com\ndieta de estágio II, exercitando-se\nregularmente em programa de reabilitação cardíaca. Não fuma e\na pressão arterial é de 120/80 mmHg sob terapia com betabloqueador e AAS. Apresenta colesterol\ntotal = 240 mg/dl, HDL col. = 55 mg/dl, LDL col. = 165 mg/dl e triglicérides = 100 mg/dl. Sua\nconduta no tratamento desse paciente é:","options":{"A":"Recomendar dieta de estágio III.","B":"Iniciar sinvastatina, 20 mg/dia.","C":"Avaliar membros da família para descartar hipercolesterolemia familiar.","D":"Encaminhar a um especialista em lipídeos.","E":"Iniciar niacina, 2.000 mg/dia."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-251871","number":"251871","sourceNumber":"251871","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual dessas condutas não fazem parte do tratamento no atendimento inicial do infarto\nagudo do miocárdio:","options":{"A":"Aspirina.","B":"Beta-bloqueador.","C":"Morfina.","D":"Digitálico."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-251874","number":"251874","sourceNumber":"251874","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Não é contraindicação absoluta para uso de betabloqueador:","options":{"A":"Bloqueio atrioventricular de 3º grau.","B":"Pressão arterial sistólica menor que 80 mmHg.","C":"Frequência cardíaca de 49 batimentos por minuto.","D":"Asma."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-247161","number":"247161","sourceNumber":"247161","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 56 anos, com antecedentes de hipertensão e dislipidemia,\nprocura o ambulatório com dor torácica\nretroesternal tipo aperto que iniciou há cerca de dois\nmeses, de forma esporádica, durante suas caminhadas matinais, associada a períodos de aumento\nde intensidade do exercício. Os episódios de dor tinham duração de 5 minutos e melhoravam com\nrepouso. Há duas semanas refere que toda vez que caminha apresenta episódio de dor\ndesencadeada por esforço menor que o habitual. Assinale a alternativa CORRETA, que classifica a\ndor torácica apresentada pelo paciente.","options":{"A":"Angina típica e estável.","B":"Angina atípica e estável.","C":"Angina atípica e instável.","D":"Angina típica e instável.","E":"Angina de Prinzmetal."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182600","number":"182600","sourceNumber":"182600","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Correlacione CORRETAMENTE as características da dor torácica descritas abaixo com\nas respectivas doenças cardiovasculares. I. Dor\nretroesternal que irradia para a região cervical,\nmandíbula, epigástrio, ombros ou braços (mais comum do lado esquerdo), em opressão,\nqueimação, aperto ou peso, com duração menor do que 2-10 minutos, desencadeada pelo esforço,\nfrio ou \"stress\" emocional, aliviada pelo repouso. II. Dor que geralmente inicia sobre o esterno, ou\nem direção ao ápice cardíaco e pode irradiar-se para o pescoço ou ombro esquerdo, muitas vezes,\nmais localizada que a dor do infarto do miocárdio, tipo aguda em \"facada\", que pode durar muitas\nhoras até dias, pode alternar períodos de maior e menor intensidade, piora com a inspiração\nprofunda, rotação do tórax, ou posição supina, aliviada na posição supina, sentada ou com a\ninclinação anterior do tórax. III. Dor no tórax anterior, que pode irradiar-se para o dorso,\nlancinante\nem \"facada\", de início súbito, que geralmente ocorre na vigência de hipertensão ou em pacientes\ncom predisposição, como na síndrome de Marfan. IV. Dor subesternal ou localizada, pleurítica ou\nem opressão, de início súbito, com duração de minutos e menor do que 1 hora, que pode piorar\ncom a respiração. A. Pericardite; B. Angina pectoris; C. Embolia pulmonar; D. Dissecção aórtica.","options":{"A":"I-A, II-B, III-C e IV-D.","B":"I-B, II-A, III-D e IV-C.","C":"I-C, II-D, III-A e IV-B.","D":"I-D, II-C, III-B e IV-A."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183132","number":"183132","sourceNumber":"183132","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem hipertenso de 65 anos de idade chega a seu consultório devido a início recente\nde desconforto torácico, que você suspeita ser\nangina. A pressão arterial foi devidamente\ncontrolada com tiazídico e, agora, é de 150/96 mmHg. Qual das seguintes medicações é a menos\napropriada?","options":{"A":"Ácido acetilsalicilico.","B":"Betabloqueador.","C":"Nitrato sublingual.","D":"Diidropiridina de ação curta.","E":"Diltiazem."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-66983","number":"66983","sourceNumber":"66983","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual a medicação indicada para prevenção primária de eventos cardiovasculares\n(doença coronariana)?","options":{"A":"Ácido acetilsalicílico 100 mg/dia.","B":"Sinvastatina 40 mg/dia.","C":"Enalapril 10 kg/dia.","D":"Não há medicações indicadas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-37070","number":"37070","sourceNumber":"37070","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Assinale a alternativa que apresenta o (s) critério (s) eletrocardiográfico (s) para a\nutilização de trombolíticos no infarto agudo do miocárdio.","options":{"A":"Bloqueio do ramo esquerdo do feixe de Hiss e Bloqueio A-V de 1º grau, que existiam\npreviamente.","B":"Infradesnível do segmento ST em duas derivações contíguas > 1 milímetro.","C":"Bloqueio do ramo direito novo e supradesnível do segmento ST em duas derivações contíguas >\n1 milímetro.","D":"Supradesnível do segmento ST ou infradesnível do segmento ST > 1 milímetro.","E":"Bloqueio do ramo esquerdo novo ou supradesnível do segmento ST, > 1 milímetro em duas\nderivações contíguas."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-29399","number":"29399","sourceNumber":"29399","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Todas as ações abaixo são medidas de prevenção bem definidas contra Doença\nCoronariana, EXCETO:","options":{"A":"Tratamento da Hipercolesterolemia com Estatinas.","B":"Tratamento de Diabetes com Metformina.","C":"Interrupção do tabagismo.","D":"Prática regular de Exercícios Físicos.","E":"Tratamento da Hipertensão com Ácido Acetil Salicílico (Aspirina)"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-29387","number":"29387","sourceNumber":"29387","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quanto ao tratamento da angina instável e do infarto agudo do miocárdio sem supra\ndesnivelamento do segmento ST, é correto afirmar;","options":{"A":"A heparina convencional é semelhante a enoxaparina no desfecho combinado morte/infarto do\nmiocárdio, independentemente do escore de risco de TIMI. A segunda droga, entretanto, apresenta\nmaior facilidade na forma de administração.","B":"A morfina não deve ser realizada como rotina, mas habitualmente deve ser empregada em\npacientes com dor persistente apesar de nitratos e betabloqueadores.","C":"Os nitratos endovenosos, mas não os sublinguais, são contra-indicados se o paciente tiver feito\niso de sildenafil nas últimas 24 horas.","D":"A combinação de clopidogrel e aspirina, aumenta o risco de sangramento e não reduz\nmortalidade. Não é, portanto, indicada.","E":"O trombolítico deverá ser utilizado nos casos em que haja aumento sérico das enzimas\ncardíacas."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-343222","number":"343222","sourceNumber":"343222","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O teste de caminhada de 6 minutos (TC6min):","options":{"A":"Não é avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na\navaliação perioperatória.","B":"É avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes, em\npatologias crônicas, mas não na avaliação perioperatória.","C":"É avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na avaliação\nperioperatória.","D":"É avaliação invalidada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na avaliação\nperioperatória."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-343223","number":"343223","sourceNumber":"343223","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O estabelecimento de intervalos de referência para o TC6min em mulheres grávidas\nsaudáveis:","options":{"A":"Não permite a avaliação individual da capacidade funcional e pode ajudar a personalizar os\nprogramas de exercícios.","B":"Permite a avaliação individual da capacidade funcional e pode ajudar a personalizar os\nprogramas de exercícios.","C":"Permite a avaliação individual da capacidade funcional, mas não pode ajudar a personalizar os\nprogramas de exercícios.","D":"Permite a avaliação individual da capacidade não funcional e pode ajudar a personalizar os\nprogramas de exercícios."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-314191","number":"314191","sourceNumber":"314191","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Podem acontecer resultados falso-positivos, em que a CK-MB é positiva e a troponina é\nnegativa em cerca de 4% dos pacientes. Sendo correto que:","options":{"A":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, deve-se basear a decisão clínica no resultado da CK-MB.","B":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, deve-se basear a decisão clínica no resultado da troponina.","C":"Nos casos em que a CK-MB está elevada e a troponina está anormal, ambas dentro de sua\njanela cinética, deve-se basear a decisão clínica nunca no resultado da troponina.","D":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, nunca se deve basear a decisão clínica no resultado da troponina."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-314195","number":"314195","sourceNumber":"314195","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Pacientes com dor torácica no setor de emergência, identificados como de risco baixo\nou intermediário, tem como adequado o item:","options":{"A":"Nunca podem ser submetidos ao teste ergométrico (TE), apesar do resultado normal confere\nrisco anual baixo de eventos cardiovasculares,\npermitindo a alta hospitalar mais precoce e segura.","B":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado anormal confere risco anual\nbaixo de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura.","C":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado normal confere risco anual\nbaixo de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura.","D":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado normal confere risco anual\nelevado de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-314198","number":"314198","sourceNumber":"314198","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Comparada ao escore de cálcio, a angiotomografia de coronárias está de acordo com o\nitem correto:","options":{"A":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose luminal.","B":"É um exame que apresenta como desvantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose luminal.","C":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e não\nestimativas do grau de estenose luminal.","D":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose extra-luminal."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-314200","number":"314200","sourceNumber":"314200","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O uso da angiotomografia de coronárias apresenta claros benefícios, no item correto:","options":{"A":"Em pacientes assintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas.","B":"Em pacientes sintomáticos de baixo risco para DAC, na emergência, mas não no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas.","C":"Em pacientes sintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque não afasta a doença como causadora dos sintomas.","D":"Em pacientes sintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-313474","number":"313474","sourceNumber":"313474","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação à Síndrome Metabólica, Diabetes Mellitus e o Corolário Contínuo da\nDoença Arterial Coronária, pode-se considerar\nadequado que:","options":{"A":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que não contribuem\ndramaticamente para a progressão dos substratos fisiopatológicos\nda DAC.","B":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que contribuem pouco para a progressão dos substratos fisiopatológicos da DAC.","C":"A SM e o DM não compõem um espectro de doenças multissistêmicas, em particular do\nendotélio vascular, e que contribuem dramaticamente para a progressão dos substratos\nfisiopatológicos da DAC.","D":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que contribuem dramaticamente para a progressão dos substratos fisiopatológicos da\nDAC."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-278609","number":"278609","sourceNumber":"278609","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O critério eletrocardiográfico para IAMCST inclui elevação do segmento ST em duas\nderivações contíguas, sendo CORRETO de acordo com a Sociedade Brasileira de Cardiologia, a\nalternativa:","options":{"A":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 60 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações.","B":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações.","C":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 2 mm nas demais derivações.","D":"Acima de 2,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-279030","number":"279030","sourceNumber":"279030","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A dor torácica é o principal sintoma sugestivo de Síndrome Coronária Aguda (SCA) com\ncaracterísticas da dor torácica sugestivas de isquemia miocárdica. Sendo correto que:","options":{"A":"Pacientes com dor anginosa em repouso com mais de 60 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA.","B":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor não são sugestivas de SCA.","C":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de ambulatório\nde cardiologia, já que essas características da dor são sugestivas de SCA.","D":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-278614","number":"278614","sourceNumber":"278614","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Os critérios para diagnóstico de IAM são aumento e/ou queda de marcadores de\nnecrose miocárdica, preferencialmente a\ntroponina, com pelo menos um valor acima do percentil 99\ndo método, indique o item correto:","options":{"A":"Associado a pelo menos duas das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","B":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) antigo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","C":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","D":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia exceto em\nautópsia."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-278616","number":"278616","sourceNumber":"278616","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A dor torácica pode não estar presente durante um episódio de SCA em até cerca de\num terço dos casos. Estes pacientes podem\napresentar dispneia isoladamente, náuseas, vômitos,\npalpitações, síncope, ou mesmo parada cardíaca. Podemos indicar como correto que:","options":{"A":"Sintomas denominados equivalentes não isquêmicos normalmente acometem idosos, mulheres\ne pacientes diabéticos.","B":"Sintomas denominados equivalentes isquêmicos normalmente acometem idosos, mulheres e\npacientes diabéticos.","C":"Sintomas denominados equivalentes isquêmicos nunca acometem idosos, mulheres e pacientes\ndiabéticos.","D":"Sintomas denominados equivalentes isquêmicos normalmente acometem somente pacientes\ndiabéticos."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-278681","number":"278681","sourceNumber":"278681","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"No Brasil, país de dimensão continental e grande diversidade social e econômica,\ndentre as inúmeras barreiras ao acesso à\nReabilitação Cardiovascular - RCV, podemos assim\naceitar a alternativa abaixo como correta.","options":{"A":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, não são alternativas aos programas\ntradicionais, nos quais as sessões são sempre realizadas sob supervisão direta ou presencial.","B":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob\nsupervisão indireta, surgem como complemento ou alternativa\naos programas tradicionais, nos quais as sessões são sempre realizadas sob supervisão direta ou\npresencial.","C":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, surgem como complemento ou alternativa\naos programas tradicionais, nos quais as sessões são sempre realizadas sob supervisão indireta.","D":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, surgem como complemento, mas nunca\ncomo uma alternativa aos programas tradicionais, nos quais as sessões são sempre realizadas sob\nsupervisão direta ou presencial."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-252879","number":"252879","sourceNumber":"252879","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 66 anos de idade, da entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde Diabetes Mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200x120mmHg, FC: 100bpm, SatO? 94%, IMC: 33Kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Diante do quadro, indique o diagnóstico mais adequado\npara este paciente nesse momento.","options":{"A":"Emergência hipertensiva associada a síndrome coronariana aguda sem supra de ST.","B":"Angina instável associada a pseudocrise hipertensiva, devido à dor.","C":"Urgência hipertensiva associada a infarto agudo do miocárdio sem supra de ST.","D":"Emergência hipertensiva associada a dissecção aguda de aorta."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-252880","number":"252880","sourceNumber":"252880","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 66 anos de idade, dá entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde diabetes mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200 x 120 mmHg, FC: 100 bpm, SatO? 94%, IMC: 33 kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Indique a conduta diagnóstica mais adequada nesse\ncaso.","options":{"A":"Teste ergométrico, dentro das próximas 6 horas.","B":"Cintilografia de perfusão miocárdica, dentro de 72 horas.","C":"Cineangiocoronariografia, nas próximas 48 horas.","D":"Cineangiocoronariografia, nos próximos 30 minutos."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-252881","number":"252881","sourceNumber":"252881","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 66 anos de idade, da entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde Diabetes Mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200x120mmHg, FC: 100bpm, SatO? 94%, IMC: 33Kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Indique o tratamento farmacológico mais adequado para\nesse paciente.","options":{"A":"Ácido acetilsalicílico, clopidogrel, nitroglicerina, morfina, metoprolol, atorvastatina.","B":"Ácido acetilsalicílico, clopidogrel, nitroglicerina, heparina não fracionada, alteplase,\nmetoprolol.","C":"Clopidogrel, nitroprussiato de sódio, heparina não fracionada, abciximab, metoprolol,\natorvastatina.","D":"Ácido acetilsalicílico, nitroprussiato de sódio, morfina, heparina não fracionada, metoprolol,\nenalapril."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-249193","number":"249193","sourceNumber":"249193","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Nos pacientes com alto risco de sangramento e baixo risco isquêmico, deve-se\nintroduzir diretamente dupla terapia com anticoagulante e clopidogrel desde o início. Nesse\ncontexto, o item com erro é:","options":{"A":"Quando houver alto risco isquêmico e também alto risco hemorrágico, recomenda-se que se use\ntripla terapia por, no máximo, um mês ou inicie-se diretamente dupla terapia com anticoagulante e\nclopidogrel.","B":"O uso de inibidores de bombas de prótons como profilaxia de úlcera de estresse nesse grupo de\npacientes nunca deve ser considerado como primeira escolha devido ao risco elevado de\nsangramento gastrintestinal.","C":"A descontinuação do tratamento antiplaquetário deve ser considerada após 12 meses.","D":"A avaliação da necessidade de manutenção da anticoagulação e o cálculo do risco de\nsangramento devem ser realizados em todos os\npacientes através dos escores de CHA2DS2-VASc\ne HAS-BLED."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-249399","number":"249399","sourceNumber":"249399","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Escolar, sexo masculino, 8 anos, está frequentando a escolinha de futebol de areia do\nPelezão. A principal orientação durante a atividade física é hidratar com:","options":{"A":"Energéticos a cada 30 minutos.","B":"Isotônicos a cada 30 minutos.","C":"Água normal a cada 20 minutos.","D":"Guaraná com açaí a cada 30 minutos."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215198","number":"215198","sourceNumber":"215198","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O estudo que comparou clopidogrel versus AAS em pacientes com risco de isquemia,\ntendo demonstrado uma redução significativa do\nnúmero total de readmissões para eventos\nisquêmicos. NÃO podemos, apenas, concordar que:","options":{"A":"Naqueles pacientes que apresentam alergia ao AAS ou intolerância gástrica, o clopidogrel pode\nser considerado uma alternativa.","B":"Redução de novas hospitalizações foi consistente em todos os resultados individuais de angina,\nataque isquêmico transitório, isquemia de membros e sangramento.","C":"Clopidogrel não resultou em diminuição em desfecho combinado de morte vascular, AVC, infarto\ndo miocárdio ou nova hospitalização para\neventos isquêmicos ou sangramento em comparação\ncom o AAS.","D":"Dessa forma clopidogrel pode ser usado como alternativa ao AAS em intolerantes."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215272","number":"215272","sourceNumber":"215272","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quanto à indicação da terapia antiplaquetária nos pacientes de muito alto risco,\nincluindo aqueles com Doença Aterosclerótica\nClínica (DACL) e eventos cardiovasculares prévios\n(prevenção secundária), o benefício é estabelecido em diversos estudos, o AAS (ou outro\nantiplaquetário):","options":{"A":"Foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","B":"Não foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","C":"Foi protetor na maioria dos pacientes com risco aumentado de eventos não vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","D":"Foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, excluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-212227","number":"212227","sourceNumber":"212227","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 58 anos, sexo feminino, portadora de hipertensão, dislipidemia e\nobesidade, evoluiu de forma súbita com quadro de\ndor torácica, em aperto, de forte intensidade,\nnáuseas e sudorese. Atendida imediatamente ao chegar ao hospital de emergência, realizou\neletrocardiograma e foi colhido o sangue para avaliação dos marcadores de necrose miocárdica.\nCardiologista avaliou o resultado do eletrocardiograma e a paciente foi diagnosticada com infarto\nagudo do miocárdio com supradesnível de ST (IAMST). As primeiras medidas terapêuticas foram\niniciadas e a reperfusão coronariana indicada. Uma das medidas terapêuticas na fase aguda do\nIAMST consiste em iniciar o inibidor da enzima conversora de angiotensina (IECA). Assinale a\nalternativa que apresenta uma contraindicação ao uso dos IECAS.","options":{"A":"Hemofilia.","B":"DPOC grave.","C":"Úlcera péptica em atividade.","D":"Estenose bilateral da artéria renal.","E":"Uso de inibidores da fosfodiesterase nas últimas 24 h."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183029","number":"183029","sourceNumber":"183029","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em discussão com amigos nesse final de semana, você foi questionado sobre\ntreinamento de emergência para pessoal que\nnão fosse da saúde. Assim, explicou que a\nimportância da FV como mecanismo de óbito precoce e a habilidade na ressuscitação e na\ndesfibrilação foram os fatores que propiciaram o desenvolvimento de programas de tratamento\npré-hospitalar do IAM. Estando INCORRETO, apenas, que","options":{"A":"se estima que a desfibrilação salve cerca de seis vezes mais vidas que o tratamento\ntrombolítico, mas depende de sua rápida aplicação ao paciente.","B":"o impacto potencial, em termos de benefício, ao se intervir na fase pré-hospitalar no IAM,\nreforça\na necessidade de programas.","C":"identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma\nnova estratégia de grande difusão na população.","D":"fornecer maior informação à população quanto aos sintomas de IAM e a importância de uma\nbusca rápida por auxílio médico. Realizar\ntreinamento restrito, apenas à saúde, para atendimento\nde urgência nos moldes do BLS, a fim de evitar erros."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182733","number":"182733","sourceNumber":"182733","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A fisiopatologia do IAM perioperatório difere um pouco da do IAM espontâneo.\nConsiderando os Testes Não Invasivos para\nDetecção de Isquemia Miocárdica, o entendimento do\nEletrocardiograma de Esforço apenas NÃO é compatível com a seguinte alternativa.","options":{"A":"No IAM perioperatório, a ruptura de placa ocorre em aproximadamente 90% dos casos.","B":"No IAM perioperatório se dá, também, por um desequilíbrio prolongado entre a redução da oferta\nde oxigênio para o miocárdio (anemia, baixo\nfluxo etc.) e o aumento da demanda arterial\ncoronariana (taquicardia e hipertensão).","C":"O TE é uma ferramenta segura, útil e eficaz para a detecção de isquemia miocárdica, tendo\njustamente como mecanismo produzir este desbalanço entre oferta e demanda.","D":"A detecção de anormalidades durante sua execução dos testes de esforços possa ser\nreprodutível durante o perioperatório e seus variados níveis de estresse."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183053","number":"183053","sourceNumber":"183053","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Órgãos governamentais de saúde e o sistema privado de saúde suplementar devem\ncriar e manter um plano regional de\natendimento emergencial integrado de pacientes com IAMCST,\ncomo o já existente em vários países. Podemos apenas concordar que, as terapias recomendadas\nna fase pré-hospitalar","options":{"A":"são baseadas em estudos realizados em pacientes pré-hospitalares. Desse modo, deve ser feita\npor equipe capacitada e treinada.","B":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja diferente, a circunstância clínica é a mesma: IAM. Trata-se, desse modo, de\numa extrapolação coerente, que, naturalmente,\ndeve ser feita por equipe capacitada e treinada.","C":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja diferente, a circunstância clínica é a mesma: IAM. Trata-se, desse modo, de\numa extrapolação incoerente, que, naturalmente,\nnão deve ser feita por equipe capacitada e\ntreinada.","D":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja igual, a circunstância clínica é diferente do IAM. Trata-se, desse modo, de\numa extrapolação coerente, que, naturalmente, deve\nser feita por equipe capacitada e treinada."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182742","number":"182742","sourceNumber":"182742","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O Teste de Esforço TE é uma ferramenta segura, útil e eficaz para a detecção de\nisquemia miocárdica, tendo justamente como mecanismo produzir este desbalanço entre oferta e\ndemanda. Somente sendo INCORRETO que,","options":{"A":"assim, é razoável pensar que a detecção de anormalidades durante sua execução possa ser\nreprodutível durante o perioperatório e seus variados níveis de estresse.","B":"não há evidências de que usar esta estratégia para todos os pacientes resulte na redução de\neventos cardiovasculares perioperatórios.","C":"também deve se considerar que, quanto maior a prevalência da doença coronária em\ndeterminada população, menor será também o valor preditivo positivo do TE.","D":"considerando que o objetivo da estratificação do risco é reduzir o risco perioperatório, não\nseria\nlógica a realização do teste em uma população já estratificada como de baixo risco pelos algoritmos\nrecomendados."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183060","number":"183060","sourceNumber":"183060","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A administração de oxigênio é rotineira no atendimento a um paciente com IAM,\ngarantindo, assim, uma melhor chance de sobrevida aos pacientes. Somente podemos\nCONCORDAR que","options":{"A":"administração de oxigênio é indicada somente em pacientes com saturação de oxigênio < 90%,\ncongestão pulmonar ou na presença de desconforto respiratório.","B":"quando utilizada de forma necessária, a administração de oxigênio por tempo prolongado pode\ncausar vasoconstrição sistêmica, e aumento da\nresistência vascular sistêmica e da pressão arterial,\nreduzindo o débito cardíaco, sendo, portanto, prejudicial.","C":"quando utilizada de forma desnecessária, a administração de oxigênio por tempo prolongado\npode causar vasoconstrição sistêmica e aumento da\nresistência vascular sistêmica e da pressão\narterial, reduzindo o débito cardíaco, sendo, portanto, prejudicial.","D":"quando utilizada de forma desnecessária, a administração de oxigênio por tempo prolongado\npode causar vasoconstrição sistêmica e redução\nda resistência vascular sistêmica e da pressão\narterial, aumentando o débito cardíaco, sendo, portanto, prejudicial."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182749","number":"182749","sourceNumber":"182749","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A ecocardiografia sob estresse é precisa e segura em identificar pacientes com doença\narterial coronária, com importante papel como preditor de eventos cardíacos. Somente sendo\nINCORRETO que,","options":{"A":"as ecocardiografias sob estresse pela dobutamina e pelo exercício apresentam acurácia\ndiagnóstica semelhantes e superiores ao estresse com dipiridamol.","B":"caso um ecocardiograma sob estresse pela dobutamina demonstre isquemia residual no\npaciente com infarto prévio, o prognóstico é bom, e a probabilidade de reinfarto, morte e edema\nagudo pulmonar é baixa no período transoperatório de uma cirurgia não cardíaca.","C":"o uso da ecocardiografia sob estresse pela dobutamina na avaliação do risco perioperatório já\nestá bem documentado na literatura.","D":"comparando a cintilografia de perfusão miocárdica e a ecocardiografia sob estresse pela\ndobutamina na estratificação de risco vascular antes cirurgia, foi demonstrado que o valor\nprognóstico das anormalidades em ambas as modalidades de imagens para eventos isquêmicos\nperioperatórios é semelhante."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183067","number":"183067","sourceNumber":"183067","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O diagnóstico e a caracterização das regiões de IAM pela Ressonância Magnética\nCardiovascular RMC baseiam-se na técnica do\n\nrealce tardio. Podemos, apenas, concordar que","options":{"A":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-nfarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, não apenas na avaliação diagnóstica, mas também na\navaliação prognóstica dos pacientes.","B":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação diagnóstica.","C":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação prognóstica dos pacientes.","D":"a incapacidade de identificação da extensão das regiões de infarto, mas sim da presença ou não\nde obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação\n\ndiagnóstica, mas não na avaliação prognóstica dos pacientes."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182758","number":"182758","sourceNumber":"182758","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando analisamos a Angiografia Coronária por Tomografia Computadorizada,\npodemos apenas CONCORDAR com o seguinte:","options":{"A":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes sem suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda.","B":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta baixa sensibilidade para a detecção\nde estenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda.","C":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, excluindo doença multiarterial e lesão em tronco de coronária esquerda.","D":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182769","number":"182769","sourceNumber":"182769","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O aumento da sensibilidade dos kits disponíveis das troponinas propiciou uma maior\nacurácia e rapidez no diagnóstico ou não do IAM em pacientes com dor torácica na sala de\nemergência. Somente NÃO sendo correto que,","options":{"A":"no perioperatório de operações não cardíacas, as evidências científicas disponíveis não incluem\ntodas as troponinas (I e T) e nem todos os métodos utilizados para sua dosagem apresentam\nlimites de detecção e valores de referência diferentes.","B":"o limite de detecção significa o máximo valor que é detectado pelo método.","C":"o valor de referência da normalidade é determinado utilizando o percentil 99, que é obtido\nrealizando-se o exame em uma população normal e, significa que, 99% dos indivíduos normais\napresentam valores abaixo deste cut-off.","D":"os kits de troponina podem ser classificados em baixa (convencionais), média (contemporâneos\nou sensíveis) ou alta sensibilidade. Esta\nclassificação é baseada na porcentagem de indivíduos\nsaudáveis em que a troponina pode ser detectada."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182819","number":"182819","sourceNumber":"182819","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Na Pericardite, o processo inflamatório decorrente da epicardite subjacente nos\nventrículos é o responsável pelas seguintes alterações eletrocardiográficas, EXCETO","options":{"A":"pela onda T: na fase inicial, apresenta-se pouco aumentada e assimétrica.","B":"pela onda T: caracteristicamente não apresenta inversão enquanto ocorrem manifestações de\nelevação do ST.","C":"que pode apresentar inversão de T na fase crônica da doença, após a normalização do ST.","D":"quando esta ocorre inversão de T, raramente é profunda o suficiente para assemelhar-se ao\npadrão da onda T isquêmica."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182738","number":"182738","sourceNumber":"182738","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Amostra de sangue para avaliação do perfil lipídico deve ser obtida nas primeiras 24\nhoras da admissão de todos os pacientes com síndrome coronariana aguda (SCA). Sendo\nINADEQUADO, apenas, o seguinte:","options":{"A":"após este período, comumente ocorre aumento de TG e diminuição do LDL-C e do HDL-C,\nmodificações que podem permanecer por cerca de um a três meses.","B":"recomenda-se a instituição precoce do tratamento com altas doses de estatina entre o primeiro e\no quarto dia da SCA, preferencialmente\natorvastatina na dose 80 mg.","C":"pacientes indicados para intervenção percutânea e angioplastia podem experimentar benefício\nadicional quando a dose de estatina for administrada até 12 horas antes do procedimento.","D":"a dose de estatina apropriada para manter o LDL-C na meta terapêutica (< 100 mg/dl) deverá\nser mantida ."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183101","number":"183101","sourceNumber":"183101","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"As doenças e as respostas inflamatórias do pericárdio podem ocorrer de distúrbios\ncomuns e incomuns. Das patologias citadas abaixo, qual não entra nas possíveis etiologias de\npericardite e derrame pericárdico?","options":{"A":"Artrite reumatóide.","B":"Granulomatose de Wegener.","C":"Diabetes insipidus.","D":"Hipotireoidismo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-187849","number":"187849","sourceNumber":"187849","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considerando a terapia clinica do infarto agudo do miocárdio com\nsupra-desnivelamento do segmento-ST, assinale a alternativa ERRADA:","options":{"A":"O ácido acetilsalicílico deve ser utilizado com dose de ataque de 200mg a 300mg e o clopidogrel\ncom dose de ataque de 300mg a 600mg, não sendo\nnecessária a suspensão para execução da\ntrombólise.","B":"Os betabloqueadores reduzem o consumo miocárdico de oxigênio pela redução da frequência\ncardíaca, da pressão arterial e pela\ncontratilidade. Podem ser utilizados por via oral ou venosa,\ndevendo ser evitado na presença de sinais de choque.","C":"Os bloqueadores dos canais de cálcio, verapamil e diltiazem, podem ser utilizados em\nassociação aos betabloqueadores para melhor controlar a resposta ventricular de arritmias.","D":"Os inibidores da enzima conversora de angiotensina não devem ser utilizados em pacientes com\npressão sistólica menor que 100mmHg ou com redução de 30mmHg em relação ao valor basal"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161318","number":"161318","sourceNumber":"161318","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 47 anos de idade, apresentou dor torácica em aperto\nacompanhado de mal-estar, diaforese e dispneia\nde início há duas horas, nessa manhã de\nsegunda-feira. Podemos assim determinar que:","options":{"A":"ácido acetilsalicílico é o único anti-inflamatório indicado rotineiramente para todos os\npacientes\ncom suspeita de IAM, eventualmente como\nautomedicação.","B":"pacientes com maior risco de doença coronária devem ser instruídos a tomar ácido\nacetilsalicílico (AAS) tamponado em\n\nsituações emergenciais.","C":"é o antiplaquetário de eleição a ser utilizado no IAM, tendo sido demonstrado que sua redução\nna mortalidade é muito menor que o da trombólise\nquímica.","D":"não tem ação sinérgica com o próprio fibrinolítico, levando à associação de ambos ao aumento\nda mortalidade."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161275","number":"161275","sourceNumber":"161275","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente procurou Pronto-socorro com intensa dor torácica e dispneia de início nesta\nmanhã. Refere ser hipertenso e tabagista. Seu ECG demonstra supra de segmento ST de 3 mm\nnas derivações D2 e D3. Marque a opção que NÃO influencia na mortalidade, nesse caso.","options":{"A":"Ausculta cardíaca.","B":"Ausculta pulmonar.","C":"Alterações à direita.","D":"Local da dor torácica."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161325","number":"161325","sourceNumber":"161325","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A abordagem de pacientes acometidos por Insuficiência Coronariana Aguda deve\ncontemplar diversos tratamentos coadjuvantes a fim de melhorar o prognóstico da lesão em\nevolução. Sobre isso, assinale a alternativa CORRETA.","options":{"A":"A recomendação atual é de se utilizar o betabloqueador por via oral nas primeiras 24 horas.","B":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 50 batimentos por\nminutos.","C":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 70 batimentos por\nminutos.","D":"A utilização de betabloqueador endovenoso deve ser feita sem maiores critérios ou cuidados,\npois é pouco associada com\n\ncomplicações."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-158813","number":"158813","sourceNumber":"158813","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente J.T.A., 25 anos, sexo masculino, deu entrada na emergência com quadro de\ndispneia aos pequenos esforços, ascite e edema de membros inferiores. Ao exame físico: ausculta\npulmonar normal; avaliação cardiológica: ritmo cardíaco regular e um ruído diastólico mitral de\n\n+++/4+, definido como estalido protodiastólico (?Knock? pericárdico); Fc: 92bpm; PA: 110 x 60\nmmHg. Presença de turgência de jugular. Abdome: globoso, flácido, doloroso à palpação de\nhipocôndrio direito, sem sinais de irritação peritoneal. Piparote positivo. Fígado palpável 5 cm do\nrebordo costal direito. Extremidades: presença de edema (+/4+) em membros inferiores. Realizou\nraio-X de tórax que evidenciou área cardíaca normal e calcificação por todo o pericárdio, que\npermitiu realizar o diagnóstico de pericardite constritiva. No nosso meio, qual a principal causa de\npericardite constritiva?","options":{"A":"Tuberculose.","B":"Esclerodermia.","C":"Artrite reumatoide.","D":"Infarto agudo do miocárdio.","E":"Lúpus eritematoso sistêmico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161208","number":"161208","sourceNumber":"161208","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente foi atendido, no setor de emergência nesta manhã, de acordo com a última\natualização a respeito de IAM. Diante dessa situação, indique a opção CORRETA.","options":{"A":"É indicada administração de oxigênio rotineira em pacientes com saturação de oxigênio < 90%,\ncongestão pulmonar ou na presença de desconforto respiratório.","B":"A analgesia deve ser feita de preferência com sulfato de morfina endovenosa, exceto para\npacientes alérgicos a esse fármaco, na dose\ninicial de 2 a 8 mg (geralmente suficiente para aliviar a\ndor e a ansiedade). Com a monitorização da pressão arterial, essas doses podem ser repetidas em\nintervalos de 3 minutos.","C":"Os Anti-inflamatórios Não Esteroides (AINES) não devem ser utilizados na vigência de IAM e, se\no paciente que apresenta esse diagnóstico\nfizer uso crônico de AINES, este deve ser suspenso. O\núnico anti-inflamatório indicado rotineiramente para todos os pacientes com suspeita de IAM é o\nÁcido Acetilsalicílico.","D":"Nitratos podem ser utilizados somente na formulação sublingual (nitroglicerina, mononitrato de\nisossorbida ou dinitrato de isossorbida), para reversão de eventual espasmo e/ou para alívio da dor\nanginosa. Também estão recomendados para controle da hipertensão arterial ou alívio da\ncongestão pulmonar, se presentes."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161126","number":"161126","sourceNumber":"161126","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 59 anos de idade, internado, na sala de emergência do hospital\nonde você se encontra de plantão, com\ndiagnóstico de Insuficiência Coronariana. Ele apresentou,\nnovamente de madrugada, intensa dor torácica, sendo então solicitado que você o avaliasse\nnovamente. Diante de tal quadro clínico, aponte a conduta CORRETA.","options":{"A":"Tratamento da dor não diminui o consumo de oxigênio pelo miocárdio isquêmico, provocado pela\nativação do sistema nervoso simpático.","B":"A analgesia deve ser feita de preferência com sulfato de morfina oral, exceto para pacientes\nalérgicos a esse fármaco, na dose inicial\nde 2 a 8 mg (geralmente suficiente para aliviar a dor e a\nansiedade). Com a monitorização da pressão arterial, essas doses podem ser repetidas em\nintervalos de 5 a 15 minutos.","C":"Analgesia com morfina pode ser substituído pelo sulfato de Meperidina.","D":"Alguns estudos iniciais sugerem que a atividade dos novos antiplaquetários, prasugrel e\nticagrelor, tenham sua atividade aumentada em pacientes que receberam morfina."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161136","number":"161136","sourceNumber":"161136","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Logo ao chegar ao Hospital, você foi solicitado para avaliar um paciente que já estava\ninternado há 5 dias com diagnóstico de Infarto Agudo do Miocárdio; já havia sido liberado da\nUnidade Coronariana, mas como apresentava ainda dificuldade de controle da Pressão Arterial,\nnecessitava de constante intervenção, mesmo estando na enfermaria. Relacionado a essa\nsituação, aponte a alternativa contendo a conduta CORRETA.","options":{"A":"Nitratos não podem ser utilizados na formulação sublingual (nitroglicerina, mononitrato de\nisossorbida ou dinitrato de isossorbida)\npara reversão de eventual espasmo e/ou para alívio da dor\nanginosa, nesse caso somente venosos.","B":"Nitratos estão recomendados para controle da hipertensão arterial ou alívio da congestão\npulmonar, se presentes.","C":"Estão contraindicados (nitratos) na presença de hipotensão arterial (Pressão Arterial Sistólica\n?\n\nPAS < 110 mmHg).","D":"Estão contraindicados (nitratos) quando houver suspeita de comprometimento de Parede\nInferior."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-152657","number":"152657","sourceNumber":"152657","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A angina pectoris instável é conhecida como angina de:","options":{"A":"Korotkoff.","B":"Prinzmetal.","C":"Simmers.","D":"Blomberg.","E":"NDA."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161400","number":"161400","sourceNumber":"161400","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro da análise estatística e epidemiológica das relações da sobreposição de\ndoenças como o Diabetes, a Hipertensão Arterial e\na Arteriosclerose, aponte a alternativa\nINCORRETA.","options":{"A":"A frequência de hipertensão mascarada pode ser maior no DM do que em indivíduos sem DM, e\na incidência de desfechos cardiovasculares é\nmaior nesses pacientes, quando não tratados.","B":"A apresentação clínica da DAC pode ser de dor anginosa típica ou atípica, mas a ausência de\nsintomas é muito raro.","C":"Além disso, a DAC nesses pacientes tem pior prognóstico, com menor sobrevida em curto\nprazo, maior risco de recorrência e pior resposta aos tratamentos propostos.","D":"A letalidade do Infarto Agudo do Miocárdio (IAM) em pacientes com DM é duas vezes maior do\nque naqueles sem DM, em razão da maior\nfrequência de complicações como IC, reinfarto e morte\nsúbita."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161194","number":"161194","sourceNumber":"161194","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O impacto estatístico de um Eletrocardiograma (ECG), executado no local de\natendimento inicial do Infarto Agudo do\nMiocárdio (IAM) e interpretado por um médico habilitado (no\nlocal ou em local remoto), mostrou ser um método que","options":{"A":"reduz em 70% o tempo porta-agulha.","B":"reduz em 50% o tempo porta-balão.","C":"proporciona menores taxas de tempo porta-balão ideal.","D":"leva a tendência à redução de mortalidade intra-hospitalar em pacientes com IAMCST."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-161412","number":"161412","sourceNumber":"161412","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Existem razões pelas quais se devem desenvolver uma estratégia preventiva para a\nprática clínica, promovendo a reabilitação cardiovascular. Aponte a alternativa INCORRETA\nreferente a esse caso.","options":{"A":"A aterosclerose se desenvolve de forma insidiosa durante décadas e suas manifestações\nclínicas só se fazem notar nos estágios avançados da\ndoença.","B":"Em sua maior parte, as DCVs possuem uma estreita relação com estilo de vida, assim como\ncom fatores fisiológicos e bioquímicos não\nmodificáveis.","C":"As modificações dos fatores de risco, promovidas pela RCV, reduzem a morbimortalidade por\nDCV, sobretudo para os indivíduos classificados como de alto risco.","D":"A carga das DCVs tem crescido nas últimas décadas, paralelamente ao incremento da\nprevalência de fatores de risco."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134813","number":"134813","sourceNumber":"134813","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A necessidade de doses cada vez maiores e a perda de eficiência da medicação\nanti-hipertensiva e antianginosa das famílias dos ditos nitratos, está MELHOR explicada pela\nafirmativa:","options":{"A":"Filtração renal.","B":"Metabolismo hepático.","C":"Metabolismo endotelial.","D":"Resistência cárdica."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134119","number":"134119","sourceNumber":"134119","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino de 54 anos de idade deu entrada na sala de emergência com dor\ntorácica intensa, sudorese e mal-estar. Seu exame físico apresenta ausculta pulmonar normal,\nausculta cardíaca com B3. Sua PA 130 x 60 mm Hg, FC 89 bpm, Saturação de 95% ao ar\nambiente. Ao solicitar ECG, demonstramos supra de ST em V1, V2, V3 com 3 mm. Dentro das\nvárias condutas a serem tomadas nesse caso, podemos afirmar que o uso de Oxigênio:","options":{"A":"Mostra-se indicado pela saturação abaixo de 99%.","B":"Somente seria indicado caso a saturação fosse abaixo de 94%.","C":"Pode ser administrado sem riscos.","D":"Nunca deve ser utilizado no quadro de IAM."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134804","number":"134804","sourceNumber":"134804","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente durante consulta refere intensa dor precordial, logo após subir pequeno lance\nde escada para trabalhar. Em sua história refere ser fumante e hipertenso leve. Exame físico\ndemonstra galope de B3 bem como fascie de dor além de sudorese fria e pegajosa. Então, é\nsolicitado ECG. O ECG demonstra corrente de lesão com supra de 2 mm no segmento ST nas\nseguintes derivações DII, DIII e aVF. Podemos, assim, AFIRMAR que:","options":{"A":"Trata-se de infarto agudo do miocárdico do ventrículo direito.","B":"A coronariana envolvida provavelmente é a descente anterior.","C":"Esse supra é imagem em espelho de parede posterior.","D":"Nesse caso, podemos utilizar, a princípio, nitratos."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134033","number":"134033","sourceNumber":"134033","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente com queixa de dor epigástrica, sudorese e mal-estar, de início há alguns\nminutos, procura o hospital e realiza ECG que\ndemonstra supra do seguimento ST nas\nseguintes derivações: D2, D3 e aVF, tendo 3 mm. Ao realizar a prescrição na sala de\nemergência, você, como médico, lembra que nitratos são contraindicados quando ocorre uma das\nseguintes situações, EXCETO por uma das alternativas. Aponte-a.","options":{"A":"Uso prévio de sildenafil ou similares, nas últimas 24 horas.","B":"Quando houver suspeita de comprometimento do Ventrículo Direito.","C":"Pressão Arterial Sistólica ? PAS < 90 mmHg.","D":"Suspeita de IAM inferior."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-131404","number":"131404","sourceNumber":"131404","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"São fatores de risco para doença coronariana, EXCETO:","options":{"A":"Fumo, sedentarismo e história familiar de IAM.","B":"Fumo, diabetes e varizes de MMII.","C":"Diabetes, hipertensão e sedentarismo.","D":"Hipercolesterolemia e diabetes.","E":"NDA."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-110052","number":"110052","sourceNumber":"110052","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo feminino, 65 anos, admitida com Infarto Agudo do Miocárdio,\nantecedente de Osteoartrite em uso crônico de\nanti-inflamatórios não esteroidais. Com relação ao\nuso desta classe de medicamentos no Infarto, é CORRETO afirmar que deve ser:","options":{"A":"mantida, pois não aumenta os riscos cardiovasculares, porém há necessidade de\nassociação do Ácido Acetilsalicílico para a prevenção de reinfarto.","B":"mantida, pois não aumenta os riscos cardiovasculares e não há necessidade de\nassociação do Ácido Acetilsalicílico para a prevenção de reinfarto, pois se trata da mesma\nclasse farmacológica.","C":"suspensa pelo risco aumentado de hipertensão, reinfarto e mortalidade, e introduzido o Ácido\nAcetilsalicílico.","D":"suspensa pelo risco aumentado de Gastrite e Úlcera Gástrica se utilizado em conjunto com o\nÁcido Acetilsalicílico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-110598","number":"110598","sourceNumber":"110598","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 62 anos de idade, é atendido na Unidade de Emergência, com\nhistória de dor lancinante, extremamente\nsúbita em região precordial, irradiada ao dorso. Ao\nchegar, estava pálido, taquicárdico, Pressão Arterial de 180 x 110 mmHg, com sopro de\nregurgitação no foco aórtico e estertores em bases pulmonares. Pulsos periféricos diminuídos em\nMMIIS. Em relação ao caso, NÃO devemos introduzir imediatamente:","options":{"A":"Nitroprussiato de sódio.","B":"Derivados da morfina.","C":"Beta-bloqueadores.","D":"Nitratos.","E":"Bloqueadores da enzima conversora."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-86610","number":"86610","sourceNumber":"86610","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"As afirmativas abaixo incluem uma série de medidas sobre o manejo inicial de\npacientes com síndromes coronarianas agudas.\nAssinale a alternativa correta: (compêndio de UTI).\nI ? O uso da nitroglicerina está contraindicado em pacientes que fizeram uso de inibidor, da\nfosfodiesterase para disfunção erétil nas últimas 24 horas. II ? As tienopiridinas utilizadas como\nantiagregantes plaquetários, são drogas que bloqueiam de forma irreversível os receptores de\nsuperfície envolvidos na agregação plaquetária induzida pelo ADP. III ? os ?-bloqueadores não são\nrecomendados para o infarto do miocárdio induzido pela cocaína em virtude do potencial do\nagravamento do vasoespasmo coronariano pela atividade sem oposição dos receptores ?.","options":{"A":"Apenas afirmativa II está correta.","B":"Apenas afirmativas I, II estão corretas.","C":"Apenas afirmativas I, III estão corretas.","D":"Apenas afirmativa I está correta.","E":"Todas afirmativas estão corretas."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-86869","number":"86869","sourceNumber":"86869","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O Sr. João, de 72 anos, foi à consulta na Unidade Saúde da Família Terra Firme, tendo\ncomo motivo principal a necessidade de realizar exames de rotina. Após realizar o SOAP, seu\nMédico de Família e Comunidade detecta o antecedente de angina instável e fibrilação atrial\ncrônica sem tratamento e a presença de ritmo cardíaco irregular no exame físico. Ao final da\nconsulta, pergunta se tem algo mais que o Sr. João gostaria de relatar. A partir disto, ele diz ao\nmédico que está ?impotente? (ficou ansioso e perdeu a ereção e a partir disto o quadro se repete.\nEreção matinal presente). Marque a alternativa com a melhor conduta para o Sr. João.","options":{"A":"A conduta seria a prescrição de dinitrato de\n\nisossorbida e ácido acetilsalicílico contínuos, e sildenafila quando necessário;","B":"A conduta seria a prescrição de ioimbina por 30 dias, associada ao ácido acetilsalicílico e ao\npropatilnitrato contínuos;","C":"A onduta seria encaminhar o Sr. João ao urologista para avaliação;","D":"A conduta seria investigar o quadro de angina instável e arritmia e fazer a abordagem\ncomportamental da disfunção erétil;","E":"A conduta seria a prescrição de amiodarona,\n\nsinvastatina, ácido acetilsalicílico e propatilnitrato contínuos e tadalafila quando necessário."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-49614","number":"49614","sourceNumber":"49614","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Assinale a droga de primeira indicação na arritmia secundária a infarto agudo do\nmiocárdio:","options":{"A":"Lidocaína.","B":"Propranolol.","C":"Verapamil.","D":"Amiodarona.","E":"Metoprolol."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-176046","number":"176046","sourceNumber":"176046","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 65 anos, tabagista, sedentário e obeso, chega no pronto-socorro em 28 de\nagosto com dor precordial típica. Seu ECG na admissão revelou supradesnivelamento do seg ST\nde 0,3 mV em V4R, V5R e V6R. Neste cenário, qual o diagnóstico e tratamento imediato? Escolha\ndentre as opções abaixo:","options":{"A":"Infarto de ventrículo direito e o tratamento deve ser feito com expansão de volume.","B":"Infarto de ventrículo direito e o tratamento deve ser feito com nitrato endovenoso.","C":"Infarto de parede anterior localizada e tratamento com betabloqueadores endovenosos.","D":"Infarto de parede anterosseptal e tratamento com betabloqueadores endovenosos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-129756","number":"129756","sourceNumber":"129756","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A terapia trombolítica no infarto agudo do miocárdio com supra de ST tem como\ncontraindicação absoluta:","options":{"A":"Menstruação excessiva.","B":"Diabetes mellitus descompensado.","C":"Hipertrigliceridemia acentuada.","D":"História de acidente vascular encefálico hemorrágico há 2 anos."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-129770","number":"129770","sourceNumber":"129770","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 55 anos, sem comorbidades conhecidas, traz um eletrocardiograma de\nrepouso sem alterações, apresenta dor\ntorácica precordial que o obriga a reduzir o passo no meio\nde suas caminhadas diárias e que cede em repouso. A opção de exame complementar para\ndiagnóstico de doença coronariana é:","options":{"A":"Teste ergométrico.","B":"Holter de 24 horas.","C":"Cintilografia miocárdica com dobutamina.","D":"Ecocardiograma transtorácico com estresse farmacológico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-107601","number":"107601","sourceNumber":"107601","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Entre as situações descritas abaixo, aquela que contraindica formalmente a terapia\ntrombolítica no infarto agudo do miocárdio com supra de ST é:","options":{"A":"Sangramento menstrual.","B":"Diabetes mellitus descontrolado.","C":"Idade superior a 65 anos.","D":"História de acidente vascular encefálico hemorrágico há 2 anos."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-107951","number":"107951","sourceNumber":"107951","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo feminino, 55 anos, hipertensa e tabagista, admitida com dor torácica\nanginosa com duração de 15 minutos e melhora espôntanea. Durante o atendimento médico, teve\nnova dor precordial de curta duração associada à inversão dinâmica de onda T de V1 a V4, com\nnormalização após nitrato sublingual. O melhor tratamento inicial para essa paciente seria:","options":{"A":"Metoprolol + nitrato + AAS + dalteparina + clopidogrel.","B":"Nitrato + propanolol + heparina não fracionada + tirofiban.","C":"Clopidogrel + bloqueador de cálcio + nitrato + IECA + oxigênio + heparina não fracionada.","D":"AAS + enoxaparina + nitrato + metoprolol + clopidogrel + oxigênio."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-103816","number":"103816","sourceNumber":"103816","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação a um paciente com diagnóstico de IAM (Infarto Agudo do Miocárdio) é\nCORRETO afirmar:","options":{"A":"FC >100 e FC< 50 não estão relacionadas com prognóstico no IAM.","B":"Nitrato endovenoso deve ser usado em infarto de ventrículo direito, pois melhora o retorno\nvenoso.","C":"Troponina T e Troponina I são iguais em relação ao diagnóstico de IAM.","D":"O bloqueio do ramo esquerdo está mais relacionado ao infarto sem supra de ST."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-87408","number":"87408","sourceNumber":"87408","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual o objetivo primordial no tratamento do infarto agudo do miocárdio até 12 horas de\nevolução?","options":{"A":"Melhorar a dor com analgésicos potentes.","B":"Restaurar o fluxo na artéria responsável pelo infarto o mais precocemente possível.","C":"Controlar as arritmias, que frequentemente são causas agravantes do infarto.","D":"Iniciar o tratamento de insuficiência cardíaca decorrente de necrose.","E":"Realizar o cateterismo para verificar o grau de disfunção ventricular esquerda."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-81993","number":"81993","sourceNumber":"81993","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 42 anos apresenta-se ao Pronto-Socorro com queixa de dor no peito.\nAlém da isquemia miocárdica, cada uma das seguintes é uma causa potencial de desconforto no\npeito, EXCETO:","options":{"A":"Espasmo esofágico.","B":"Dissecção aórtica.","C":"Herpes-zóster.","D":"Bronquiectasia.","E":"Costocondrite."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-60830","number":"60830","sourceNumber":"60830","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Sobre o exame clínico de pacientes com suspeita diagnóstica de IAM de VD, assinale a\nalternativa INCORRETA:","options":{"A":"Sinal de Kussmaul.","B":"Hipofonese de bulhas.","C":"Ausculta pulmonar sem estertores.","D":"Presença de estase venosa jugular.","E":"Hipotensão arterial acentuada após uso de nitrato."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-46723","number":"46723","sourceNumber":"46723","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente é atendido no PS e internado com diagnóstico de IAM (Infarto Agudo do\nMiocárdio). Após uma semana, paciente apresenta novo episódio de dor de forte intensidade com\nduração de mais de 20 minutos. Que marcador cardíaco seria fundamental para confirmar o\ndiagnóstico de novo IAM?","options":{"A":"CKMB","B":"CPK","C":"DHL","D":"Troponina T","E":"Troponina I"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34131","number":"34131","sourceNumber":"34131","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Ao avaliarmos uma curva enzimática que mostra elevação de troponina e CPK-MB com\nqueda precoce pensamos tratar-se de:","options":{"A":"Reperfusão coronariana.","B":"Infarto Agudo do Miocárdio.","C":"Angina instável.","D":"Embolia pulmonar.","E":"Edema agudo de pulmão."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-26440","number":"26440","sourceNumber":"26440","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Selecione a alternativa em que a dosagem da troponina I seria conclusiva para a lesão\nmiocárdica decorrente de isquemia miocárdica nas primeiras 12 horas após o início do quadro\nclínico. Assuma, em todas as situações, que a troponina não foi dosada previamente:","options":{"A":"Sexo feminino, 56 anos, com dor precordial ventilatório dependente há 2 dias, portadora de\ninsuficiência renal crônica em decorrência de nefropatia hipertensiva, com hipertrofia ventricular\nesquerda ao ECG.","B":"Sexo masculino, 65 anos, com dor precordial típica há uma hora e supra segmento ST em\nderivações antero-septais (V1 e V3).","C":"Sexo feminino, 60 anos, com dor precordial recorrente após infarto agudo do miocárdio ocorrido\nhá 2 dias.","D":"Sexo masculino, 48 anos, diabético, sem alterações eletrocardiográficas, com epigastralgia\nincaracterística.","E":"Sexo feminino, 70 anos, submetida à cirurgia de revascularização miocárdica (2 pontes de\nsafena) há 1 dia, com dor precordial de leve intensidade há cinco horas e sem alterações\neletrocardiográficas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-26612","number":"26612","sourceNumber":"26612","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com a morte dos miócitos, macromoléculas intracelulares passam através da\nmembrana da célula lesada, e o seu\naparecimento na corrente sanguínea significa a ocorrência de\ninfarto do miocárdio. O padrão de elevação é útil para fins diagnósticos sendo correto afirmar,\nexceto:","options":{"A":"A troponina T e I cardioespecíficas não existem nos tecidos extracardíacos e sua presença no\nsoro em qualquer concentração detectável é altamente específica de necrose miocárdica.","B":"Embora a CK-MB tenha sido o marcador sérico mais amplamente utilizado para confirmar o\ndiagnóstico de IAM, sua utilidade clínica é limitada pelo não aparecimento durante a primeira hora\ndo infarto e pela sua falta de especificidade total.","C":"A CK-MB começa a subir cerca de quatro a seis horas após o início dos sinais e sintomas,\natingindo o máximo em aproximadamente 24 horas, e retornando aos níveis basais em três ou\nquatro dias.","D":"A troponina semelhante à CK-MB começa a subir com quatro a seis horas e atinge seus níveis\nmáximos em cerca de 24 horas, entretanto são liberadas continuamente por até 10 a 14.","E":"A mioglobina é um marcador muito sensível de necrose muscular cardíaca sendo importante\npara as decisões diagnósticas e mensurar a\nextensão do infarto."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-26684","number":"26684","sourceNumber":"26684","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O infarto agudo do miocárdio apresenta várias complicações sendo a complicação\nmecânica mais comum:","options":{"A":"rotura do septo interventricular","B":"rotura do músculo papilar","C":"aneurisma ventricular","D":"rotura da parede livre do Ventrículo esquerdo","E":"insuficiência mitral"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-7447","number":"7447","sourceNumber":"7447","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Para um homem idoso, com um infarto do miocárdio pregresso, foi indicado o uso de\nácido acetilsalicílico para prevenção secundária de novas síndromes coronarianas. Dentre as\nseguintes, a dose diária que melhor une as características de prevenção e menor custo é:","options":{"A":"50 mg.","B":"100 mg.","C":"200 mg.","D":"300 mg.","E":"500 mg."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-10007","number":"10007","sourceNumber":"10007","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dos marcadores de lesão miocárdica abaixo, qual leva mais tempo para normalização\ndos seus níveis séricos?","options":{"A":"CKMB massa.","B":"Mioglobina.","C":"CKMB atividade.","D":"Troponina.","E":"Isoforma MB2."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-49293","number":"49293","sourceNumber":"49293","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher, 67 anos de idade, hipertensa e obesa, internada por pé diabético, apresentou\nmal-estar súbito com sudorese e náuseas. Nega\ndor torácica ou tosse. PA: 105 x 70 mmHg deitada.\nPulso radial: 118 bpm rítmico. Temp: 36,7°C. Mucosas coradas, sem estase de jugulares. Aparelho\nrespiratório: MV preservados, sem crépitos, ACV: íctus no 5º EICE, ritmo regular, sem sopros, com\nB4. Abdome: fígado palpável a 3 cm do RCD, elástico, sem outras alterações. Pé esquerdo com\núlcera seca profunda em região plantar e necrose isquêmica de 5 pododáctilo. No momento, lúcida,\nansiosa, sem déficits motores. Exames imediatos: glicemia capilar: 144 mg/dl, saturação de O2 ao\nar ambiente: 91%. O diagnóstico mais provável a ser confirmado é:","options":{"A":"Infarto do miocárdio.","B":"Tromboembolismo pulmonar.","C":"Sepse em instalação.","D":"Acidente vascular encefálico.","E":"Síncope vasomotora."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34966","number":"34966","sourceNumber":"34966","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Na avaliação de risco cardíaco pré-operatório, para cirurgia intraperitoneal de um\npaciente cardiopata, representa o pior risco - ou risco mais elevado de morte cardiovascular\nrelacionada à intervenção - paciente com IAM nos seis meses prévios","options":{"A":"com estenose aórtica importante e idade > 70 anos.","B":"DPOC e idade > 70 anos.","C":"com fibrilação atrial e ritmo de galope à ausculta cardíaca.","D":"DPOC e ECG com extrassístoles ventriculares frequentes .","E":"com insuficiência renal crônica e cirurgia de emergência."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34978","number":"34978","sourceNumber":"34978","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De acordo com as alterações observadas nas derivações do eletrocardiograma,\npode-se, topograficamente, classificar o infarto agudo do\nmiocárdio. Sendo assim, é incorreto\nafirmar que, em relação à localização, a parede miocárdica envolvida é a:","options":{"A":"Lateral: alterações de D1, aVR, V5 e V6.","B":"Anterosseptal: alterações de V1 a V3.","C":"Anterior extenso: alterações de V1 a V6, D1 e aVL.","D":"Inferior: alterações de D2, D3 e aVF.","E":"Posterior (dorsal): alterações de V7, V8, V9 e V10, com ondas R amplas em V1 e V2."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35014","number":"35014","sourceNumber":"35014","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação à isquemia miocárdica, é correto afirmar:","options":{"A":"A função miocárdica pode permanecer deprimida por até 6 horas, após resolução de isquemia\nque se segue à oclusão de uma artéria\ncoronária, por um período de até 15 minutos, na ausência\nde necrose tecidual, fenômeno que é conhecido por miocárdio atordoado.","B":"Miocárdio disfuncionalmente viável pode ser definido como qualquer região que não obteve\nmelhora contrátil após revascularização coronária é chamado de miocárdio hibernado.","C":"Miocárdio que não normaliza a sua função após rápidos períodos de isquemia com duração de\naté 2 minutos é chamado de miocárdio hibernante.","D":"Infarto subendocárdico pode ocorrer quando se mantém moderada isquemia por um período de\ntempo > 24 horas, com o desenvolvimento de miocárdio hibernado.","E":"Atordoamento miocárdico crônico é improvável, ainda que ocorra isquemia reversível de\nrepetição, antes que a função miocárdica\nesteja normalizada. O mecanismo celular de\natordoamento não deve envolver lesão miocárdica, mantendo sensibilidade ao cálcio miofilamentar."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34917","number":"34917","sourceNumber":"34917","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação à abordagem do paciente com dor torácica, segundo as diretrizes da\nAmerican College of Cardiology, e validados no Brasil pelas diretrizes da Sociedade Brasileira de\nCardiologia, é falso afirmar:","options":{"A":"Dor torácica atípica que reduz a probabilidade de representar isquemia miocárdica compreende\nsintomas com as seguintes características: dor pleurítica, localizada primariamente na região\nmediana ou inferior do abdome, dor que pode ser localizada com a ponta de um dedo, dor que\npode ser reproduzida com movimentos ou palpação da parede torácica ou dos braços.","B":"A superfície visceral do pericárdio é insensível à dor, bem como a maior parte da superfície\nparietal. Assim, causas não infecciosa de\npericardite geralmente ocasionam pouca ou nenhuma\ndor.","C":"Dissecções da aorta ascendente tendem a manifestar dor na linha média da parede anterior do\ntórax.","D":"Embolia pulmonar maciça pode causar dor subesternal aguda e persistente, atribuída à\ndistensão da artéria pulmonar. A hipertensão\npulmonar, nesses casos, também pode levar à dor\ntorácica, atribuída à isquemia do VD, porém com características diferentes da dor anginosa\ncausada por obstrução coronária do VE.","E":"Síndrome do pânico pode levar à dor torácica, geralmente associada à dispneia, com duração\nsemelhante à angina pectoris."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34997","number":"34997","sourceNumber":"34997","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O eletrocardiograma (VER IMAGEM) é de um paciente, 70 anos de idade, sexo\nmasculino, que apresenta dor torácica típica\nhá cinco horas. O médico que o atendia obteve outras\ninformações adicionais, como: paciente diabético há 10 anos, hipertenso há 5 anos, tabagista de 20\ncigarros/dia, por 30 anos. Tem peso estimado em torno de 60 kg. Dados vitais na admissão\nmostravam PA: 90 x 50 mmHg, pulso: 110 bpm, FR: 24 inc/min; mucosas coradas. Cabeça e\npescoço: percebe-se estas e jugular a 45°. Tórax: pulmões com MV rude bem distribuído,\nestertores crepitantes em terço inferior de ambos os hemitóraces. ACV: B1 e B2 normais. B3+ em\nFM, SS grau II/VI em FM, irradia para axila. Abdome: sem alterações. É habitual classificar o\npaciente em categorias de risco para desfechos negativos em 30 dias. As classificações/escores\nmais utilizados são Killip-Kimbal e TIMI RISK. Com base nessa informação, pode-se afirmar:","options":{"A":"O paciente tem um infarto com supra de ST-T de parede anterior, Killip-Kimbal III, TIMI RISK 10,\ncom mortalidade em 30 dias, que pode chegar a 35%, e a conduta inicial deve incluir AAS,\ndiuréticos, betabloqueador, nitrato, morfina, oxigênio sob máscara de Venturi e trombólise com\ntenecteplase.","B":"O paciente tem um infarto com supra de ST-T de parede anterosseptal, Killip-Kimbal II, TIMI\nRISK 8, com mortalidade em 30 dias de 35%, e a conduta inicial deve ser feita com AAS,\nmetoprolol venoso 5 mg, nitroglicerina venosa, furosemida venosa (1 mg/kg), morfina venosa,\noxigênio sob máscara de Venturi e angioplastia coronária, pois deve haver oclusão da artéria\ndescendente anterior.","C":"O paciente se encontra em Killip-Kimbal III, TIMI RISK 11, com mortalidade que pode chegar a\n35% em 30 dias. Não há diferença estatística entre trombólise e angioplastia nessa situação,\ndevendo-se optar pela estratégia disponível no centro de saúde. Além disso, o paciente deve\nreceber diuréticos de alça, morfina, nitroglicerina e metoprolol venoso, medidas que\ncomprovadamente reduzem a mortalidade inicial no paciente com infarto com supradesnível de\nST-T.","D":"O paciente se encontra em classe Killip-Kimbal II, TIMI RISK 13, com possibilidade de até 35%\n\nde desfechos negativos em 30 dias, e a melhor conduta deve incluir AAS, diuréticos de alça,\nclopidogrel, oxigênio sob máscara de Venturi e angioplastia imediata.","E":"O paciente se encontra em classe II de Killip-Kimbal, TIMI RISK 12, com alto risco de desfechos\nnegativos em 30 dias, e a melhor\n\nconduta deve ser feita com diuréticos de alça, oxigênio nasal, morfina venosa, nitroglicerina\nvenosa,\ndigital, tenecteplase venosa e, caso não haja sinais de reperfusão, transferência para angioplastia\nda artéria descendente anterior."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/34997.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-13890","number":"13890","sourceNumber":"13890","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, 40 anos de idade, sexo masculino, procura emergência com quadro de\nprecordialgia, com irradiação para ombro esquerdo. Tabagista, sedentário, com histórico familiar de\ncoronariopatia, dislipidêmico. O médico plantonista faz a suspeita de IAM.O ECG mostrou inversão\nda onda T e os marcadores estavam normais. A melhor conduta a ser adotada é:","options":{"A":"Internamento, seriar marcadores e monitorização, apenas.","B":"Uso de trombolíticos.","C":"Uso de AAS e liberar para casa.","D":"Uso de betabloqueador.","E":"Internamento, monitorização, seriar marcadores e uso de AAS."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-281902","number":"281902","sourceNumber":"281902","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Além de esfigmomanômetros e estetoscópios, há vários recursos disponíveis, como\ncardiofrequencímetros e aplicativos de celulares para monitoramento da frequência cardíaca (FC),\nglicosímetros e oxímetros digitais na Reabilitação Cardiovascular. Sendo correto que:","options":{"A":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares favoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e durante o exercício.","B":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e durante o exercício.","C":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, não\né desejável o monitoramento\neletrocardiográfico no repouso e durante o exercício.","D":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e nunca durante o exercício."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-249968","number":"249968","sourceNumber":"249968","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Sobre o risco de trombose de stent em pacientes que foram submetidos à ICP com\nstents convencionais nos primeiros dias e semanas\napós o procedimento, podemos concordar que:","options":{"A":"Uma dupla Antiagregação Plaquetária é recomendada por um semestre.","B":"Os stents convencionais foram reservados, idealmente, para os pacientes com risco muito alto\nde sangramento e que necessitam de um período mais curto (ao menos um mês) de dupla\nAntiagregação.","C":"No Brasil, o stent convencional metálico não é utilizado principalmente em serviços públicos.","D":"Trombose de stent em pacientes com stents metálicos é muito mais raro nos primeiros dias e\nsemanas após o procedimento."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181159","number":"181159","sourceNumber":"181159","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A observação, principalmente em mulheres que tem angina, mas que não apresentam\nobstruções à angiografia coronária, há\nanos chama a atenção é denominada de Síndrome X. Sobre\nisso, assinale a alternativa INCORRETA:","options":{"A":"Ocorre que mesmo sem obstruções nas artérias, estas têm comportamento inadequado para o\nfluxo, tanto as epicárdicas quanto a microcirculação, o que é suficiente para provocar isquemia\nmiocárdica.","B":"Isso não consegue ser detectado por meio da eletrocardiografia de esforço ou pela Cintigrafia de\nPerfusão Miocárdica (CPM), infelizmente.","C":"Essa síndrome é interpretada como uma doença da microcirculação coronária devido a uma\ndisfunção endotelial ou a alterações do tônus vascular, resultando em uma redução da oferta de\noxigênio no nível celular.","D":"Muitas das pessoas com essa síndrome, em verdade, tem placas ateroscleróticas em vários\nsegmentos sem obstrução coronária quando avaliadas por Ultrassom Intravascular (USIV)\ncoronária."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181165","number":"181165","sourceNumber":"181165","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro da abordagem do diagnóstico diferencial da dor torácica e das condições\nassociadas, que podem ser provocadoras ou mesmo\nfatores de alívio da angina, podemos\nconsiderar que os pacientes, especialmente naqueles com angina típica, devem ser consideradas\nas doenças associadas (simultâneas) que possam precipitar angina ?funcional?, isto é, isquemia\nmiocárdica na ausência de obstrução coronariana anatômica significante. Sendo INCORRETA\napenas a seguinte situação:","options":{"A":"Uma redução no consumo de oxigênio pode ser produzida por hipertermia, hipertireoidismo e\nuso de cocaína.","B":"Geralmente, são doenças que causam isquemia miocárdica, por aumentarem o consumo ou por\ndiminuírem a oferta de oxigênio para o miocárdio.","C":"Hipertermia, particularmente se acompanhada de redução de volemia, devido à sudorese ou a\noutras perdas de fluidos, pode precipitar angina, mesmo na ausência de DAC significante.","D":"Hipertireoidismo, com sua taquicardia associada e índice metabólico elevado, aumenta o\nconsumo de oxigênio e pode também reduzir a sua oferta."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181170","number":"181170","sourceNumber":"181170","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"É importante identificar a angina instável, pois está muito relacionada com o evento\ncoronariano agudo. Dentre os achados clínicos, assinale a alternativa INCORRETA:","options":{"A":"Um desconforto repentino, fugaz, ou então contínuo, com duração de várias horas, raramente se\ntrata de angina.","B":"A angina usualmente incide sobre a região retroesternal, tendo irradiação para o pescoço,\nmandíbula, epigástrio ou membros superiores.","C":"Dor localizada nas regiões das articulações condroesternais quase sempre tem origem cardíaca.","D":"Diversas classificações já foram propostas e a mais utilizada é a que divide a dor torácica em\ntrês grupos: típica, atípica e não cardíaca."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181173","number":"181173","sourceNumber":"181173","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro da terapia antiagregante plaquetária podemos considerar diversas intervenções,\nsendo que somente uma das afirmativas abaixo\nlistadas se mostra INCORRETA assinale-a:","options":{"A":"O AAS e o Clopidogrel é a combinação de antiplaquetários orais mais utilizada na terapêutica\nantiplaquetária dupla em nosso meio, por ser eficaz na maioria dos pacientes, ter baixo custo e\nestar amplamente disponível.","B":"O prasugrel tem demostrado menor grau de inibição plaquetária, início de ação mais rápido e\nredução de eventos isquêmicos comparados ao clopidogrel.","C":"O ticagrelor tem demostrado maior grau de inibição plaquetária, início de ação mais rápido e\nredução de eventos isquêmicos comparados ao clopidogrel.","D":"O prasugrel está associado à maior risco de sangramentos, tem maior custo e está aprovado\npara uso apenas em pacientes portadores de\nSíndrome Coronária Aguda."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181184","number":"181184","sourceNumber":"181184","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando realizamos o exame físico em um paciente com suspeita de angina, além dela,\nhá várias situações de dor torácica, ou sintomas manifestados nas regiões habituais de sua\nmanifestação, que possuem outros diagnósticos como relacionados a DAC (Doença\nArteriosclerótica Coronariana). Sobre isso, assinale a alternativa INCORRETA:","options":{"A":"O exame físico é usualmente normal nos pacientes com angina estável.","B":"Entretanto, durante o episódio anginoso, pode fornecer indícios valiosos a respeito da existência\nou não de DAC.","C":"Quando é possível realizar o exame fisico do paciente na vigência de dor, Terceira Bulha (B3),\nQuarta Bulha (B4) ou galope, sopro de regurgitação mitral, desdobramento paradoxal de Segunda\nBulha (B2) e estertoração pulmonar bibasal indicam achados sugestivos e preditores de DAC.","D":"Achados de aterosclerose em outros territórios, como pulsos de membros inferiores diminuídos,\nendurecimento arterial e aneurisma abdominal, diminuem a probabilidade de DAC."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181169","number":"181169","sourceNumber":"181169","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Aterosclerose é uma doença inflamatória crônica de origem multifatorial que ocorre\nem resposta à agressão endotelial, acometendo\nprincipalmente a camada íntima de artérias de\nmédio e grande calibres. Sendo INCORRETO a seu respeito:","options":{"A":"A formação da placa aterosclerótica inicia-se com a agressão ao endotélio vascular devida a\ndiversos fatores de risco como dislipidemia, hipertensão arterial ou tabagismo.","B":"A disfunção endotelial diminui a permeabilidade da íntima às lipoproteínas plasmáticas,\nfavorecendo a retenção das mesmas no espaço subendotelial.","C":"Ocorre que as partículas de LDL sofrem oxidação, causando a exposição de diversos\nneoepitopos e tornando-as imunogênicas.","D":"O depósito de lipoproteínas na parede arterial, processo-chave no início da aterogênese, ocorre\nde maneira proporcional à concentração dessas\nlipoproteínas no plasma."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181199","number":"181199","sourceNumber":"181199","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Fatores como os listados abaixo aumentam também a chance de Doença\nArterosclerotica Coronariana DAC, sendo que após a\nprobabilidade ter sido estimada, ela é\ncategorizada como baixa, intermediaria e alta, de acordo com valores estabelecidos na diretriz\nnacional, somente uma das alternativas não corresponde completamente como correta:","options":{"A":"Tabagismo (mínimo de meio maço ao dia por 5 anos ou 25 maços ao ano).","B":"Colesterol total (> 250 mg/dL).","C":"Glicemia de jejum (> 140 mg/dL).","D":"História familiar são fortemente preditivos."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181201","number":"181201","sourceNumber":"181201","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A variedade e possível gravidade das condições clínicas que se manifestam com dor\ntorácica faz com que seja primordial um diagnóstico rápido e preciso das suas causas. Esta\ndiferenciação entre as doenças que oferecem risco de vida (dor torácica com potencial de\nfatalidade), ou não, é um ponto crítico na tomada de decisão do médico emergencial para definir\nsobre a liberação ou admissão do paciente ao hospital e de iniciar o tratamento imediatamente.\nSendo que a epidemiologia apresenta importante papel nessa tomada de decisão, assinale a\nalternativa INCORRETA:","options":{"A":"A Síndrome Coronariana Aguda (infarto agudo do miocárdico e angina instável) representa\nquase 1/5 das causas de dor torácica nas salas\nde emergência.","B":"A Síndrome Coronariana Aguda por possuir uma significativa morbimortalidade, a abordagem\ninicial desses pacientes é sempre feita no sentido\nde confirmar ou afastar este diagnóstico.","C":"A característica anginosa da dor torácica tem sido identificada como o dado com menor poder\npreditivo de doença coronariana aguda.","D":"O exame físico no contexto da doença coronariana aguda não é expressivo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181203","number":"181203","sourceNumber":"181203","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O Eletrocardiograma (ECG) exerce papel fundamental na avaliação de pacientes com\ndor torácica, tanto pelo seu baixo custo e\nampla disponibilidade como pela relativa simplicidade de\ninterpretação. Sendo somente inadequado o seguinte dado epidemiológico de acordo com a diretriz\natual:","options":{"A":"A incidência de Síndrome Coronariana Aguda nesses pacientes é de cerca de 5%.","B":"Um ECG absolutamente normal é encontrado na minoria dos pacientes que se apresenta com\ndor torácica na sala de emergência.","C":"Diversos estudos têm demonstrado que a sensibilidade do ECG de admissão para Infarto Agudo\ndo Miocárdio varia de 45% a 60% quando se\nutiliza o supradesnível do segmento ST como critério\ndiagnóstico","D":"Metade dos pacientes com Infarto Agudo do Miocárdio não são diagnosticados com um único\nECG realizado à admissão."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181205","number":"181205","sourceNumber":"181205","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Cardiologia Nuclear avalia o coração enfocando os seguintes aspectos de perfusão\nmiocárdica, tendo importante valor como índice prognóstico e epidemiológico, sendo INCORRETO\napenas que avalia:","options":{"A":"A integridade celular.","B":"O metabolismo miocárdio.","C":"A contratilidade miocárdica","D":"A função ventricular global somente."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157628","number":"157628","sourceNumber":"157628","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro do diagnóstico de doença aterosclerótica coronariana subclínica, podemos\nconsiderar como VERDADEIRA a seguinte situação. Assinale-a.","options":{"A":"A identificação apenas de indivíduos sintomáticos, portadores de aterosclerose e, dessa forma,\nsob risco de eventos cardiovasculares\nagudos, como o infarto e morte, é fundamental para se\ninstituírem medidas de tratamento e prevenção secundária.","B":"Diversos algoritmos têm sido criados com base em análises de regressão de estudos\npopulacionais, por meio dos quais a\nidentificação do risco global é substancialmente piorada pela\ncriação de viés.","C":"A estimativa do risco de doença aterosclerótica não apresenta necessidade de ser avaliada pelo\nsomatório do risco causado individualmente ou pelo sinergismo dos reconhecidos fatores de risco\npara doença cardiovascular.","D":"Diante da complexidade dessas interações cardiovasculares, a atribuição intuitiva do risco\nfrequentemente resulta em subestimação ou superestimação dos casos de maior ou menor risco,\nrespectivamente. Para contornar essa dificuldade, diversos algoritmos têm sido criados com base\nem análises de regressão de estudos populacionais, por meio dos quais a identificação do risco\nglobal é substancialmente aprimorada."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157671","number":"157671","sourceNumber":"157671","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro da avaliação do risco de Doença Coronariana Silenciosa em pacientes\ndiabéticos, podemos considerar INADEQUADA a seguinte alternativa a seguir. Assinale-a.","options":{"A":"Em geral, o DM adianta em 15 anos a idade para a ocorrência de DCV.","B":"Homens e mulheres diabéticos tipos 1 e 2, com idades respectivamente superiores a 40 e 50\nanos,\n\ngeralmente apresentam risco de eventos coronarianos > 2% ao ano.","C":"Sexo feminino: risco relativo aumenta 10 vezes.","D":"Idade > 40 anos nos homens e > 50 anos nas mulheres."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157735","number":"157735","sourceNumber":"157735","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Para o correto entendimento do uso da ecocardiográfica sob estresse, na doença\naterosclerótica coronariana crônica, podemos apenas considerar VÁLIDO o contido em apenas\numa das alternativas. Indique-a.","options":{"A":"A ecocardiografia sob estresse é um método não invasivo, estabelecido para a avaliação de\npacientes com DAC obstrutiva suspeita ou conhecida, para a determinação do diagnóstico e\nprognóstico, na avaliação do impacto de terapias de revascularização, na detecção de viabilidade\nmiocárdica, mas não é capaz de auxiliar as decisões terapêuticas.","B":"A ecocardiografia bidimensional permite a avaliação de todos os segmentos miocárdicos do\nventrículo esquerdo com grande resolução\nespacial e temporal, tornando-se a ferramenta ideal para\na avaliação não invasiva da isquemia miocárdica.","C":"A ecocardiografia sob estresse apresenta acurácia ruim para detecção de isquemia miocárdica\ninduzida em pacientes com probabilidade pré-teste intermediária ou alta.","D":"Enquanto a ecocardiografia pela dobutamina e pelo exercício apresenta acurácia diagnóstica\nsemelhante (83 e 85%,respectivamente), a ecocardiografia sob estresse pelo dipiridamol parece\napresentar uma acurácia diagnóstica um pouco muito maior."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157742","number":"157742","sourceNumber":"157742","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A cardiologia nuclear pode ser utilizada para avaliar o coração enfocando os aspectos\nde perfusão miocárdica, integridade celular,\nmetabolismo miocárdico, contratilidade miocárdica e\nfunção ventricular global ou segmentar. Diante disso, marque a opção INCORRETA.","options":{"A":"Estudos de perfusão miocárdica têm importante espaço no diagnóstico da doença isquêmica,\napesar de utilizarem métodos muito invasivos,\ncom muitas reações adversas ao radiotraçador.","B":"A análise da especificidade do método ? usualmente relatada ? é afetada por subestimação\ndecorrente de viés, pois a maioria dos\npacientes com cintilografia de perfusão normal acaba não\nsendo referido para o exame padrão-ouro da coronariográfica.","C":"Pode-se confirmar ou excluir doença arterial coronária com altos valores de sensibilidade e\nespecificidade.","D":"Técnicas atuais de sincronização eletrocardiográfica e de quantificação regional, associadas ao\nestudo tomográfico, permitem objetivar informações concomitantes da perfusão miocárdica e da\nmotilidade parietal e função global do Ventrículo Esquerdo (VE), aumentando, de forma\nsignificativa, o poder diagnóstico do método."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157747","number":"157747","sourceNumber":"157747","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Sobre a utilização do ecocardiograma para separação entre eventos agudos e crônicos\nde insuficiência coronariana, podemos considerar\nINCORRETA uma das opções. Aponte-a.","options":{"A":"Ecocardiográfica transtorácica é um excelente método de triagem em pacientes com DAC\ndurante eventos agudos.","B":"Alterações da motilidade segmentar ocorrem segundos após a oclusão coronariana e são\nmarcadores fidedignos de infarto antigo do miocárdio.","C":"As alterações da motilidade segmentar podem significar isquemia ou infarto antigo somente.","D":"A ecocardiográfica em repouso fornece uma série de informações sobre a função ventricular\nesquerda, como a viabilidade miocárdica, com\nimportantes implicações terapêuticas e prognósticas\napós o IAM."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157751","number":"157751","sourceNumber":"157751","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Angiotomografia Computadorizada das Artérias Coronárias (angio-TC) permite a\navaliação da luz das artérias coronárias de maneira não invasiva. Os equipamentos são capazes de\nadquirir tais imagens com alta qualidade, permitindo a visualização detalhada da luz das artérias\ncoronárias com alta acurácia diagnóstica quando comparada ao cateterismo cardíaco (o\n\npadrão-ouro), porém de maneira não invasiva, rápida e segura. Indique a alternativa que NÃO\ncorresponde a esse caso.","options":{"A":"Uma melhora da qualidade de imagem associada à redução do volume do meio de contraste\ninfundido e à queda drástica na dose de\nradiação utilizada, aumentando ainda mais a segurança do\nmétodo.","B":"O método não apresenta desempenho adequado na avaliação de indivíduos em diversas\nsituações clínicas, com revascularização miocárdica cirúrgica e com stents > 3 mm.","C":"Pacientes estáveis com suspeita de DAC demonstram que não apenas a presença e a extensão\nde estenoses coronárias significativas como\ntambém a presença e a extensão da aterosclerose não\nobstrutiva foram fatores preditores independentes de maior mortalidade.","D":"As principais indicações clínicas do método na avaliação da doença coronária crônica são para\npacientes sintomáticos de risco intermediário, podendo ser utilizado como exame inicial ou quando\nhá testes de isquemia prévios conflitantes ou inconclusivos."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157744","number":"157744","sourceNumber":"157744","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentre o conceito de prevenção, agora não mais primária, o Teste Ergométrico (TE) é o\nmétodo não invasivo utilizado com maior frequência na angina estável, visando à confirmação\ndiagnóstica, entre outros. Para interpretação do TE, devem ser considerados diversos fatores, com\nEXCEÇÃO de um deles. Assinale-o.","options":{"A":"Depressão do segmento ST.","B":"Respostas hemodinâmicas, clínicas e a capacidade funcional.","C":"Dispersão do QT, para diagnóstico de isquemia residual após revascularizações.","D":"Em pacientes já revascularizados, as respostas clínicas relacionadas não se aplicam."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157740","number":"157740","sourceNumber":"157740","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 48 anos de idade, deu entrada em Pronto Atendimento primário\ncom dor torácica típica de início há 1 hora.\nSeu eletrocardiograma demonstra supra de ST nas\nseguintes derivações V1/V2/V3/V4 com 2 mm de altura. Seu diagnóstico inicial é o de Infarto Agudo\ndo Miocárdio, sendo então realizado trombólise química, vez que não estava disponível\nAngioplastia Primária. Porém, o paciente evolui com: dor torácica persistente importante,\nespecialmente associada à sudorese e dispneia, e instabilidade hemodinâmica com queda de sua\npressão Arterial. Frente a esse caso clínico, assinale a alternativa que NÃO pode ser considerada\ncomo adequada.","options":{"A":"A falha da terapia fibrinolítica pode ser avaliada por ECG com supradesnivelamento de ST\npersistente, ou que não reduziu mais que 50% do padrão inicial ou que aumenta.","B":"Não existindo recanalização adequada, deve ser realizada a intervenção coronária percutânea\nde resgate em tempo < 180 minutos após o\nfibrinolítico.","C":"É importante ressaltar que não é seguro a tentativa para transferência para um hospital terciário\nhabilitado.","D":"Angioplastia de resgate é definida como a estratégia de recanalização mecânica realizada\nprecocemente quando a terapia fibrinolítica falha em atingir a reperfusão miocárdica."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157668","number":"157668","sourceNumber":"157668","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Idoso, 68 anos de idade, procura hospital com quadro de dor torácica, provavelmente\ncardiogênica, possuindo algumas características que não são compatíveis com insuficiência\ncoronária. Ao ser realizado eletrocardiograma, foram encontradas alterações de repolarização\nventricular causada por patologias não isquêmicas, que podem ser exemplificados pelas opções\nseguintes, com EXCEÇÃO de uma delas. Indique-a:","options":{"A":"Supradesnivelamento do segmento ST em todas as derivações no caso da pericardite.","B":"Inversão de ondas T no caso de embolia pulmonar.","C":"Aumento de amplitude de ondas no caso de derrame pericárdico.","D":"Ondas T gigantes causadas por hipercalemia."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157670","number":"157670","sourceNumber":"157670","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O Nitroprussiato de sódio é uma medicação de uso bastante comum em situações de\nlesão de órgão-alvo, durante as crises hipertensivas. Em qual das situações a seguir seu potencial\ntóxico se encontra exacerbado?","options":{"A":"Insuficiência Cardíaca.","B":"Edema Agudo de Pulmão.","C":"Insuficiência Hepática.","D":"AVC hemorrágico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157750","number":"157750","sourceNumber":"157750","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 56 anos de idade, foi internado no hospital com quadro de dor\ntorácica, sendo diagnosticado com IAM (Infarto\nAgudo do Miocárdio) com supra do segmento ST na\nparede anterosseptal. O mesmo foi transferido alguns dias depois da Unidade Coronariana para a\nenfermaria de Clínica. Você então é convidado a dar seu parecer para realização da prescrição,\nque agora é uma prescrição de Enfermaria. Sendo assim, qual das alternativas abaixo NÃO é\ncondizente com o caso apresentado.","options":{"A":"Inibidores do sistema renina angiotensina orais reduzem mortalidade após o infarto agudo do\nmiocárdio, com e sem terapias de reperfusão. Seus efeitos benéficos são mais pronunciados em\npacientes acometidos de infarto anterior, congestão pulmonar e fração de ejeção < 40%.","B":"Embora a administração precoce do betabloqueador possa ajudar a prevenir ocorrências de\ntaquiarritmias e reduzir reinfarto, é observado aumento da incidência de choque cardiogênico.","C":"Ticlopidina, antagonista seletivo e irreversível dos receptores de difosfato de adenosine de\nsuperfície de membrana, bloqueia a ligação\ninduzida por difosfato de adenosina do fibrinogênio ao\ncomplexo IIb / IIIa.","D":"Os nitratos são indicados para os pacientes com SCA em decorrência da capacidade de levar à\nvasodilatação coronariana com\n\nconsequente aumento do fluxo sanguíneo coronariano, além de diminuir a capacitância venosa,\nlevando ao aumento da pré-carga ventricular."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134697","number":"134697","sourceNumber":"134697","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Durante o tratamento de emergências cardiovasculares, frequentemente oferecemos\noxigênio aos pacientes, notadamente quadros de\nInfarto Agudo do Miocárdio. Marque a alternativa\nque NÃO pode ser considerada como adequada sobre essa conduta.","options":{"A":"Quando mal indicada a administração de oxigênio por tempo prolongado pode causar\nvasoconstrição sistêmica.","B":"Caso inadequadamente indicado pode levar ao aumento da resistência vascular sistêmica.","C":"É indicada sua administração rotineira em pacientes com saturação de oxigênio < 94%.","D":"É indicada sua administração rotineira em pacientes com saturação de oxigênio < 90%."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134710","number":"134710","sourceNumber":"134710","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considere o caso a seguir. Paciente hipertenso, dislipidêmico e diabético mal\ncontrolado, deu entrada no hospital no dia\nanterior com intensa dor torácica e diaforese.\nSeu ECG demonstrava corrente de lesão em parede anterior, septal e inferior. Como angioplastia,\nestava indisponível e seu tempo de dor era de 10 horas, foi decidido por trombólise química.\nEvolui com melhora discreta da dor, e sua ausculta pulmonar demonstra estertores em ambas\nas bases pulmonares; sua pressão é de 110 x 60 mmHg. Qual das medicações abaixo listadas está\ncontraindicada?","options":{"A":"Atenolol.","B":"Captopril.","C":"Nitroglicerina.","D":"Oxigênio."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111854","number":"111854","sourceNumber":"111854","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente diabético com início de quadro de mal-estar e vômitos de 30 a 30 minutos. Ao\nprocurar seu médico, é realizado Eletrocardiograma que demonstrou supra do segmento ST nas\nderivações D2, D3 e a VF. Podemos, assim, afirmar que:","options":{"A":"está contraindicado nitratos.","B":"ocorreu provavelmente obstrução da Coronariana Direita.","C":"ocorreu provavelmente obstrução da Descendente Anterior.","D":"ocorreu infarto de VD."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111880","number":"111880","sourceNumber":"111880","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O conceito de roubo coronariano pode ser explicado:","options":{"A":"pelo aumento do fluxo para coronariana sadia.","B":"pelo aumento do consumo de O2 pelo miocárdio.","C":"pela taquicardia.","D":"pela piora do tempo diastólico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111914","number":"111914","sourceNumber":"111914","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando avaliamos pacientes com Infarto Agudo do Miocárdio, podemos utilizar\ndiversos escores tanto para conduta quanto\nevolutivos. Um índice clínico interessante baseia-se\nnos achados de disfunção ventricular que são os seguintes:","options":{"A":"ausculta cardíaca com B3, ausculta pulmonar e ECG.","B":"ausculta cardíaca com B4, ausculta pulmonar e ECG.","C":"ausculta cardíaca com B3 ou não, além de ausculta pulmonar.","D":"ausculta pulmonar, apenas."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111918","number":"111918","sourceNumber":"111918","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando iniciamos avaliação de paciente com quadro de dor torácica, além de uma\nanamnese e de um ECG, solicitamos os ditos\nMarcadores de Necrose Miocárdica. Esse, por sua\nvez:","options":{"A":"a Troponina é bastante precoce.","B":"o mais sensível é a mioglobina.","C":"a fração M da Creatinina fosfo quinase relaciona-se mais com tecido cerebral.","D":"a metodologia baseada da atividade da CPK MB mostra-se mais efetiva para diagnóstico."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111879","number":"111879","sourceNumber":"111879","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando avaliamos paciente com quadro de dor torácica, usualmente realizamos\nEletrocardiograma para verificar diversas\npatologias. Ao encontrarmos um supra desnivelamento do\nsegmento ST nas derivações D2, D3 e aVF, podemos supor que:","options":{"A":"ocorreu infarto de Ventrículo Direito.","B":"contraindicamos Nitratos.","C":"a coronariana afetada é a Direita.","D":"todas são afirmativas adequadas."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111892","number":"111892","sourceNumber":"111892","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A utilização de nitratos mostra-se bastante comum, tanto a nível ambulatorial quanto a\nnível de emergência hospitalar, sendo importante a compreensão de seu uso farmacológico. Dessa\nmaneira, podemos afirmar que os mesmos possuem essas propriedades, EXCETO:","options":{"A":"Exaurir o óxido nítrico endotelial.","B":"Melhorar prognóstico do infarto miocárdico.","C":"Venodilatador.","D":"Apresentar absorção cutânea."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-350876","number":"350876","sourceNumber":"350876","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 67 anos, masculino, procurou atendimento na UPA devido quadro de dor\ntorácica iniciado há 2 horas, descreve a dor como sensação de mal-estar, não conseguindo definir\num local específico do peito, associado à sensação de queimação, com irradiação para membro\nsuperior esquerdo e sudorese. Refere que a dor se iniciou após retirar o lixo de seu domicílio,\ncomeçando de maneira leve, porém, devido a piora da dor, procurou atendimento. Faz\nacompanhamento na UBS devido quadro de hipertensão arterial e Diabetes Mellitus, em uso\nirregular de insulina NPH, enalapril e alopurinol. Fuma 01 carteira de cigarros por dia, desde os 15\nanos de idade. Ao exame físico, consciente, orientado, sudoreico, pálido, com fácies de dor, PA\n120x80 mmHg em ambos os membros, FC 90 bpm, f 16 irpm, SpO? 94% em ar ambiente. Ausculta\ncardíaca e pulmonar normais. Abdome flácido. Pulsos periféricos simétricos e palpáveis. Devido\nquadro de dor, foi medicado com morfina venosa, com melhora dos sintomas, além de realizar o\nECG a seguir. Dentro do contexto do caso, assinale o item que demonstra o melhor planejamento\ndiagnóstico nesse momento.","options":{"A":"Solicitar dosagem de CK-MB e mioglobina.","B":"Realizar ECG e dosagem de troponinas de maneira seriada.","C":"Realizar ECG apenas na chegada e solicitar dosagem de TGO, LDH e CK-MB.","D":"Transferir paciente para tratamento invasivo percutâneo (cateterismo) de imediato."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-199702","number":"199702","sourceNumber":"199702","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, 52 anos, piloto de aviação comercial, chega ao consultório para avaliar\nquadro de dor torácica. O quadro iniciou há\n3 meses, se caracteriza por dor retroesternal, em\naperto, que surge geralmente quando está caminhando em esteira, na academia. Necessita parar a\natividade e a dor cede em cerca de 3 minutos. O quadro está estável desde o início. É portador de\nhipertensão arterial sistêmica e tabagista. Usa olmesartana. Tem irmão falecido por infarto aos 50\nanos. Traz radiografia de tórax normal e tem eletrocardiograma com bloqueio de ramo esquerdo.\n\nNo exame físico, a pressão arterial é 140 x 90 mmHg. Qual dos testes abaixo é o mais adequado\npara esse paciente?","options":{"A":"Coronariografia.","B":"Teste ergométrico.","C":"Ecocardiograma de estresse com dipiridamol.","D":"Escore de cálcio pela tomografia computadorizada."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-172990","number":"172990","sourceNumber":"172990","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente feminina, 45 anos, portadora de hipertensão arterial, ex-tabagista, procura\nambulatório com queixa de dor torácica\nprecordial em queimação, que irradia para pescoço. Refere\nque a dor aparece ao esforço moderado nos últimos 3 meses, dura em torno de 5 minutos e\nmelhora espontaneamente. Realizou o seguinte eletrocardiograma: Qual exame deve ser realizado\ncomo próximo passo na investigação?","options":{"A":"Teste ergométrico.","B":"Tomografia coronária com escore de cálcio.","C":"Cateterismo com coronariografia diagnóstica.","D":"Cintilografia miocárdica de estresse farmacológico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/172990.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-150883","number":"150883","sourceNumber":"150883","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 65 anos, com dor precordial que irradia para mandíbula, associada a\nnáuseas e diaforese, de início há 30\nminutos. Filho refere que o paciente já apresentara dor de\ncaráter semelhante há 2 semanas. É portador de hipertensão arterial sistêmica, diabetes mellitus e\ndislipidemia, tomando medicações prescritas de forma irregular. Realizou o seguinte\neletrocardiograma na entrada: (VER IMAGEM) Evoluiu com sinais de hipotensão, congestão\npulmonar e má perfusão periférica. Qual a conduta a ser realizada no momento, além do controle\nhemodinâmico, uso de dupla antiagregação plaquetária e anticoagulante parenteral?","options":{"A":"Trombolítico.","B":"Intervenção coronária percutânea.","C":"Cirurgia de revascularização do miocárdio.","D":"Tratamento clínico e teste provocativo de isquemia."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/150883.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-126996","number":"126996","sourceNumber":"126996","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dona Maria Helena tem 45 anos, é diabética, sedentária, fumante de meio maço de\ncigarros por dia. Apresenta-se assintomática do ponto de vista cardiovascular, exceto pelo baixo\ncondicionamento para exercícios evidenciado em teste de esteira que foi negativo para doença\nisquêmica. O risco cardiovascular da paciente, pelo critério de Framingham, é de 13,1%. Que nível\nde prevenção estará sendo aplicado a esta paciente se for considerada terapia com aspirina em\nbaixas doses (75-100 mg por dia)?","options":{"A":"Primária.","B":"Secundária.","C":"Terciária.","D":"Quartenária."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-102173","number":"102173","sourceNumber":"102173","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, feminina, 58 anos, diabética, comparece em consulta de seguimento com seu\nmédico de família e comunidade. Faz uso contínuo de hipoglicemiante oral de forma regular.\n\nTrouxe exames solicitados na última consulta: glicemia jejum 168 mg/dl, hemoglobina glicada\n8,2%, triglicérides 400 mg/dl, Colesterol total 230 mg/dl, HDL 20 mg/dl. Que conduta deve ser\ntomada na situação acima?","options":{"A":"Prescrever fibrato.","B":"Prescrever estatina.","C":"Prescrever fibrato e estatina.","D":"Prescrever fibrato, estatina e ácido acetilsalicílico."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-81249","number":"81249","sourceNumber":"81249","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, diabético e hipertenso, comparece ao\n\npronto-socorro com uma hora de dor precordial constritiva com irradiação para o membro superior\nesquerdo. Encontra-se ansioso e sudoreico. Realizado ECG com imagem. (VER IMAGEM) Qual o\nmelhor tipo de tratamento para esse paciente?","options":{"A":"Cardioversão elétrica, sob sedação.","B":"Intervenção percutânea coronariana imediata.","C":"Administração de ativador de plasminogênio tecidual.","D":"Amiodarona em bolus, seguida de administração intravenosa contínua."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/81249.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-65777","number":"65777","sourceNumber":"65777","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, diabético e hipertenso, vem se queixando de dor\nprecordial em aperto, com irradiação para o membro superior esquerdo, quando faz grandes\nesforços. Ao exame físico: PA de 150/100 mmHg, ausculta cardíaca com presença de quarta\nbulha. O ECG foi o primeiro exame complementar realizado e está exposto ao lado (VER\nIMAGEM). Qual o próximo exame a ser solicitado?","options":{"A":"Teste ergométrico.","B":"Cateterismo cardíaco.","C":"Cintilografia do miocárdio.","D":"Ecocardiograma sob estresse.","E":"Ecocardiograma convencional."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/65777.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-51199","number":"51199","sourceNumber":"51199","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 50 anos, obeso, tabagista e sedentário, realizou teste ergométrico\nprévio interrompido no estágio II por fadiga e dor\ntorácica. Que outro achado neste teste indicaria\num sinal de prognóstico adverso importante?","options":{"A":"Taquicardia sinusal após o esforço.","B":"Redução da pressão arterial durante o esforço.","C":"Aumento da pressão arterial durante o esforço.","D":"Depressão de até 0,03 milivolt do segmento ST."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-51236","number":"51236","sourceNumber":"51236","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 38 anos, motorista, negro, procura seu médico de família para avaliação de\nrotina. Relata etilismo, tabagismo, sedentarismo e alimentação rica em gordura animal. Ao exame:\n98 Kg; 1,65 metros de altura; PA 165 x 95 mmHg (1° medida), PA: 160/95 mmHg (2° medida);\ncintura abdominal 98 cm. Ausculta cardíaca e pulmonar sem alterações. Exames complementares:\nColesterol total: 200 mg/dl; HDL: 50 mg/dl; triglicérides: 260 mg/dl; glicemia de jejum: 98 mg/dl;\ncreatinina: 0,8 mg/dl; sumário de urina sem alterações; ácido úrico 8,2 mg/dl. Raio X de tórax e\nECG de repouso sem alterações. Segundo a escala de Framingham, qual o risco cardiovascular\nestimado para esse paciente?","options":{"A":"Risco médio, ou entre 15 e 20% em 10 anos.","B":"Risco baixo, ou menos de 10% em 10 anos.","C":"Risco médio, entre 10 e 15% em 10 anos.","D":"Risco alto, ou mais de 20% em 10 anos."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-141579","number":"141579","sourceNumber":"141579","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual o principal elemento para o diagnóstico da síndrome coronariana aguda?","options":{"A":"CK-MB.","B":"Troponina.","C":"História clínica.","D":"Eletrocardiograma."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-45382","number":"45382","sourceNumber":"45382","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, de 57 anos, fumante, e portador de hipertensão arterial sistêmica chega ao\npronto-socorro com forte dor torácica central opressiva e sudorese. Um eletrocardiograma mostra\ninversão de onda T das derivações V1 a V4 e avaliação laboratorial mostra troponina elevada. Qual\ndas medicações abaixo deve ser evitada nesse paciente?","options":{"A":"Aspirina.","B":"Clopidogrel.","C":"Metoprolol.","D":"Alteplase (t-PA).","E":"Morfina."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-36982","number":"36982","sourceNumber":"36982","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 54 anos comparece à emergência com dor retroesternal em aperto com\nirradiação para o pescoço, sudorese e náusea há oito horas. É hipertenso, tabagista, tem história\nde LDL elevado e índice de massa corporal de 35 kg/m². Seu ECG mostra inversão de onda T de\nV1 a V4. Seus exames mostram troponina elevada. Qual dos itens abaixo NÃO ESTÁ INCLUÍDO\nnas estratégias terapêuticas para este caso?","options":{"A":"Enoxaparina.","B":"Clopidogrel.","C":"Estreptoquinase.","D":"Angioplastia coronariana."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-37383","number":"37383","sourceNumber":"37383","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação à melhor conduta nas síndromes coronarianas agudas com\nsupradesnivelamento do segmento ST, podemos afirmar que:","options":{"A":"A estratégia de reperfusão imediata tem benefícios comprovados até as 12h iniciais do início do\nIAM na grande maioria dos casos.","B":"Em relação à estratégia de reperfusão, o uso de fibrinolíticos é tão eficaz quanto a angioplastia\ncom stents após as 3h iniciais do evento agudo.","C":"A menstruação presente é contraindicação absoluta ao uso de fibrinolíticos e da heparina.","D":"A heparinização plena é uma das estratégias\nresponsáveis pela reperfusão da artéria ?culpada?.","E":"O uso de aspirina na fase aguda tem pouco ou nenhum impacto sobre a mortalidade final."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-37393","number":"37393","sourceNumber":"37393","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considere o quadro clínico e escolha a alternativa correta: Francisco, 58 anos, chegou\nà emergência com história de dor precordial\nintensa com início há 2 horas, com irradiação para o\nbraço esquerdo, acompanhada de sudorese e palidez. Relata antecedentes de hipertensão arterial\nsistêmica e tabagismo há 35 anos. Faz uso regular de captopril e sinvastatina. O exame físico\nmostra paciente ansioso, pálido, com sudorese fria e taquicárdico. O restante sem particularidade.\nPA = 140 x 90 mmHg, FC = 115 bpm, T = 37°C, FR = 24 irpm. Eletrocardiograma realizado na\nchegada à emergência:(VER IMAGEM)","options":{"A":"O ECG mostra IAM (Infarto Agudo do Miocárdio) anterior extenso, devendo ser prescritos AAS,\nnitrato sublingual, betabloqueador e oxigênio e solicitadas enzimas cardíacas, hemograma\ncompleto, bioquímica, perfil lipídico, TAP e TPTA. Está indicado realização de cateterismo cardíaco\ncom angioplastia OU trombolítico, com posterior admissão do paciente em UTI.","B":"O ECG mostra IAM (Infarto Agudo do Miocárdio) inferior, devendo ser prescritos AAS, nitrato\nsublingual, betabloqueador e oxigênio e solicitadas enzimas cardíacas, hemograma completo,\nbioquímica, perfil lipídico, TAP e TPTA. Está indicado realização de cateterismo cardíaco com\nangioplastia OU trombolítico, com posterior admissão do paciente em UTI.","C":"O ECG mostra IAM (Infarto Agudo do Miocárdio) anterior, devendo ser prescritos AAS, nitrato\nsublingual, betabloqueador e oxigênio e solicitadas enzimas cardíacas, hemograma completo,\nbioquímica, perfil lipídico, TAP e TPTA. Está indicado realização de cateterismo cardíaco com\nangioplastia OU trombolítico, com posterior admissão do paciente em UTI.","D":"O ECG mostra IAM (Infarto Agudo do Miocárdio) lateral, devendo ser prescritos AAS, nitrato\nsublingual, betabloqueador e oxigênio e solicitadas enzimas cardíacas, hemograma completo,\nbioquímica, perfil lipídico, TAP e TPTA. Está indicado realização de cateterismo cardíaco com\nangioplastia OU trombolítico, com posterior admissão do paciente em UTI.","E":"O ECG mostra IAM (Infarto Agudo do Miocárdio) anterolateral, devendo ser prescritos AAS,\nnitrato sublingual, betabloqueador e oxigênio e\nsolicitadas enzimas cardíacas, hemograma\ncompleto, bioquímica, perfil lipídico, TAP e TPTA. Está indicado realização de cateterismo cardíaco\n\ncom angioplastia OU trombolítico, com posterior admissão do paciente em UTI."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/37393.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-9051","number":"9051","sourceNumber":"9051","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação ao infarto agudo do miocárdio (IAM), é CORRETO afirmar:","options":{"A":"A taxa de mortalidade precoce do IAM é de 30%, e mais da metade dessas mortes ocorrem\napós a chegada do paciente ao hospital","B":"Ao contrário da angina instável, a dor do IAM nunca começa com o paciente em repouso","C":"Além do IAM, cirurgia cardíaca, miocardite e cardioversão elétrica podem elevar a CKMB","D":"No IAM sem elevação de ST, o tratamento por fibrinólise é formalmente indicado, pois existem\nevidências claras na literatura do seu benefício."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-349738","number":"349738","sourceNumber":"349738","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação ao uso de trombolíticos em paciente com infarto agudo do miocárdio com\nsupra de ST no eletrocardiograma, é considerado(a) contraindicação absoluta","options":{"A":"uso crônico de AAS 100 mg diário.","B":"trauma cranioencefálico importante nos últimos 3 meses.","C":"histórico de úlcera péptica mesmo sem evidência de sangramento ativo.","D":"acidente vascular encefálico isquêmico há 1 ano.","E":"gestação."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-349712","number":"349712","sourceNumber":"349712","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A boa prática médica está associada à promoção da saúde, além de práticas\nterapêuticas e diagnósticas. A atividade\nfísica vem se tornando o centro da promoção à saúde em\ndecorrência de seus inúmeros benefícios de curto, médio e longo prazo. Assinale a alternativa que\napresenta a quantidade recomendada de atividade física para pessoas entre 6 e 17 anos.","options":{"A":"Realização de atividade física variada, envolvendo atividades lúdicas e recreativas.","B":"Realização de 60 minutos de atividades físicas moderadas a vigorosas por dia, sendo estas\nadequadas para cada idade.","C":"Realização, no máximo, de 150 minutos por semana de atividades físicas vigorosas, devido ao\nrisco de acidentes.","D":"Realização de 40 minutos de atividades físicas de reforço muscular por dia, sendo estas\nadequadas para cada idade.","E":"Realização de 60 minutos de atividades físicas moderadas a vigorosas, no máximo 3x por\nsemana devido ao risco de lesões."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-337517","number":"337517","sourceNumber":"337517","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 80 anos foi encontrado em rua pública, e testemunhas disseram que ele\nestava caminhando quando subitamente caiu no chão, perdendo a consciência. No hospital, foi\nrealizado eletrocardiograma mostrado a seguir. Ao exame físico, sua pressão arterial era de\n80x40mmHg, havia estertores pulmonares em todos os segmentos pulmonares com turgência\njugular; sua glicemia estava normal. Durante seu atendimento, o paciente demonstrou ritmo\ncardíaco no monitor. Com base nos conhecimentos clínicos e nos eletrocardiogramas\napresentados, julgue o item a seguir: O eletrocardiograma número 1 denota um eletrocardiograma\ncom supradesnivelamento do segmento ST, compatível com infarto agudo do miocárdio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/337517.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-322165","number":"322165","sourceNumber":"322165","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma mulher de 78 anos procura atendimento médico de urgência com queixa de dor no\nestômago e náuseas há aproximadamente 2 horas, obtendo-se o seguinte ECG da paciente: Nesse\ncaso, considerando as informações apresentadas, é correto afirmar que","options":{"A":"se trata de uma colecistite aguda, e a paciente deve ser internada aos cuidados da cirurgia\ngeral.","B":"uma opção de reperfusão coronariana deve ser indicada imediatamente.","C":"o uso de morfina e nitrato está indicado.","D":"uma endoscopia digestiva alta é prioritária.","E":"a paciente deve ser encaminhada para avaliação ambulatorial com um cardiologista."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/322165.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-284272","number":"284272","sourceNumber":"284272","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. Trata-se de um infarto agudo do miocárdio\nsem supra de ST.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-284273","number":"284273","sourceNumber":"284273","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. A classificação da apresentação clínica é\nKillip 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-284274","number":"284274","sourceNumber":"284274","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. A trombólise é contraindicada para o\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-284276","number":"284276","sourceNumber":"284276","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de\ndor torácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. Está indicada a suplementação de oxigênio\npor cateter nasal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261228","number":"261228","sourceNumber":"261228","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre\n(38,5ºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente, o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. Trata-se provavelmente de\npericardite aguda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261228.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261229","number":"261229","sourceNumber":"261229","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. Em geral, início súbito dos\nsintomas é associado ao pior prognóstico em relação a início subagudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261229.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261230","number":"261230","sourceNumber":"261230","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. É comum associação dessa\npatologia com edema agudo de pulmão e, consequentemente, insuficiência ventricular esquerda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261230.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261231","number":"261231","sourceNumber":"261231","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. É necessário internar o\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261231.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261232","number":"261232","sourceNumber":"261232","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente com história de dor torácica aos esforços comparece à consulta por estar\nmais cansado do que o normal. Refere que vem\napresentando ortopneia e dispneia paroxística\nnoturna. Foram realizados investigação laboratorial, Holter, ecocardiograma e cateterismo cardíaco.\nO ecocardiograma e o cateterismo estão representados a seguir. Tendo em vista esse caso clínico,\nas imagens apresentadas e os conhecimentos médicos correlatos, julgue o item a seguir. Na\nimagem do cateterismo, observa-se lesão em artéria descendente anterior.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261232.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261235","number":"261235","sourceNumber":"261235","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade, com miocardiopatia isquêmica dilatada com fração\nde ejeção prévia de 30%, encaminha-se à\nemergência com dor torácica em aperto há sete horas,\ndispneia importante e sudorese. Foram solicitados exames laboratoriais que demonstram\nhemograma normal, função renal e eletrólitos normais. Seu peptídeo natriurético cerebral (BNP) era\nde 300 pg/mL (valor de referência até 150 pg/dL). Solicitou-se, então o eletrocardiograma\nrepresentado na figura a seguir. Considerando esse caso clínico, a figura apresentada e os\nconhecimentos médicos correlatos, julgue o item a seguir. O paciente apresenta-se com infarto\nagudo do miocárdio anterior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261235.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-261236","number":"261236","sourceNumber":"261236","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 35 anos de idade, com miocardiopatia isquêmica dilatada com fração\nde ejeção prévia de 30%, encaminha-se à\nemergência com dor torácica em aperto há sete horas,\ndispneia importante e sudorese. Foram solicitados exames laboratoriais que demonstram\nhemograma normal, função renal e eletrólitos normais. Seu peptídeo natriurético cerebral (BNP) era\nde 300 pg/mL (valor de referência até 150 pg/dL). Solicitou-se, então o eletrocardiograma\nrepresentado na figura a seguir. Considerando esse caso clínico, a figura apresentada e os\nconhecimentos médicos correlatos, julgue o item a seguir. Ao avaliar o valor de BNP para esse\npaciente, pode-se afirmar que ele está com insuficiência cardíaca descompensada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/261236.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-274378","number":"274378","sourceNumber":"274378","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A pericardite é uma doença inflamatória de etiologia autoimune ou infecciosa que\nacomete o pericárdio e faz parte do\ndiagnóstico diferencial de dor torácica. Atualmente, cerca de\n1% dos casos de infarto agudo do miocárdio que têm elevação do segmento ST são, na verdade,\npericardite. Sobre esse tema, é correto afirmar que","options":{"A":"a pericardite bacteriana é a forma infecciosa mais comum.","B":"o citomegalovírus é um agente comum em imunodeprimidos e soropositivos.","C":"A síndrome de Marfan é uma causa autoimune comum.","D":"a forma que ocorre pós-infarto do miocárdio deve ser aventada em sintomas que ocorrem após 3\nsemanas do evento.","E":"a dosagem de BNP e NT-proBNP deve ser rotineira porque indica o prognóstico da doença."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-255667","number":"255667","sourceNumber":"255667","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente com angina instável foi submetido a cateterismo cardíaco, que demonstrou\nlesões de 80% em artéria descendente\nanterior proximal, coronária direita de 70% em terço medial\ne lesão de 80% em circunflexa. Foi submetido à cirurgia de revascularização do miocárdio com\ncirculação extracorpórea. O cirurgião utilizou duas pontes de safena e uma mamária, sendo esta\npor técnica pediculada. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Geralmente a técnica pediculada causa mais trauma pleural comparada à\nesqueletizada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-255668","number":"255668","sourceNumber":"255668","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente com angina instável foi submetido a cateterismo cardíaco, que demonstrou\nlesões de 80% em artéria descendente\nanterior proximal, coronária direita de 70% em terço medial\ne lesão de 80% em circunflexa. Foi submetido à cirurgia de revascularização do miocárdio com\ncirculação extracorpórea. O cirurgião utilizou duas pontes de safena e uma mamária, sendo esta\npor técnica pediculada. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em geral, nos pacientes com ponte de safena, no primeiro mês, o principal\nmecanismo de perda do enxerto é trombose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-255691","number":"255691","sourceNumber":"255691","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 35 anos de idade chega ao pronto-socorro com dor torácica em aperto,\nirradiada para membro superior esquerdo há duas\nhoras. Foi realizado um eletrocardiograma de\nrepouso. Acerca desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\nconsiderando o traçado eletrocardiográfico apresentado, julgue o item a seguir. Esse paciente é um\ncandidato a terapia de reperfusão e, com base nas diretrizes da ESC, a trombólise é a opção de\nescolha.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/255691.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-255693","number":"255693","sourceNumber":"255693","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 35 anos de idade chega ao pronto-socorro com dor torácica em aperto,\nirradiada para membro superior esquerdo há duas horas. Foi realizado um eletrocardiograma de\nrepouso. Acerca desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\nconsiderando o traçado eletrocardiográfico apresentado, julgue o item a seguir. Provavelmente a\nlesão culpada é a coronária direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/255693.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-255694","number":"255694","sourceNumber":"255694","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 35 anos de idade chega ao pronto-socorro com dor torácica em aperto,\nirradiada para membro superior esquerdo há duas\nhoras. Foi realizado um eletrocardiograma de\nrepouso. Acerca desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\nconsiderando o traçado eletrocardiográfico apresentado, julgue o item a seguir. Embora\ntromboaspiração de rotina seja classe III, pelas diretrizes da ESC, em alguns cenários, ela deve ser\nconsiderada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/255694.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-239365","number":"239365","sourceNumber":"239365","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. As características da dor torácica apresentadas pela paciente resultam em\nbaixo valor preditivo positivo para dor torácica por etiologia cardíaca.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-196643","number":"196643","sourceNumber":"196643","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 65 anos de idade, diabético, vem apresentando dor torácica de forte\nintensidade há 30 dias. Foi então submetido a um cateterismo cardíaco, demonstrando lesão grave\nem artéria descendente anterior, lesão grave em artéria descendente posterior e lesão grave em\nprimeiro ramo marginal. Em relação a esse caso clínico e aos conhecimentos médicos correlatos,\njulgue o item a seguir. Se o caso foi passível de cirurgia, pode-se utilizar a artéria radial como\num\ndos enxertos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-214514","number":"214514","sourceNumber":"214514","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Certo paciente de 52 anos de idade compareceu ao pronto atendimento levado pela\nfamília, relatando apresentar, há cerca de 30\nminutos, desconforto precordial em \"aperto\",\nsensação de ansiedade, taquicardia e sudorese. Refere que os sontomas se inciaram após uma\ndiscussão exacerbada com os familiares a respeito de \"opiniões políticas\". Relata quadro prévio de\ndiabetes mellitus tipo 2 (DM2) e hipertensão arterial sistêmica (HAS), em uso de anti-hipertensivos\ne hipoglicemiantes orais. A esposa informa que o paciente faz uso de inibidores seletivos de\nrecaptação de seratonina (ISRS) para controle de transtorno de ansiedade. Nega uso de outras\nmedicações e alergias medicamentosas. Nega presença de outras comorbidades\nneuropsiquiátricas prévias ou atuais. Nega histórico prévio de traumas ou de hemorragias por\nquaisquer vias. Na avaliação inicial, o paciente mostra-se em estado geral regular, com fácies de\ndor, sem particularidades à ausculta pulmonar e cardíaca. PA=190 mmHg x 120 mmHg; FC=112\nbpm; Sat=96%; e FR=28 irpm. A respeito desse caso clínico e considerando os conhecimentos\nmédicos correlatos, julgue o item a seguir. O paciente mencionado apresenta pelo menos três\nfatores de risco para a presença de aterosclerose (principal fator de risco para doenças isquêmicas\ndo miocárdio) e deve ser avaliada a possibilidade de uma sindrome coronariana aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-214522","number":"214522","sourceNumber":"214522","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Certo paciente de 52 anos de idade compareceu ao pronto atendimento levado pela\nfamília, relatando apresentar, há cerca de 30\nminutos, desconforto precordial em \"aperto\",\nsensação de ansiedade, taquicardia e sudorese. Refere que os sintomas se inciaram após uma\ndiscussão exacerbada com os familiares a respeito de \"opiniões políticas\". Relata quadro prévio de\ndiabetes mellitus tipo 2 (DM2) e hipertensão arterial sistêmica (HAS), em uso de anti-hipertensivos\ne hipoglicemiantes orais. A esposa informa que o paciente faz uso de inibidores seletivos de\nrecaptação de seratonina (ISRS) para controle de transtorno de ansiedade. Nega uso de outras\nmedicações e alergias medicamentosas. Nega presença de outras comorbidades\nneuropsiquiátricas prévias ou atuais. Nega histórico prévio de traumas ou de hemorragias por\nquaisquer vias. Na avaliação inicial, o paciente mostra-se em estado geral regular, com fácies de\ndor, sem particularidades à ausculta pulmonar e cardíaca. PA=190 mmHg x 120 mmHg; FC=112\nbpm; Sat=96%; e FR=28 irpm. A respeito desse caso clínico e considerando os conhecimentos\nmédicos correlatos, julgue o item a seguir. Pacientes com quadro de DM2 apresentam maior\nincidência de infarto silencioso e IAM com sintomas atípicos do que pacientes não portadores de\nDM2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-152122","number":"152122","sourceNumber":"152122","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 55 anos de idade, hipertenso e diabético, chega ao\npronto-socorro com intensa dor torácica, em\naperto, irradiada para membro superior direito. Relata\ndispneia concomitante. Ao exame físico, observava-se bulhas normofonéticas, ritmo regular. Na\nausculta, havia estertores em bases pulmonares bilaterais Sat O2 = 90% com óculos nasal\ncomplementar. Foi realizado eletrocardiograma que demonstrou supra de ST em D2, D3 e AVF,\nsendo que o supra D3 é maior que o de D2, e D1 é isoelétrico. Com base neste caso clínico, e\nconsiderando os conhecimentos médicos a ele relacionados, julgue o item a seguir. A artéria\nacometida provavelmente é a artéria coronária direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-131848","number":"131848","sourceNumber":"131848","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De acordo com a Sociedade Brasileira de Cardiologia, no que se refere ao tratamento\ndo Infarto Agudo do Miocárdio (IAM) com desvio\nde segmento ST, assinale a alternativa\nCORRETA:","options":{"A":"A suplementação de oxigênio somente está recomendada aos pacientes que apresentarem\nsaturação sanguínea de oxigênio inferior a 86%,\nmedida por oximetria de pulso.","B":"O analgésico de escolha no IAM é o sulfato de morfina, exceto em pacientes que apresentarem\nIAM complicado por edema agudo de pulmão.","C":"O uso de nitratos está indicado especialmente aos pacientes que apresentam bradicardia,\ntaquicardia, pressão arterial sistólica abaixo de 90\nmmHg e àqueles que apresentaram queda de\nmais de 30 mmHg no respectivo nível pressórico basal.","D":"Os betabloqueadores aumentam a perfusão miocárdica bem como a função cardíaca e estão\nindicados, sobretudo, aos pacientes com doença vascular periférica, com bloqueio atrioventricular\nde terceiro grau, com doença pulmonar obstrutiva crônica, e aos que apresentarem intervalo PR\nmaior que 0,24 segundo no eletrocardiograma.","E":"Os antiagregantes plaquetários apresentam benefícios no IAM, sendo que o AAS deve ser\nadministrado aos pacientes o mais rápido possível após o diagnóstico provável, na dose de 160 mg\na 325 mg, e a terapia deve ser mantida sem interrupção, na dose diária de 100 mg ao dia."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134986","number":"134986","sourceNumber":"134986","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de vinte anos de idade foi internado no pronto-socorro de um hospital,\nonde recebeu o diagnóstico de infarto agudo do\nmiocárdio. Os familiares negaram ocorrência de\ndoenças prévias no paciente. Durante o exame físico, o paciente apresentou quadro de ansiedade\ne agitação psicomotora, dilatação das pupilas com o emprego de reflexo fotomotor, taquicardia e\ntaquipneia. Além de receber tratamento, o paciente foi submetido à investigação de abuso de\ndrogas. Julgue o item subsequente, relativo a esse caso clínico. A dilatação das pupilas devido ao\nefeito fotomotor indica uso de opioides.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-134995","number":"134995","sourceNumber":"134995","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de vinte anos de idade foi internado no pronto-socorro de um hospital,\nonde recebeu o diagnóstico de infarto agudo do\nmiocárdio. Os familiares negaram ocorrência de\ndoenças prévias no paciente. Durante o exame físico, o paciente apresentou quadro de ansiedade\ne agitação psicomotora, dilatação das pupilas com o emprego de reflexo foto motor, taquicardia e\ntaquipneia. Além de receber tratamento, o paciente foi submetido à investigação de abuso de\ndrogas. Julgue o item subsequente, relativo a esse caso clínico. Nesse caso, a detecção de uso de\ndrogas por meio do exame de urina pressupõe uso recente dessas drogas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-140746","number":"140746","sourceNumber":"140746","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma paciente de sessenta e três anos de idade foi atendida no setor de emergência de\num hospital terciário apresentando dor\nretroesternal, em aperto, de forte intensidade, irradiada para\na região epigástrica e para o ombro esquerdo, associada a náuseas e um episódio de vômito;\nsintomas que haviam iniciado, segundo a paciente, cerca de seis horas antes do atendimento no\nhospital, durante uma discussão com o seu cônjuge. Ela relatou, ainda, ter hipertensão arterial, em\nuso irregular de anti-hipertensivo, colesterol elevado, e que era tabagista crônico. No exame\nclínico,\nconstatou-se que a paciente estava consciente, orientada, eupneica, ansiosa, e apresentou os\nseguintes dados clínicos: pressão arterial de 148 mmHg x 92 mmHg (em ambos os membros\nsuperiores, em posição de decúbio dorsal); frequência cardíaca de 98 bpm; frequência respiratória\nde 27 irpm, com saturação de oxigênio à oximetria de pulso a 94%; ritmo cardíaco regular em três\ntempos, à custa de quarta bulha, sem sopros; pulsos arteriais palpáveis e simétricos; pulmões\nlimpos; abdome livre; e extremidades sem cianose ou edema. Os resultados do eletrocardiograma\nrevelaram ritmo sinusal, com frequência ventricular média de 95 spm (sístoles/minuto); eixo elétrico\ndo complexo QRS = +30°; presença de raras e isoladas extrassístoles ventriculares monomórficas;\nsupradesnivelamento do segmento ST (de 5 mm), com convexidade para baixo, associado à onda\nT negativa nas derivações D2, D3 e aVF, onde também foi observada onda Q profunda e alargada.\nOs resultados da radiografia de tórax (projeções PA e perfil, com esôfago constrastado) mostraram\nárea cardíaca normal, pulmões sem anormalidades e ectasia leve da aorta torácica. A dosagem de\ntroponina T sanguínea foi de 1,8 ng/mL (valor de referência < 0,1 ng/mL). Com base nesse caso\nclínico, julgue o item a seguir. O principal diagnóstico para a paciente desse caso clínico é de\nangina instável.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-140748","number":"140748","sourceNumber":"140748","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma paciente de sessenta e três anos de idade foi atendida no setor de emergência de\num hospital terciário apresentando dor\nretroesternal, em aperto, de forte intensidade, irradiada para\na região epigástrica e para o ombro esquerdo, associada a náuseas e um episódio de vômito;\nsintomas que haviam iniciado, segundo a paciente, cerca de seis horas antes do atendimento no\nhospital, durante uma discussão com o seu cônjuge. Ela relatou, ainda, ter hipertensão arterial, em\nuso irregular de anti-hipertensivo, colesterol elevado, e que era tabagista crônico. No exame\nclínico,\nconstatou-se que a paciente estava consciente, orientada, eupneica, ansiosa, e apresentou os\nseguintes dados clínicos: pressão arterial de 148 mmHg x 92 mmHg (em ambos os membros\nsuperiores, em posição de decúbio dorsal); frequência cardíaca de 98 bpm; frequência respiratória\nde 27 irpm, com saturação de oxigênio à oximetria de pulso a 94%; ritmo cardíaco regular em três\ntempos, à custa de quarta bulha, sem sopros; pulsos arteriais palpáveis e simétricos; pulmões\nlimpos; abdome livre; e extremidades sem cianose ou edema. Os resultados do eletrocardiograma\nrevelaram ritmo sinusal, com frequência ventricular média de 95 spm (sístoles/minuto); eixo elétrico\ndo complexo QRS = +30°; presença de raras e isoladas extrassístoles ventriculares monomórficas;\nsupradesnivelamento do segmento ST (de 5 mm), com convexidade para baixo, associado à onda\nT negativa nas derivações D2, D3 e aVF, onde também foi observada onda Q profunda e alargada.\nOs resultados da radiografia de tórax (projeções PA e perfil, com esôfago constrastado) mostraram\nárea cardíaca normal, pulmões sem anormalidades e ectasia leve da aorta torácica. A dosagem de\ntroponina T sanguínea foi de 1,8 ng/mL (valor de referência < 0,1 ng/mL). Com base nesse caso\nclínico, julgue o item a seguir. Nesse caso clínico, como foi ultrapassada a \"janela terapêutica\" e\nnão há evidências de necrose miocárdica, são contraindicados tanto o uso de medicamentos\ntrombolíticos como a realização de angioplastia coronariana transluminal percutânea primária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-140723","number":"140723","sourceNumber":"140723","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Durante consulta, um paciente de cinquenta e sete anos de idade, com histórico de\nhipertensão arterial sistêmica e tabagismo, reportou que, havia uma semana, vinha tendo episódios\nde dor retroesternal opressiva, de moderada intensidade, com irradiação para membro superior\nesquerdo. A dor geralmente surgia durante pequenos esforços habituais com o banho. Ele\nacrescentou que, no dia anterior à consulta, tivera, em momento de repouso, dois episódios de dor\ncom as mesmas características, que cessaram em torno de vinte minutos. Na consulta, foi\ndetectado que o paciente apresentava precordialgia que já persistia havia três horas com as\nmesmas características descritas anteriormente. No exame físico, constatou-se que o paciente\nestava com saturação de oxigênio de 93% (em ar ambiente), pressão arterial de 136 mmHg x 74\nmmHg (aferida por três vezes), frequência cardíaca de 76 bpm e ritmo cardíaco regular em dois\ntempos sem sopros. O restante do exame físico foi normal. Os resultados da dosagem de CK-MB\nmassa e da troponina, no momento de admissão no pronto-socorro, foram normais. O paciente foi\nsubmetido à realização de eletrocardiograma (com calibração padrão), cujo resultado está\napresentado na figura precedente (VER IMAGEM). Com base nas informações presentes no texto e\nna figura referente a esse caso clínico, julgue o item a seguir. Os resultados dos exames indicam\nque esse é um caso de anginina instávelde início recente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/140723.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-108184","number":"108184","sourceNumber":"108184","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de sessenta anos de idade compareceu à emergência de um hospital\nqueixando-se de dor precordial em aperto de forte intensidade que tinha se iniciado, havia trinta\nminutos, imediatamente após acordar. O exame físico mostrou pressão arterial de 150 x 100\nmmHg, frequência cardíaca de 100 bpm, frequência respiratória de 20 irpm, temperatura de 36°C e\nsaturação de oxigênio de 97%. A ausculta cardíaca mostrou ritmo cardíaco em 3 tempos com\npresença da quarta bulha. Com referência ao caso clínico apresentado, julgue o item seguinte. A\npresença de quarta bulha aumenta a probabilidade de que a dor seja decorrente de síndrome\ncoronariana.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88714","number":"88714","sourceNumber":"88714","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma paciente de sessenta e oito anos de idade, com antecedentes de tabagismo e\ndiabetes, refere que, há quatro horas, iniciou um quadro de dor retroesternal em peso de forte\nintensidade, com irradiação para o membro superior esquerdo e sem alívio com o uso de dipirona.\nNo exame físico, a paciente apresentou-se eupneica e acianótica, com pressão arterial de 132\nmm/Hg × 84 mm/Hg, frequência cardíaca de 78 bpm e ritmo cardíaco regular em dois tempos sem\nsopros. O eletrocardiograma revelou supradesnível do segmento ST na parede anterior do\nventrículo esquerdo. A dosagem das enzimas cardíacas (CK-MB massa e troponina), o exame de\nraios X de tórax e os demais exames laboratoriais de rotina foram normais. Considerando esse\ncaso clínico, julgue o próximo item. A paciente deve ser tratada com ácido acetilsalicílico,\nclopidogrel e betabloqueador.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88635","number":"88635","sourceNumber":"88635","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com relação aos pacientes com dislipidemias, julgue o item seguinte. A modificação\ndos hábitos de vida (alimentação saudável,\nprática regular de atividades físicas, manutenção do\níndice de massa corporal saudável) é parte essencial do acompanhamento desses pacientes e tem\nimpacto significativo na redução do risco de doença aterosclerótica cardiovascular dos indivíduos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-37943","number":"37943","sourceNumber":"37943","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma senhora de 67 anos de idade, que teve diagnóstico de infarto do miocárdio por\ndoença coronariana aterosclerótica, há 6 meses,\nvem fazendo acompanhamento periódico e\nregular com cardiologista, sem sintomas. Em sua última consulta, ela relatou que, nos últimos 30\ndias, passou a apresentar muita fadiga e cansaço aos pequenos esforços e voltou a apresentar\nepisódios de dor precordial do tipo anginosa, que, inicialmente, ocorriam aos grandes esforços e,\nna última semana, passaram a ocorrer aos médios esforços, que melhoram com o repouso e, às\nvezes, com o uso de nitrato sublingual. Ela também informou que estava apresentando sudorese\nnoturna excessiva (sem relação com esforços físicos ou com a dor anginosa). Em seu exame físico,\napresentava: pressão arterial de 125 x 80 mmHg, frequência cardíaca de 60 bpm, ritmo cardíaco\nregular em 3 tempos (à custa de quarta bulha), pulmões limpos, presença de esplenomegalia (baço\npalpável a 14 cm abaixo da borda costal esquerda na posição intermediária de Schuster), fígado\nimpalpável (hepatimetria de 8 cm), sem edemas ou lesões. O exame hematológico mostrou\nhemoglobina de 10,0 g/dl, leucócitos totais = 105.000 céls/mm³ (aumento de neutrófilos,\nbastonetes, metamielócitos e também de eosinófilos e basófilos); a contagem de plaquetas foi de\n780.000/mm³. O ácido úrico sérico foi de 14 mg/dl. Diante do quadro, o cardiologista suspeitou de\ndoença hematológica e encaminhou-a ao hematologista. Foi então realizado um exame de biópsia\nda medula óssea (mielograma), que evidenciou medula hipercelular com granulócitos em diferentes\nestágios de maturação (bastonetes, metamielócitos, mielócitos, promielócitos e mieloblastos),\naumento de eosinófilos e basófilos. O exame citogenético detectou uma translocação recíproca\nentre os braços longos dos cromossomas 9 e 22, levando à formação de um novo gene específico,\no BCR-ABL. O traçado do último Eletrocardiograma (ECG) convencional realizado é apresentado\nabaixo. Tendo por base as informações clínicas e laboratoriais apresentadas no texto acima, julgue\no item. \"A análise do ECG permite concluir que a paciente apresentou infarto do miocárdio\nlocalizado na parede inferior.\"","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/37943.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-343391","number":"343391","sourceNumber":"343391","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Acerca do manuseio de pacientes com dor torácica, é CORRETO afirmar:","options":{"A":"A pericardite pode ser confundida com angina, pois costuma causar dor precordial em aperto,\naliviada pelo repouso e pela nitroglicerina, mas que piora com a respiração profunda.","B":"A dor torácica que acompanha a pneumonia é bastante variável, tanto em intensidade quanto\nem característica, refletindo geralmente\nacometimento pulmonar periférico, com estimulação das\nterminações nervosas da pleura.","C":"Os transtornos psiquiátricos não podem e não devem ser diagnosticados como a causa de dor\ntorácica em um paciente, pelo risco de uma desordem orgânica de base ser negligenciada.","D":"A dor torácica causada por patologia esofágica é localizada na região central do tórax, dura de\nsegundos a poucos minutos, sendo\nfrequentemente descrita pelo paciente como pontada."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-334883","number":"334883","sourceNumber":"334883","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 61 anos de idade, sedentário, obeso e tabagista, há duas horas iniciou\nepigastralgia em queimação de forte intensidade após o almoço. O exame físico mostrou uma\nfrequência cardíaca igual a 60 bpm, frequência respiratória = 25 irpm, SatO2 = 92% e PA = 100\nmmHg x 60 mmHg, com ausculta cardíaca e pulmonar normais e sem edema de membros\ninferiores. Na admissão em uma unidade de pronto atendimento, ele realizou o eletrocardiograma\n(ECG) a seguir. Qual é a principal hipótese de diagnóstico?","options":{"A":"Bloqueio de ramo direito.","B":"Infarto agudo do miocárdio","C":"Síndrome de Wolf Parkinson White","D":"Hipertonia vagal","E":"Fibrilação atrial"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-291558","number":"291558","sourceNumber":"291558","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma mulher com 55 anos de idade procura a unidade de emergência referenciada com\nqueixa de dor precordial em aperto há 12 horas. Antecedentes pessoais: diabética tipo 2, há 12\nanos, em uso de metformina 1.500 mg ao dia e glicazida 30 mg ao dia, hipertensão arterial, há 8\nanos, em uso de captopril 150 mg ao dia. Exame físico da admissão: PA = 100 x 60 mmHg, FC =\n70 bpm, FR = 18 irpm, Sat = 92%. Ritmo cardíaco regular em 2 tempos sem sopros, murmúrio\nvesicular presente e simétrico com estertores crepitantes em base, abdome globoso, fígado a 4 cm\ndo rebordo costal direito, baço não percutível. Extremidades: pulsos periféricos diminuído, edema\n3+/4+. ECG a seguir: Diante do quadro apresentado, o diagnóstico e tratamento são:","options":{"A":"Infarto agudo do miocárdio e trombólise com ateplase.","B":"Infarto do miocárdio evoluído e cateterismo.","C":"Síndrome coronariana aguda e balão intra-aórtico.","D":"Pericardite aguda e colchicina."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/291558.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-230548","number":"230548","sourceNumber":"230548","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considerada recomendação para uso de antiagregantes plaquetários e anticoagulantes\nem pacientes oncológicos com trombocitopenia o\nitem:","options":{"A":"Uso do ácido acetilsalicílico em pacientes com doença coronária.","B":"O ácido acetilsalicílico deve ser usado sempre em dose máxima, preferencialmente ? 500 mg ao\ndia.","C":"Uso de terapia antiplaquetária e/ou anticoagulante em pacientes com síndrome coronária aguda,\nexceto caso com plaquetopenia.","D":"Uso de dose reduzida de enoxaparina e heparina não fracionada em pacientes com contagem\nde plaquetas < 150.000."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-230556","number":"230556","sourceNumber":"230556","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A morfologia da Placa Aterosclerótica (PC) tem um papel importante na ocorrência de\neventos cerebrovasculares e pode também ser um importante preditor de evento. Assim podemos\nAPENAS aceitar que:","options":{"A":"O reconhecimento das características ultrassonográficas da placa pode atrapalhar a\nidentificação de uma placa instável.","B":"O reconhecimento das características ultrassonográficas da placa não altera a identificação de\numa placa instável.","C":"O reconhecimento das características ultrassonográficas da placa não facilita a identificação de\numa placa estável.","D":"O reconhecimento das características ultrassonográficas da placa pode facilitar a identificação\nde uma placa instável."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-206086","number":"206086","sourceNumber":"206086","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"As categorias de risco baixo e intermediário cardiovascular são baseadas apenas na\nidade e nos Estratificadores de Risco (ER). Doença aterosclerótica subclínica não está presente\nnestes grupos de risco. Determine qual dos itens abaixo não se enquadra no seu quadro:","options":{"A":"Escore de cálcio arterial coronário > 10 U Agatston.","B":"Placa carotídea (espessura íntima média > 1,5 mm)14.","C":"Angiotomografia coronária computadorizada com presença de placa 15?.","D":"Índice tornozelo braquial < 0,7"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-206135","number":"206135","sourceNumber":"206135","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Calcificação Arterial Coronariana (CAC) está associada a eventos cardiovasculares e\nmortalidade em pacientes com diabetes. Podemos apenas ACEITAR que:","options":{"A":"O rastreamento de aterosclerose clínica, não se utilizando o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor discriminar o\nrisco cardiovascular em prevenção primária.","B":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da terceira idade, para pior discriminar o\nrisco cardiovascular em prevenção primária.","C":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio endotelial, pode ser\ndesconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor\ndiscriminar o risco cardiovascular em prevenção primária.","D":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor discriminar o\nrisco cardiovascular em prevenção primária."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-206147","number":"206147","sourceNumber":"206147","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considere a investigação de isquemia miocárdica em pacientes com diabetes,\nassintomáticos e na presença dos achados abaixo descritos, indique o INCORRETO:","options":{"A":"Alterações de ECG de repouso.","B":"Pacientes que apresentam sintomas atípicos.","C":"Pacientes que apresentam dispneia inexplicada, dor torácica atípica ou desconforto.","D":"Calcificação arterial coronariana CAC muito alta (> 100)."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-206151","number":"206151","sourceNumber":"206151","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em indivíduos com diabetes, o SPECT tem maior sensibilidade e especificidade do que\no teste ergométrico. Estando de acordo com o\nseguinte item:","options":{"A":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla\n\ngama de informações, incluindo localização e extensão da isquemia e função ventricular esquerda.","B":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\n\nTc-99m sestamibi fornecem informações restritas, excluindo localização e extensão da isquemia e\nfunção ventricular esquerda.","C":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla gama de informações, incluindo localização e extensão da\nisquemia, mas não a função ventricular esquerda.","D":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla gama de informações, excluindo localização e extensão da\nisquemia e função ventricular esquerda."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-203106","number":"203106","sourceNumber":"203106","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 60 anos de idade é internado em razão de dor torácica típica de\nsíndrome coronariana com duração de duas horas.\nEle apresenta frequência cardíaca de 42 bpm,\ncom bradicardia sinusal observada e confirmada no ECG, associada ao supradesnivelamento do\nsegmento ST nas derivações DII, DIII e AVF. No que se refere a esse caso clínico, assinale a\nalternativa correta.","options":{"A":"O paciente provavelmente tem um aneurisma de ventrículo esquerdo como complicação do\ninfarto agudo do miocárdio.","B":"O paciente apresenta quadro de infarto agudo do miocárdio de parede inferior, pois a artéria\ncoronária direita irriga a parede inferior do ventrículo esquerda e o nó sinusal.","C":"A bradicardia sinusal apresentada pelo paciente é fator protetor do aumento da área de\nisquemia. Assim, não deve ser considerada como fenômeno patológico.","D":"O paciente apresenta infarto agudo do miocárdio de ventrículo direito, pois as derivações\ndescritas são da artéria circunflexa e coronária direita.","E":"O ECG com supradesnivelamento do segmento ST, bem como o tempo de dor torácica, indicam\nque esse paciente não é candidato a terapia trombolítica ou angioplastia primária no momento."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-212077","number":"212077","sourceNumber":"212077","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. As informações apresentadas\nnesse caso clínico podem sugerir o diagnóstico de infarto agudo do miocárdio em parede anterior.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175089","number":"175089","sourceNumber":"175089","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Durante seu último plantão, foi solicitada sua avaliação para um paciente que deu\nentrada no hospital com queixa de dor torácica, e que referia ser diabético. Foi feito exame de\nECG. Dentre os possíveis achados do exame e sobre os conceitos diagnósticos, qual das\nalternativas se mostra INCORRETA?","options":{"A":"Sobrecarga ventricular esquerda miocárdica ao eletrocardiograma (ECG) indica baixa de\neventos cardiovasculares no DM.","B":"Ondas ?Q? ao eletrocardiograma (ECG) indicam risco elevado de eventos cardiovasculares no\nDM.","C":"Isquemia miocárdica ao eletrocardiograma (ECG) indica risco elevado de eventos\ncardiovasculares no DM.","D":"ECG, contudo é um exame pouco sensível."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175090","number":"175090","sourceNumber":"175090","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Enoxaparina apresenta grande indicação de ser administrada quando do diagnóstico\ndo IAMCST, não podemos, contudo, afirmar que:","options":{"A":"Em pacientes com idade < 75 anos: 30 mg por via Intravenosa (IV) em bolus seguidas de 1\nmg/kg de peso Subcutâneo (SC) a cada 12 horas até a alta hospitalar.","B":"Em pacientes com idade = 75 anos: não administrar o bolus e iniciar com 0,75 mg/kg SC a cada\n12 horas.","C":"A Enoxaparina não tem demonstrado redução de mortalidade.","D":"Uso de Enoxaparina demonstra que não houve redução do desfecho primário de morte ou\ninfarto do miocárdio não fatal sem um aumento importante de sangramento."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-177262","number":"177262","sourceNumber":"177262","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 65 anos de idade, portador de diabetes e de hipertensão arterial\napresenta quadro doloroso precordial iniciado\nhá 2 dias , quando foi internado em unidade\nhospitalar em cidade remota , de modo a aguardar transferência para uma unidade de referência\nem cardiologia. O resultado do eletrocardiograma apresenta supra de ST e onda Q, embora o\npaciente se apresente hemodinamicamente estável. Ele chega a uma unidade terciária para vaga\nem UTI. Durante o transporte, houve piora súbita do estádo clínico do paciente , que apresentou\ndispneia, diaforese e edema agudo de pulmão. Na admissão na UTI, o paciente apresentava PA de\n98 mmHg x 72 mmHg (PA média de 81 mmHg), sopro meso-sistólico leve, mas audível, em ápice,\nirradiando-se para axila. além de edema agudo de pulmão. Considerando-se o referido caso clínico\ne os conhecimentos médicos relacionados a ele, é correto afirmar que, ao admitir o paciente, a\nequipe deverá realizar","options":{"A":"estabilização do quadro respiratório, com suporte ventilatório e ecocardiograma precoce, para\nplanejamento de plastia ou troca mitral.","B":"estudo hemodinârnico para reperfusão de resgate e iniciar imediatamente terapia com dupla\nantigregação plaquetária.","C":"o procedimento do balão intra-aórtico, em razão de tratar-se de sopro secundário à degeneração\nventricular esquerda, com reperfusão programada.","D":"intubação orotraquel e investigação de evento tromboembólico pulmonar para início da\nadministração trombolítico.","E":"infusão de agentes inotrópicos e vasopressores por se tratar de insuficiência ventricular\nesquerda decorrente de infarto agudo do miocárdio."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183930","number":"183930","sourceNumber":"183930","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade, sem doenças prévias, procurou\natendimento de emergência em um hospital de\nnível terciário, com quadro de dor retroesternal, de\ngrande intensidade, em aperto, com irradiação para o membro superior esquerdo (tipo\nformigamento), iniciada havia quatro horas. Com exceção da presença de quarta bulha cardíaca,\nnão apresentou outras alterações significativas no exame físico. O eletrocardiograma realizado na\nsala de emergência evidenciou ritmo sinusal, frequência ventricular média de 98 bpm, SÂQRS de +\n60°, presença de supradesnível do segmento ST de 5 mm nas derivações precordiais de V1 a V6 e\nnas derivações do plano frontal D1 e aVL. Os níveis de troponina T e de CKBM estavam elevados e\ncom valores acima do triplo do limite superior de referência. Com base nas informações clínicas e\nlaboratoriais do caso clínico precedente, julgue o item subsequente. O provável diagnóstico para\nesse paciente é de infarto do miocárdio transmural ? com supra do segmento ST do\neletrocardiograma ?, localizado na parede anterior extensa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175167","number":"175167","sourceNumber":"175167","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A decisão sobre a liberação para a atividade desportiva após IAM é baseada nas\navaliações clínicas e nos resultados dos exames complementares: teste ergométrico,\necocardiograma, ECG, Holter 24 horas, radiografia de tórax e exames laboratoriais. Sendo\ninadequado apenas que:","options":{"A":"É importante a avaliação do anseio do paciente e qual atividade e, principalmente, qual\ndesempenho ele espera atingir.","B":"Os pacientes, após submetidos à estratificação, devem ser classificados entre baixo, moderado\ne alto risco.","C":"Os pacientes de baixo risco são os que apresentaram alterações nos exames complementares e\nque permanecem assintomáticos, são orientados à\nrealização de quaisquer tipos de atividade\nfísica.","D":"Já os indivíduos de moderado e alto risco são contra indicados às atividades competitivas e\ndevem ser encaminhados para atividades físicas supervisionadas."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175169","number":"175169","sourceNumber":"175169","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro da conduta médica frente à realização de exercícios físicos nos paciente\nInfartados em reabilitação, somente podemos considerar INCORRETO o seguinte item:","options":{"A":"A prática de natação e hidroginástica merece alguns cuidados. Apesar de ideal para os obesos,\npode gerar alguns problemas para o\ncoronariano, como bradicardia reflexa vagal e arritmias\ncomplexas.","B":"O choque térmico pode causar espasmos arteriais.","C":"Indivíduos que já estejam praticando atividade física no após IAM devem ser orientados às\nmínimas modificações nos sintomas e sinais, ou à alterações nos exames de reavaliação\nindicativas da progressão da doença aterosclerótica coronárias.","D":"Pacientes infartados que não possuam prévio domínio da técnica natatória devem ser\ndesaconselhados à hidroginástica."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175172","number":"175172","sourceNumber":"175172","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro das indicações da Emergência de Insuficiência Coronariana, podemos\nconsiderar completamente adequado somente a seguinte alternativa:","options":{"A":"Ácido acetilsalicílico é um dos muitos anti-inflamatórios indicados rotineiramente para todos os\npacientes com suspeita de IAM.","B":"Ácido acetilsalicílico é contraindicado na alergia ou intolerância ao medicamento, sangramento\nativo, hemofilia e úlcera péptica ativa.","C":"Pacientes com maior risco de doença coronária devem ser instruídos por seus médicos\nassistentes a tomar Ácido Acetilsalicílico (AAS) tamponado em situações emergenciais.","D":"É o antiplaquetários de eleição a ser utilizado no IAM, tendo sido demonstrado que reduz a\nmortalidade em 90%, isoladamente, quase tanto quanto a Estreptoquinase (SK)."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175177","number":"175177","sourceNumber":"175177","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com o uso de ensaios cada vez mais sensíveis para dosagem de troponinas, as\nmudanças absolutas e relativas de seus valores\nna fase aguda têm sido muito valorizadas para o\ndiagnóstico correto de IAM. Como a curva ou alteração da troponina (delta change), sendo\ninadequado que:","options":{"A":"Alguns estudos demonstraram que incrementos relativos de 20 a 50% em relação aos Valores\nBasais são insuficientes para detectar uma curva.","B":"Da mesma forma, incrementos absolutos (de uma vez o referencial de cada ensaio) também\ndemonstraram uma acurácia melhor que a dosagem isolada das troponinas na admissão.","C":"No entanto, não existe consenso de qual ponto de corte seja ideal.","D":"Os incrementos nas troponinas ultrassensíveis são muito sensíveis para infarto em evolução,\nmas pouco específicos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175176","number":"175176","sourceNumber":"175176","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Para que ocorra melhora do prognóstico, a adesão aos programas de reabilitação\ncardiovascular é importante para o sucesso de\nqualquer intervenção de prevenção secundária, e\nestá diretamente relacionada à aderência ao tratamento. Somente uma das alternativas listadas se\nmostra inadequada dentro da atual abordagem, assinale-a:","options":{"A":"Os índices de aderência aos programas de reabilitação cardíaca após IAM excedem a 80% nos\n3 primeiros meses, caindo para 60 a 71% no\nsexto mês, para 60% aos 12 meses e para 30 a 40%\nentre o segundo e o quarto ano","B":"A insistência do Médico Assistente e a integração da equipe multidisciplinar ao atendimento aos\npacientes, por meio de esclarecimento e controle dos fatores de risco, não tem demonstrado\naumento na adesão ao tratamento.","C":"Aumento da capacidade funcional, redução de sintomas, benefício psicológico, auxílio no\ncontrole de fatores de risco, retorno mais precoce ao trabalho e aumento da sobrevivência\njustificam o emprego sistemático da reabilitação no tratamento do IAM, em todas as fases,\nconsiderando sua excelente relação custo/efetividade.","D":"A orientação fundamental a ser dada pelo cardiologista é a de que a reabilitação após o infarto\nnão se limita a programas formais e\nsofisticados, mas à mudança do estilo de vida, abrangente em\nrelação aos fatores de risco controláveis, e à marcada convivência com movimentos de qualquer\nespécie em relação às atividades cotidianas."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-168434","number":"168434","sourceNumber":"168434","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem com 50 anos de idade, ao ser atendido em um Serviço de Emergência,\nrefere desconforto torácico descrito como sensação\nde aperto, com início há cerca de 90 minutos,\nsem fatores de alívio. Questionado a respeito da localização da dor, o paciente coloca a mão\nfechada sobre o lado esquerdo do peito. Informa, ainda, que o desconforto teve início após ter\nsubido escadas, tendo evoluído também com náuseas, palidez cutâneo-mucosa e sudorese fria. O\npaciente é portador de hipertensão arterial sistêmica e dislipidemia, estando em uso regular de\nenalapril - 20 mg/dia, de sinvastatina - 20 mg/dia e de ácido acetilsalicílico - 100 mg/dia.\nDurante o\natendimento, foi realizado eletrocardiograma, cujo resultado está reproduzido a seguir. (Conforme\nimagem no caderno de questões) Nessa situação, qual é o diagnóstico mais provável e o que se\nespera encontrar na curva enzimática do paciente no momento de sua chegada?","options":{"A":"Angina variante de Prinzmetal; troponina e CPK-MB positivas.","B":"Angina instável; marcadores de necrose miocárdica negativos.","C":"Infarto agudo do miocárdio inferolateral dorsal; mioglobina positiva.","D":"Infarto agudo do miocárdio de parede lateral alta; elevações séricas de mioglobina e CK-MB."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/168434.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-104738","number":"104738","sourceNumber":"104738","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O segmento ST no eletrocardiograma reflete:","options":{"A":"repolarização atrial.","B":"despolarização atrial.","C":"despolarização ventricular.","D":"o intervalo de despolarização entre átrios e ventrículos.","E":"repolarização ventricular."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-104755","number":"104755","sourceNumber":"104755","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Além dos benefícios de natureza mais ampla para a saúde e a melhoria da qualidade\nde vida, vários estudos têm demonstrado que a\natividade física é um fator importante na prevenção\ne no controle de alguns problemas de saúde, quando analisada a partir da perspectiva\npopulacional. A orientação para a prática de atividades físicas moderadas está relacionada ao\ncontrole da frequência cardíaca como parâmetro de segurança. Um indivíduo de sessenta anos de\nidade deve atingir frequência cardíaca (bat/min) máxima e ideal, respectivamente, de","options":{"A":"140 e entre 110 e 118.","B":"150 e entre 124 e 138.","C":"160 e entre 104 e 128.","D":"170 e entre 114 e 138.","E":"180 e entre 108 e 128."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-80711","number":"80711","sourceNumber":"80711","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O diagnóstico de Infarto Agudo do Miocárdio (IAM) geralmente é feito pela tríade: dor\nprecordial característica, anormalidades ao Eletrocardiograma (ECG) e marcadores cardíacos\nséricos elevados. A análise de segmento ST ao ECG tem implicações terapêuticas e prognósticas e\ndeve sempre ser procedida com suspeita desse quadro, por que:","options":{"A":"O supradesnivelamento do segmento ST é indicação de imediata revascularização.","B":"O supradesnivelamento de ST é patagnomônico de angina instável.","C":"O infradesnivelamento de ST sempre precede fibrilação ventricular.","D":"O infradesnivelamento de ST só ocorre nos pacientes que já tiveram IAM prévio.","E":"Fibrilação atrial sempre se associa a supradesnivelamento de ST e por isso entra no diagnóstico\ndo diferencial do IAM."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-80704","number":"80704","sourceNumber":"80704","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De acordo com a 1ª Diretriz de Ressuscitação Cardiopulmonar e Cuidados\nCardiovasculares de Emergência da Sociedade\nBrasileira de Cardiologia - 2013, a Parada\nCardiorrespiratória (PCR) permanece como um problema mundial de saúde pública. Apesar de\navanços nos últimos anos relacionados à prevenção e ao tratamento, muitas são as vidas perdidas\nanualmente no Brasil relacionadas à PCR. Nesse sentido, assinale a alternativa correta em relação\nà epidemiologia.","options":{"A":"A disponibilidade obrigatória dos Desfibriladores Automáticos não trouxe importante relevência,\npois a maioria das PCR não é por fibrilação.","B":"Em relação à educação, à implementação e ao retreinamento, as habilidades adquiridas após\num treinamento em Ressuscitação\nCardiorrespiratória (RCP) podem ser perdidas em tempo muito\ncurto (três a seis meses), caso não utilizadas ou praticadas.","C":"Informações sobre epidemiologia e desfechos da RCP não têm contribuído para um maior\nsucesso das tentativas de ressuscitação devido à baixa notificação.","D":"Em relação à importância dos cuidados pós-ressuscitação, muitas vítimas de PCR ressuscitadas\nmorrem nas primeiras 24 a 36 horas de\ndisfunção miocárdica, mas as que sobrevivem raramente\napresentam disfunção e sequelas cerebrais importantes.","E":"Uma simplificação de procedimentos, principalmente voltada para o socorrista leigo, pode\nproporcionar uma maior aderência a possíveis tentativas de melhoria do sucesso das\nressuscitações, entretanto a fase pré-hospitalar não apresenta muita relevência no prognóstico."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-97752","number":"97752","sourceNumber":"97752","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma mulher com 65 anos de idade apresenta o seguinte histórico: antecedentes de\nobesidade, hipertensão arterial e angioplastia coronariana prévia, em uso prévio de diltiazem - 90\nmg/dia, propranolol - 40 mg duas vezes ao dia, AAS - 100 mg/dia, dinitrato de isossorbida e\nsinvastatina - 20 mg/dia. A paciente, residente em uma cidade do interior, apresentou, há cerca de\n24 horas, quadro de infarto agudo do miocárdio com supradesnivelamento de ST de parede inferior\nassociado a infarto do ventrículo direito. Como não havia equipe de hemodinâmica disponível, foi\nadministrada estreptoquinase, com melhora apenas parcial da dor. Após estabilização clínica a\npaciente foi encaminhada para Serviço de Emergência de hospital terciário. Na admissão a\npaciente estava eupneica, orientada, ainda com queixas de dor precordial com as mesmas\ncaracterísticas, mas de menor intensidade e intermitente. A pressão arterial era de 100 x 60 mmHg,\nfrequência cardíaca = 78 bpm, frequência respiratória = 16 irpm. As auscultas cardíaca e pulmonar\nestavam normais. Enquanto eram colhidos os exames complementares e repetido o ECG, a\npaciente subitamente apresentou quadro de choque (pressão arterial = 60 x 20 mmHg), com\nrebaixamento do nível de consciência, palidez cutâneo-mucosa e insuficiência respiratória. A\nsaturação de 02 caiu para 75% em ar ambiente e a frequência cardíaca aumentou para 135 bpm. A\nperfusão periférica encontrava-se muito prejudicada e as extremidades frias e sudoreicas. O ictus\ncardíaco estava hiperdinâmico e a ausculta cardíaca revelava bulhas audíveis, com 3ª bulha e\nsopro holossistólico pancardíaco, mais audível em borda estrenal esquerda. Havia turgência jugular\na 45°. A ausculta pulmonar revelava estertores bolhosos até os ápices. Alem da intubação\norotraqueal, as medidas terapêuticas recomendadas são:","options":{"A":"iniciar noradrenalina e dobutamina e encaminhar para angioplastia de emergência.","B":"iniciar nitroprussiato de sódio e dopamina e realizar pericardiocentese de emergência.","C":"iniciar nitroprussiato de sódio e dobutamina e encaminhar para cirurgia cardíaca de emergência.","D":"iniciar noradrenalina e dopamina e encaminhar para instalação, de emergência, de balão\nintra-aórtico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-97805","number":"97805","sourceNumber":"97805","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem com 35 anos de idade, obeso, sedentário, foi admitido no Serviço de\nEmergência com quadro agudo de dor\nretroesternal e epigástrica, em queimação, que o acordou no\nmeio da noite. Relata episódios pregressos semelhantes, porém de menor intensidade e\ngeralmente após refeições copiosas. No momento da consulta, estava extremamente ansioso,\nfrequência cardíaca = 104 bpm, pressão arterial = 150 x 110 mmHg e auscultas cardíaca e\npulmonar sem anormalidades. O paciente foi incluído em protocolo de avaliação de dor torácica e\nfoi indicada internação para observação e exames seriados por 12 horas. Qual dos seguintes\nachados de exames complementares afasta o diagnóstico de dor torácica não cardíaca?","options":{"A":"ECG normal após 12 horas.","B":"Ecocardiograma normal após 12 horas.","C":"EDA - hérnia hiatal com esofagite de refluxo moderada.","D":"Ausência de elevação de CK-MB e troponina em 12 horas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-64433","number":"64433","sourceNumber":"64433","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O aumento da mortalidade do infarto agudo do miocárdio está relacionado ao uso de:","options":{"A":"Diltiazem","B":"Amlodipina","C":"Nifedipina","D":"Verapamil","E":"Captopril"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-75539","number":"75539","sourceNumber":"75539","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem com 54 anos de idade, com antecedentes de dislipidemia, hipertensão arterial\ne histórico de doença familiar cardiovascular\nprecoce (pai teve infarto do miocárdio aos 50 anos),\ndeu entrada na Emergência de um hospital com história de dor em região epigástrica há cerca de\ncinco horas, em aperto, de forte intensidade, sem relação com a alimentação e sem fatores de\nmelhora, acompanhada de náuseas e vômitos. Havia recebido 200 mg de AAS no hospital de\norigem. Ao exame, encontrava-se pálido, sudoreico e sonolento. Temperatura axilar = 35,8ºC;\npressão arterial = 80 x 50 mmHg; frequência cardíaca = 118 bpm; frequência respiratória = 16 irpm.\nPerfusão periférica diminuída. A ausculta cardíaca revelava bulhas normofonéticas, sem sopros.\n\nHavia turgência jugular a 45º. A ausculta pulmonar não revelava estertores. O eletrocardiograma da\nadmissão é apresentado abaixo: (VER IMAGEM) Diante do quadro clínico do paciente, a hipótese\ndiagnóstica, a provável causa do choque e o tratamento inicial recomendado são, respectivamente:","options":{"A":"Infarto do miocárdio com supra de ST de parede inferior; tamponamento cardíaco;\npericardiocentese.","B":"Infarto do miocárdio com supra de ST de parede anterior; resposta inflamatória sistêmica;\nnoradrenalina.","C":"Infarto do miocárdio com supra de ST de parede inferior; infarto de ventrículo direito;\nhidratação\ncom solução salina.","D":"Infarto do miocárdio com supra de ST de parede anterior; ruptura de músculo papilar; colocação\nde balão intra-aórtico.","E":"Infarto do miocárdio com supra de ST de parede anterosseptal; ruptura do septo interventricular;\ncirurgia cardíaca de emergência."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/75539.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-137701","number":"137701","sourceNumber":"137701","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 48 anos, hipertenso, obeso, chega à Emergência com queixa de\nepisódios de dor torácica precordial, sem\nirradiação, iniciada nos últimos dois dias, com piora há 24\nhoras. A dor dura de 5 a 15 minutos, sendo precipitada por esforços intensos, como subir escadas,\ne é aliviada pelo repouso. O paciente informa não sentir a dor no momento da anamnese. Usa\ncaptopril e hipoglicemiante oral de forma regular. Nega antecedentes de doença coronariana e um\neletrocardiograma foi considerado normal pelo seu cardiologista na última consulta, há 6 meses. Ao\nexame, mostra-se ansioso, mas em bom estado geral, pulso = 85 bpm, regular, cheio, PA = 140 x\n80 mmHg, pulsos periféricos palpáveis e simétricos, extremidades bem perfundidas. As auscultas\npulmonar e cardíaca estão dentro da normalidade. O seu eletrocardiograma à admissão mostra os\nseguintes achados (VER IMAGEM). Qual a abordagem mais adequada ao paciente?","options":{"A":"Realizar tratamentos anti-isquêmico e antitrombótico administrados de modo imediato e\nsimultâneo.","B":"Observar em Unidade Coronariana e administrar medicamentos sintomáticos até realização de\ncateterismo cardíaco.","C":"Observar na Emergência por 12 horas e encaminhar ao cardiologista para teste ergométrico se\npersistir assintomático.","D":"Realizar tratamento anti-isquêmico imediato, seguido de terapia antitrombótica em caso de\nalterações do segmento ST no ECG nas próximas 12 horas.","E":"Realizar tratamento antitrombótico imediato, seguido de terapia anti-isquêmica em caso de\nelevação de troponina sérica e/ou CK-MB nas próximas 12 horas."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/137701.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-351582","number":"351582","sourceNumber":"351582","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 77 anos de idade, diabético tipo 2, coronariopata, com\nrevascularização miocárdica há 8 anos, chegou ao pronto-socorro com quadro de dor precordial\ncom as mesmas características do infarto agudo do miocárdio, ocorrido há 9 anos, acompanhado\nde palidez e sudorese. O exame físico revelou pressão arterial de 140 x 90mmHg em membros\nsuperiores, frequência cardíaca de 80bpm e peso de 80kg. O paciente apresentava-se com bom\nestado geral, ansioso, pálido, hidratado e afebril. Estava em uso de 100mg/dia de AAS, 850mg de\nmetformina 3x/dia, 50mg de captopril 3x/dia, 25mg/dia de atenolol e 20mg/dia de sinvastatina.\n\nRealizou ECG que não evidenciou alterações no segmento ST. Foram realizadas três dosagens\nnegativas de troponinas. Nesse caso, é\nCORRETO afirmar que a principal hipótese diagnóstica é:","options":{"A":"Síndrome coronariana aguda com angina instável.","B":"Infarto agudo do miocárdio sem supradesnivelamento do segmento ST.","C":"Infarto agudo do miocárdio com supradesnivelamento do segmento ST.","D":"Angina estável."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-352187","number":"352187","sourceNumber":"352187","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quanto aos tipos de infarto agudo do miocárdio (IAM), assinale a alternativa incorreta.","options":{"A":"Tipo 1: é o infarto decorrente de instabilização de uma placa aterosclerótica na coronária.","B":"Tipo 2: é o infarto causado mais comumente por um desbalanço entre oferta e demanda de\noxigênio para o músculo cardíaco.","C":"Tipo 3: quadro sugestivo de IAM em acidente que evoluiu com morte súbita e no qual não houve\ntempo de colher marcadores de necrose miocárdica.","D":"Tipo 4: infarto relacionado à cirurgia de revascularização miocárdica."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-320451","number":"320451","sourceNumber":"320451","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"As síndromes coronarianas agudas são emergências clínicas de alta morbimortalidade.\nAcerca do tratamento dessas condições, julgue as\nalternativas abaixo e marque a correta:","options":{"A":"O uso de oxigenoterapia deve ser realizado de rotina na sala de emergência.","B":"O uso de beta-bloqueadores (via oral) deve ser feito nos pacientes sem sinais de baixo débito.","C":"A morfina deve ser evitada, pois aumenta o consumo miocárdico de oxigênio.","D":"A dose de ataque de enoxaparina deve ser feita na dose de 1 mg/kg, via subcutânea.","E":"A fibrinólise pode ser realizada para os pacientes com síndrome coronariana aguda sem supra\nde ST de alto risco."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-336312","number":"336312","sourceNumber":"336312","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher, 52 anos, tabagista, portadora de lúpus eritematoso sistêmico e hipertensão\narterial sistêmica, chega no pronto socorro com\nprecordialgia intensa iniciada há 5 horas,\nespontaneamente, em repouso, que piora durante a inspiração forçada, irradiada para ombros, sem\nmelhora desde então. Ao exame: regular estado geral, corada, acianótica, anictérica, desidratada\n\n+/4+, Tax: 38,1°C. Lúcida, orientada em tempo e espaço, pupilas isocóricas e fotorreagentes, sem\ndéficits focais. Ritmo cardíaco regular, 2 tempos, bulhas hipofonéticas, sem sopros, FC: 106 bpm,\nPA: 142/80 mmHg, jugulares túrgidas, TEC < 3 segundos. Murmúrio vesicular fisiológico, sem\nruídos adventícios, eupneica em ar ambiente, SpO2: 97%. Realizado eletrocardiograma e\nultrassonografia cardíaca point-of-care na admissão, cujas imagens estão abaixo. O diagnóstico e\ntratamento, deste paciente são, respectivamente:","options":{"A":"Miocardite aguda / Prednisona + amoxicilina","B":"Pericardite aguda / Ibuprofeno + colchicina","C":"Infarto agudo do miocárdio com supradesnivelamento de ST / Alteplase","D":"Tamponamento cardíaco / Pericardiocentese imediata"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/336312.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-305021","number":"305021","sourceNumber":"305021","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considere dois pacientes que buscaram atendimento médico no ambulatório de um\nhospital com queixa de tonteira. O paciente\nA é um homem de 73 anos de idade, hipertenso, com\nrelato de sensação de rotação do ambiente que acontece pela manhã, ao se levantar da cama,\nassociada à náusea, que passa muito rapidamente, embora ele permaneça por alguns minutos\nsudorético, nauseado e com as mãos frias. A paciente B é uma mulher de 54 anos de idade,\nhipertensa e diabética, com relato de sensação de desmaio, sudorese, palpitações e escurecimento\nvisual que podem acontecer em repouso ou esforço, e duram alguns minutos, com remissão\nespontânea. Considerando as prováveis origens das tonteiras desses pacientes, os exames\ninicialmente indicados para auxílio diagnóstico são, respectivamente,","options":{"A":"manobra de Dix-Hallpike e eletrocardiograma (ECG).","B":"eletronistagmografia e Holter de 24 horas.","C":"Holter de 24 horas e manobra de Dix-Hallpike.","D":"eletronistagmografia e ECG."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-304873","number":"304873","sourceNumber":"304873","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Adolescente, sexo masculino, 12 anos, comparece a consulta solicitando atestado para\nprática de natação. Assintomático, sem história familiar de risco para doença cardiovascular.\n\nExame físico: dados vitais e exame segmentar normais. Traz eletrocardiograma realizado há um\nano para avaliação pré-operatória de cirurgia\nortopédica com laudo de arritmia sinusal. A conduta\nindicada neste caso é:","options":{"A":"Liberar para prática de natação.","B":"Indicar Tilt teste.","C":"Realizar ecocardiograma.","D":"Solicitar novo eletrocardiograma."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-306731","number":"306731","sourceNumber":"306731","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"D.R.A, 58 anos, dá entrada no PS com queixa de dor torácica há 1 hora. Apresenta-se\nsudoreico e relata náuseas. Durante a\navaliação inicial foi realizado eletrocardiograma, que está\nrepresentado abaixo. PA = 80/50 mmHg, FC = 120 bpm, FR = 28 irpm, SpO2 = 92%. A troponina\nencontra-se 3 vezes acima do valor de referência superior. Qual das drogas abaixo está\ncontraindicada neste caso?","options":{"A":"Ácido acetilsalicílico","B":"Clopidogrel","C":"Dinitrato de isossorbida","D":"Heparina"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/306731.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-287337","number":"287337","sourceNumber":"287337","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 65 anos, diabético, hipertenso, dislipidêmico e tabagista. Relata\ndor/desconforto no hemitórax esquerdo há 02\nsemanas, durante uma atividade física moderada. Há\n01 dia apresentou desconforto mais intenso (7+/10+), com cerca de 10 minutos de duração. Nessa\nmadrugada, às 05h15, foi acordado com dor retroesternal (10+/10+), acompanhado de náuseas e\nmal-estar intenso. Às 08h30 é atendido com desconforto em hemitórax esquerdo (4+/10+). O\neletrocardiograma está apresentado abaixo. Qual diagnóstico? (Obs. Cópia da Figura a seguir na\npágina 13 ampliada para consulta).","options":{"A":"Síndrome Coronariana Aguda.","B":"Angina Estável.","C":"Dissecção de aorta.","D":"Tomboembolismo Pulmonar."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/287337.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-246719","number":"246719","sourceNumber":"246719","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A inflamação desempenha papel central na gênese da doença coronariana isquêmica.\nNos últimos anos, vários medicamentos têm sido\nutilizados em pesquisas clínicas buscando reduzir\nnovos eventos coronarianos adversos, a nível de prevenção secundária, agindo exclusivamente por\nvias inflamatórias. Dentre os medicamentos abaixo, qual possui evidência científica mais favorável\nneste contexto?","options":{"A":"Corticoides","B":"Anti-Inflamatórios não hormonais","C":"Idarucizumab","D":"Metotrexato","E":"Colchicina"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-243062","number":"243062","sourceNumber":"243062","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, é admitido na UPA (Unidade de Pronto\nAtendimento) com forte dor precordial há 2 horas.\nEletrocardiograma mostra supradesnível de\nsegmento ST em parede anterior. É submetido à trombólise química com critérios de reperfusão.\nSegundo a estratégia farmacoinvasiva atualmente indicada, este paciente:","options":{"A":"deve ser submetido a cateterismo com vistas à possível intervenção coronária percutânea dentro\nde 3 a 24 horas após a trombólise\nbem-sucedida.","B":"deveria ter sido administrada metade da dose do trombolítico no atendimento pré-hospitalar e,\nem seguida, ter sido encaminhado para hospital de referência.","C":"deve ser submetido a cateterismo o quanto antes após a administração de trombólise, mesmo\nque a reperfusão química seja bem-sucedida.","D":"deve ser submetido a cateterismo com vistas à possível intervenção coronária percutânea após\n48 horas da trombólise bem-sucedida.","E":"caso seja optado por cateterismo cardíaco, a trombólise intra-arterial está indicada."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-243067","number":"243067","sourceNumber":"243067","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A ecocardiografia sob estresse é um método não invasivo, estabelecido para a\navaliação de pacientes com doença arterial\ncoronária. Qual, dentre as alternativas abaixo, NÃO\nconstitui indicação para a realização do ecocardiograma sob estresse na doença arterial coronária\ncrônica?","options":{"A":"Estratificação de risco de pacientes com doença arterial coronária.","B":"Avaliação de isquemia miocárdica em indivíduos assintomáticos com teste ergométrico positivo\nou duvidoso.","C":"Avaliação de rotina em pacientes após revascularização do miocárdio.","D":"Avaliação de isquemia miocárdica na presença de bloqueio do ramo esquerdo ou alterações que\nimpeçam adequada análise eletrocardiográfica de isquemia.","E":"Estresse farmacológico na avaliação de viabilidade miocárdica (miocárdio hibernado) para\nplanejamento de revascularização."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-243074","number":"243074","sourceNumber":"243074","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentre os achados de exame físico, qual, entre os abaixo, NÃO é característico de um\nepisódio anginoso provocado por isquemia miocárdica?","options":{"A":"sopro diastólico aspirativo em foco aórtico acessório.","B":"terceira bulha.","C":"quarta bulha.","D":"sopro de regurgitação mitral.","E":"desdobramento paradoxal da segunda bulha."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215173","number":"215173","sourceNumber":"215173","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 50 anos, tabagista, refere que acordou às 6 horas da manhã com dor\nretroesternal em queimação, com irradiação\npara o pescoço, associado a sudorese, náuseas e\nvômitos. Chega ao pronto-socorro às 10 horas e é submetido a realização de eletrocardiograma\nque evidenciou supra do segmento ST em parede anterior. O paciente encontra-se a 30 minutos do\ncentro de referência com hemodinâmica. Qual é o próximo passo?","options":{"A":"Administrar AAS 200 mg, clopidogrel 300 mg, enoxaparina 30 mg IV e encaminhar ao serviço de\nhemodinâmica para angioplastia primária.","B":"Administrar AAS 200 mg, clopidogrel 300 mg, enoxaparina 30 mg IV e aguardar a troponina\nantes de encaminhar para angioplastia\nprimária.","C":"Administrar AAS 100 mg, clopidogrel 75 mg, enoxaparina 80 mg SC e encaminhar ao serviço de\nhemodinâmica para angioplastia primária.","D":"Administrar AAS 100 mg, clopidogrel 75 mg, enoxaparina 80 mg SC e aguardar a troponina\nantes de encaminhar para angioplastia\nprimária.","E":"Realizar trombólise com tenecteplase."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215179","number":"215179","sourceNumber":"215179","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 52 anos, do sexo masculino, chegou ao pronto-socorro com queixa de dor\nretroesternal em aperto, com duração de 20min, que se repetiu por 2 vezes nas últimas 24 horas.\nEstava assintomático havia 2 anos, em uso de ácido acetilsalicílico (AAS), sinvastatina e enalapril.\nApresenta antecedentes de hipertensão, dislipidemia. Pai falecido de infarto do miocárdio aos 54\nanos. Exame físico: ritmo cardíaco regular; Frequência Cardíaca (FC) = 88 bpm; Pressão Arterial\n(PA) = 140 x 90 mmHg; pulmões sem ruídos adventícios. Primeira medida de troponina positiva. O\neletrocardiograma (ECG) está apresentado na figura que segue:","options":{"A":"Paciente de alto risco (TIMI = 6); deve ser estratificado invasivamente nas próximas 24 horas.","B":"Paciente de alto risco (TIMI = 5); deve ser estratificado invasivamente nas próximas 48 horas.","C":"Paciente de alto risco (TIMI = 7); deve ser estratificado invasivamente nas próximas 24 horas.","D":"Paciente de moderado risco (TIMI = 4); deve ser estratificado invasivamente nas próximas 72\nhoras.","E":"Paciente de alto risco (TIMI = 6); deve ser estratificado invasivamente nas próximas 48 horas."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/215179.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215181","number":"215181","sourceNumber":"215181","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 68 anos chegou à emergência do Hospital de Marechal Floriano com infarto\nagudo do miocárdio (IAM) com supradesnivelamento de do segmento ST na parede inferior.\n\nClinicamente, apresentava-se estável hemodinamicamente em Killip I. Os sintomas haviam iniciado\nhá 60 minutos, não possui contra-indicação ao\nuso de trombolítico. Qual a estratégia de tratamento\nmais adequada, considerando-se o tempo de transferência para o centro de referência para\nhemodinâmica estima-se ser de cerca de 150 minutos?","options":{"A":"Encaminhar o paciente imediatamente ao centro capacitado para realização de angioplastia\nprimária.","B":"Administrar metade da dose do trombolítico preconizada para IAM com supra de ST e\nencaminhar o paciente para estratégia de angioplastia facilitada.","C":"Utilizar inibidor de IIb/IIa e encaminhar o paciente para estratégia de angioplastia facilitada.","D":"Por ser o IAM de baixo risco para complicações, tratar o paciente sem estratégia de reperfusão,\nevitando-se os riscos do uso de trombolítico em local com poucos recursos ou os riscos de\ntransporte.","E":"Administrar trombolítico imediatamente, com posterior estratificação coronariana invasiva."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-215106","number":"215106","sourceNumber":"215106","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O que apresenta um paciente com infarto agudo do miocárdio e insuficiência cardíaca\nKillip III:","options":{"A":"Choque cardiogênico.","B":"Edema agudo de pulmão cardiogênico.","C":"Estertores crepitantes bibasais.","D":"Perda de líquido para terceiro espaço.","E":"Todas as alternativas anteriores."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-196813","number":"196813","sourceNumber":"196813","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 59 anos com dor precordial em aperto iniciada há duas horas, irradiando\npara o andar superior do abdome, com vômitos.\nAusculta pulmonar normal. PA = 115 x 70 mmHg.\nAmilase e lipase normais. Radiografias de tórax e abdome normais e o ECG abaixo. Dentre as\ndrogas abaixo, qual deve ser evitada neste paciente?","options":{"A":"Nitroglicerina.","B":"AAS.","C":"Sinvastatina.","D":"Enoxaparina."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/196813.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-172803","number":"172803","sourceNumber":"172803","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 78 anos admitido em pronto-socorro com dor precordial típica, há cerca de 1\nhora, associada à dispneia. Histórico de uso de sildenafila há 3 horas. Ao exame físico,\napresentava-se orientado, sudoreico, com frequência cardíaca de 110 bpm e pressão arterial de 85\nx 50 mmHg. O eletrocardiograma evidencia infradesnivelamento de segmento ST de V1 a V3. Este\npaciente deve ser tratado com:","options":{"A":"Heparina de baixo peso molecular associada a antiagregante plaquetário.","B":"Nitroprussiato de sódio por via endovenosa.","C":"Nitrato sublingual.","D":"Trombolítico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-148540","number":"148540","sourceNumber":"148540","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente feminina, 60 anos, multípara, obesa, apresenta dor intensa epigástrica,\nacompanhada de sudorese profusa, dispneia e\ntaquicardia, que durou cerca de 15 minutos. No dia\nseguinte procura assistência médica já assintomática. A pressão arterial foi aferida em 130 x 80\nmmHg, frequência cardíaca de 80 batimentos por minuto, ritmo cardíaco regular em 2 tempos,\nabdome indolor, sem massas palpáveis ou visceromegalias, com peristalse normal e exame do\naparelho respiratório normal. Ao iniciar a investigação, qual a conduta mais adequada neste\ncontexto clínico?","options":{"A":"Solicitar endoscopia digestiva alta.","B":"Solicitar eletrocardiograma de repouso e de teste ergométrico.","C":"Solicitar ultrassonografia abdominal.","D":"Solicitar exame de urina.","E":"Solicitar tomografia computadorizada de tórax."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-155474","number":"155474","sourceNumber":"155474","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentre os biomarcadores séricos abaixo, o mais específico para necrose miocardica é:","options":{"A":"Mioglobina.","B":"BNP.","C":"CK-MB.","D":"Troponina.","E":"Interleucina 6."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-131638","number":"131638","sourceNumber":"131638","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em pacientes com infarto agudo do miocárdio, o maior benefício com o uso de\nfibrinolíticos é encontrado naqueles que apresentam:","options":{"A":"Bloqueio A-V de 1º e 2º graus.","B":"Elevação do segmento ST em parede anterior.","C":"Eletrocardiograma normal.","D":"Depressão do segmento ST, em qualquer área.","E":"Elevação do segmento ST em parede inferior."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-100986","number":"100986","sourceNumber":"100986","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"T.V.Z., homem, 73 anos, necessita realizar tratamento cirúrgico de hérnia inguinal\nbilateral. Entretanto, devido sua idade, e ao fato\nde apresentar hipertensão arterial bem controlada\ncom uso de anlodipina, ele e sua família estão preocupados com os riscos da operação. Passou\nem avaliação com o cardiologista que o classificou como classe I de Goldman. Na consulta com o\nanestesiologista, foi classificado como classe II de ASA (American Society of Anesthesiologists).\n\nIsso significa que:","options":{"A":"O risco de morte de origem cardíaca para o doente em questão é aproximadamente 0,2%.","B":"Com oito pontos atribuídos pela idade, utilizando-se a classificação de Goldman, o doente\napresenta probabilidade de não complicação de 86%.","C":"O doente não está apto a ser operado, tendo em vista que, com a classificação ASA II tem alta\nprobabilidade de apresentar evento cardíaco no período intraoperatório.","D":"O doente está apto a ser operado, mas deve passar o período pós-operatório imediato em\nUnidade de Tratamento Intensivo.","E":"Os riscos potenciais à vida do doente em questão são de aproximadamente 11%."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-77502","number":"77502","sourceNumber":"77502","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 56 anos procura o pronto-socorro por dor torácica. Refere pressão\nretroesternal irradiada para a mandíbula,\ndesencadeada por esforço, e melhorando após 3 minutos\nem repouso. Não se altera com a posição ou ventilação. Atendido 1 hora após e no momento\nassintomático. O eletrocardiograma é normal. A alternativa que melhor relaciona a hipótese mais\nprovável e a conduta, respectivamente, nesse momento, é:","options":{"A":"Angina de peito - dosagem de troponina.","B":"Infarto agudo do miocárdio - ecocardiograma.","C":"Infarto agudo do miocárdio - coronariografia.","D":"Dissecção de aorta - radiografia de tórax.","E":"Angina de peito - teste de esforço."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88889","number":"88889","sourceNumber":"88889","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente hipertenso, diabético, dislipidêmico, 57 anos, vem apresentando precordialgia\nassociada aos esforços, típica de coronariopatia. Porém, teste ergométrico foi normal. Qual a\nmelhor conduta?","options":{"A":"Prosseguir com a investigação de coronariopatia, pois deve ser um falso-negativo do teste\nergométrico.","B":"Encerrar a investigação, pois não deve ser coronariopatia.","C":"Medicar com AAS e acompanhar o paciente ambulatorialmente.","D":"Solicitar CT de tórax, sem contraste, pois pode ser outra patologia torácica.","E":"Investigar patologia osteomuscular."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88847","number":"88847","sourceNumber":"88847","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual o tempo porta-agulha ideal para trombólise, no IAM com supradesnivelamento do\nsegmento ST, após admissão hospitalar?","options":{"A":"até 30 minutos.","B":"até 45 minutos.","C":"até 10 minutos.","D":"até 35 minutos.","E":"até 90 minutos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88844","number":"88844","sourceNumber":"88844","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual o tempo porta-balão ideal em pacientes com IAM com supradesnivelamento do\nsegmento ST?","options":{"A":"até 30 minutos.","B":"até 45 minutos.","C":"até10 minutos.","D":"até 35 minutos.","E":"até 90 minutos."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-43923","number":"43923","sourceNumber":"43923","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente deu entrada no Pronto-Socorro com quadro de dor precordial intensa\nsendo diagnosticada síndrome coronariana aguda sem supradesnivelamento do segmento ST.\nQual das medidas a seguir foi demonstrado, em ensaios clínicos, ser eficaz claramente para\ntratamento inicial em diminuir a gravidade em eventos cardiovasculares?","options":{"A":"Uso intravenoso de nitrato nas primeiras horas do início da dor.","B":"Associação de clopidogrel e ticlopidina.","C":"Utilização de bloqueadores do cálcio (Verapamil ou Diltiazem).","D":"Uso de heparina de baixo peso molecular.","E":"Utilização de inibidores da enzima conversora da angiotensina 2."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-32460","number":"32460","sourceNumber":"32460","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 68 anos com relato de desconforto em hemitórax esquerdo há 01 semana,\ndurante o estresse no trabalho. Há 24\nhoras, apresentou desconforto mais intenso (5+/10+), com\ncerca de 10 minutos de duração. Nessa madrugada, às 05:30h, foi acordado com intenso\ndesconforto retroesternal (8+/10+) acompanhado de mal-estar e náuseas. Utilizou Atenolol 50 mg\ncom melhora parcial dos sintomas. Fatores de risco: Hipertensão Arterial Sistêmica, dislipidemia,\ntabagista e com pai falecido por Acidente Vascular Cerebral aos 74 anos. Às 08:10h é atendido\ncom desconforto em hemitórax esquerdo (2+/10+) e são realizados Eletrocardiograma de repouso\napresentado abaixo e coleta de amostra de sangue. O exame físico revela 4ª bulha, ausência de\nsopros e pulmões limpos. Pressão Arterial = 165/88 mmHg, peso = 87 kg e altura = 1,73 m. Em\nrelação ao quadro clínico descrito, pode-se afirmar que: (VER IMAGEM)","options":{"A":"A história clínica e o Eletrocardiograma são suficientes para o diagnóstico e conduta terapêutica\niniciais.","B":"A descrição clínica é compatível com Angina Estável, com evolução para Síndrome Coronária\nAguda.","C":"A descrição clínica é compatível com Angina Instável e a estratificação no momento da\nadmissão é compatível com grupo de alto risco para eventos adversos na fase intra-hospitalar.","D":"A realização de ecocardiograma é necessária para diagnóstico diferencial entre as diversas\napresentações das Síndromes Coronárias Agudas e orientará a terapêutica inicial.","E":"A presença da 4ª bulha é útil na diferenciação entre angina instável e infarto."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/32460.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-32497","number":"32497","sourceNumber":"32497","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"É expressivo o aumento da prevalência de obesidade na faixa etária pediátrica,\nconcomitante ao incremento significativo de\nmorbidades associadas à doença nesta idade, tais\ncomo:","options":{"A":"Síndrome metabólica, Hipertensão arterial e Síndrome da apneia do sono.","B":"Dislipidemia, Genu varum, Esteatose hepática.","C":"Diabetes Mellitus tipo 1, Insuficiência venosa, Dislipidemia.","D":"Acanthosis nigrians, Infarto agudo do miocárdio, Síndrome do ovário policístico.","E":"Acidente Vascular Cerebral, Refluxo gastroesofágico, Estrias."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-27402","number":"27402","sourceNumber":"27402","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente sem fatores de risco para DAC, com dor precordial típica há 50 minutos chega\nao PS com PA = 155 x 90 mmHg e FC = 78\nbpm. Realizou ECG que é demonstrado abaixo. Após\nadministração de dinitrato de isossorbida SL evolui com piora da dor precordial associada à\ndispneia e pré-síncope. PA = 60 x 40 mmHg e FC = 55 bpm. Qual o diagnóstico mais provável?\n(VER IMAGEM)","options":{"A":"IAM inferior complicando com edema agudo de pulmão","B":"IAM lateral com provável rotura de músculo papilar","C":"IAM anterior + CIV pós-infarto","D":"IAM inferior com acometimento de ventrículo direito","E":"Trata-se de pericardite aguda e hipotensão causada pela vasodilatação secundária ao uso de\nnitrato"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/27402.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-9388","number":"9388","sourceNumber":"9388","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 67 anos, portador de hipertensão arterial, tem colesterol total de 280\nmg/dL, HDL 32 mg/dL, triglicerídeos 190 mg/dL e cintura 104 cm. Fez uma CT Slice-64 para\ndiagnóstico de doença coronariana. Que parecer clínico é dado ao paciente?","options":{"A":"O teste negativo para estenose coronariana nos permite excluir a possibilidade de doença\naterosclerótica coronariana.","B":"A presença de estenose não necessita confirmação por cateterismo coronariano.","C":"Trata-se de um exame com baixa especificidade e sensibilidade, sem aplicabilidade clínica.","D":"O valor preditivo negativo para estenose dos segmentos iniciais, médio e distal das artérias\ncoronárias é baixo, aproximadamente 20%.","E":"Esse teste apresenta pequena exposição à radiação, sem risco para o paciente."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-355622","number":"355622","sourceNumber":"355622","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 60 anos, é atendido com dor precordial constritiva iniciada em\nrepouso desde duas horas antes. Encontra-se\ndiaforético e pálido; PA = 110/75 mmHg; FC = 106\nbpm; ausculta cardíaca com ritmo cardíaco regular, sem sopros. O nível sérico de troponina está\nelevado e o traçado do ECG é compatível com infarto agudo do miocárdio sem elevação do\nsegmento ST. Assinale a alternativa que apresenta a melhor opção terapêutica para este paciente:","options":{"A":"ácido acetilsalicílico","B":"AAS, betabloqueador, clopidogrel e enoxiparina","C":"betabloqueador, maleato de enalapril e enoxiparina","D":"nitroglicerina, sulfato de morfina e betabloqueador","E":"estreptoquinase, AAS, fondaparinux e clopidogrel"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-353832","number":"353832","sourceNumber":"353832","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De acordo com a Diretriz da Sociedade Brasileira de Cardiologia sobre Angina Instável\ne Infarto Agudo do Miocárdio sem\nSupradesnível do Segmento ST (SCASSST), julgue as seguintes\nafirmações como verdadeiras (V) ou falsas (F). 1. O uso de AAS é recomendado na sala de\nemergência o mais precoce possível em todos os pacientes sem contraindicação, em dose inicial\nde 150 a 300 mg e dose de manutenção de 75 a 100 mg. 2. Os Anti-Inflamatórios Não Esteroides\n(AINE) são preconizados para controle da dor em pacientes com infarto agudo do miocárdio. 3. É\nindicado iniciar o tratamento com nitrato para alívio da angina na sala de emergência, sendo\nadministrado inicialmente por via sublingual, e, caso não haja melhora rápida da dor, a\nadministração intravenosa é recomendada. Sendo (V) para verdadeiro e (F) para falso, é\nCORRETO afirmar:","options":{"A":"1F ? 2V ? 3F.","B":"1V ? 2V ? 3F.","C":"1F ? 2F ? 3V.","D":"1V ? 2F ? 3V."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-334095","number":"334095","sourceNumber":"334095","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O ecocardiograma sob estresse pode ser recomendado para estratificação de risco de\npacientes em unidades de dor torácica:","options":{"A":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado inconclusivo, uma vez aliviada a dor por pelo menos 24h\nem pacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e\nmarcadores de necrose.","B":"Especialmente quando o ECG define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado inconclusivo, uma vez aliviada a dor por pelo menos 24h\nem pacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e\nmarcadores de necrose.","C":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico não é submáximo,\nde realização factível ou com resultado\ninconclusivo, uma vez aliviada a dor por pelo menos 24h em\npacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e marcadores\nde necrose.","D":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado conclusivo, uma vez aliviada a dor por pelo menos 4h em\npacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e marcadores\nde necrose."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-334097","number":"334097","sourceNumber":"334097","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em pacientes com dor torácica aguda e ECG não diagnóstico:","options":{"A":"O uso da ecocardiografia com contraste reduz a sensibilidade para o diagnóstico da síndrome\ncoronariana aguda - SCA.","B":"O uso da ecocardiografia sem contraste não aumenta a sensibilidade para o diagnóstico da\nsíndrome coronariana aguda - SCA.","C":"O uso da ecocardiografia com contraste não aumenta a sensibilidade para o diagnóstico da\nsíndrome coronariana aguda - SCA.","D":"O uso da ecocardiografia com contraste aumenta a sensibilidade para o diagnóstico da síndrome\ncoronariana aguda - SCA."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-334773","number":"334773","sourceNumber":"334773","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente do sexo masculino, diabético, com 62 anos de idade, foi submetido à\nangioplastia coronariana com implante de stent há 7 dias, na vigência de quadro de infarto agudo\ndo miocárdio sem supradesnivelamento do segmento ST. No seguimento ambulatorial deste\npaciente é importante garantir que","options":{"A":"a terapia de dupla antiagregação plaquetária seja mantida por no máximo seis meses após o\ninfarto.","B":"os fármacos análogos do GLP-1 não sejam associados ao esquema terapêutico antes de 30\ndias do infarto.","C":"o nível máximo de LDL-C em 50 mg/dL deve ser alcançado o mais brevemente possível.","D":"o ácido acetilsalicílico seja suspenso, em pacientes com ritmo sinusal, após doze meses do\ninfarto."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-339771","number":"339771","sourceNumber":"339771","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após 3\ndias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte: O\nquadro clínico apresentado sugere como diagnóstico:","options":{"A":"infarto agudo do miocárdio com supra desnivelamento do segmento ST.","B":"dissecção de coronária.","C":"miopericardite.","D":"vasoespasmo coronariano."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/339771.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-339772","number":"339772","sourceNumber":"339772","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nQual dos exames a seguir deverá ser solicitado nesse caso?","options":{"A":"Cateterismo cardíaco.","B":"Angiotomografia de coronárias.","C":"Cintilografia do miocárdio.","D":"Ecocardiograma."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/339772.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-339773","number":"339773","sourceNumber":"339773","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nNesse caso, o tratamento adequado é o da indicação de","options":{"A":"aspirina e clopidogrel.","B":"anti-inflamatório não hormonal e colchicina.","C":"corticosteroides e nitrato.","D":"heparina, aspirina e clopidogrel."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/339773.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-339774","number":"339774","sourceNumber":"339774","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 61 anos de idade, sedentário, obeso e tabagista, há duas horas iniciou\nepigastralgia em queimação de forte intensidade após o almoço. O exame físico mostrou uma\nfrequência cardíaca igual a 60 bpm, frequência respiratória = 25 irpm, SatO2 = 92% e PA = 100\nmmHg x 60 mmHg, com ausculta cardíaca e pulmonar normais e sem edema de membros\ninferiores. Na admissão em uma unidade de pronto atendimento, ele realizou o eletrocardiograma\n(ECG) a seguir. Qual é a principal hipótese de diagnóstico?","options":{"A":"Bloqueio de ramo direito.","B":"Infarto agudo do miocárdio","C":"Síndrome de Wolf Parkinson White","D":"Hipertonia vagal","E":"Fibrilação atrial"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/339774.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-346432","number":"346432","sourceNumber":"346432","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Você está de plantão no pronto socorro do hospital e existem 04 pacientes na sala\nvermelha. Assinale qual dos pacientes possui indicação de trombólise endovenosa de urgência,\nconsiderando ausência de contra indicações?","options":{"A":"Homem de 40 anos, diabético e hipertenso, apresentou episódio de perda de força à direita e\ndificuldade para falar há 05 horas. EF: Hemiplegia à direita e Afasia motora. Exames\nComplementares: TC Crânio Sem alterações;","B":"Mulher de 55 anos, tabagista 40 anos/maço, apresentou episódio de dor torácica, em opressão,\nde forte intensidade, com irradiação para o\nmembro superior esquerdo e mandíbula há 11 horas.\nExames Complementares: ECG Supra de segmento ST em parede anterior;","C":"Homem de 35 anos, submetido a cirurgia de joelho esquerdo há 01 semana, apresentou\nepisódio de dor em membro inferior esquerdo há\n06 horas. EF: Dor à palpação de panturrilha\nesquerda. Exames Complementares: USG Doppler Venoso de Membro Inferior Esquerdo:\nTrombose venosa profunda extensa;","D":"Mulher de 35 anos, em uso de anticoncepcional oral, apresentou episódio de dor torácica\nventilatória dependente à esquerda há 03 horas, sem\ninstabilidade hemodinâmica. Exames\nComplementares: Angio TC Tórax, com presença de TEP Defeitos de enchimento completos dos\nramos inferiores dos lobos médio e inferiores pulmonares."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-321608","number":"321608","sourceNumber":"321608","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após 3\ndias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte: O\nquadro clínico apresentado sugere como diagnóstico:","options":{"A":"infarto agudo do miocárdio com supra desnivelamento do segmento ST.","B":"dissecção de coronária.","C":"miopericardite.","D":"vasoespasmo coronariano."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/321608.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-337459","number":"337459","sourceNumber":"337459","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A adição do escore de cálcio coronário aos de riscos clínicos:","options":{"A":"Tem figurado como a alternativa mais eficiente e não custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário.","B":"Tem figurado como a alternativa mais eficiente e custo-efetiva na atualidade para estimar o risco\nde doença arterial coronariana (DAC) em pacientes com risco intermediário.","C":"Não Tem figurado como a alternativa mais eficiente e custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário.","D":"Tem figurado como a alternativa menos eficiente e custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-321609","number":"321609","sourceNumber":"321609","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nQual dos exames a seguir deverá ser solicitado nesse caso?","options":{"A":"Cateterismo cardíaco.","B":"Angiotomografia de coronárias.","C":"Cintilografia do miocárdio.","D":"Ecocardiograma."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/321609.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-321610","number":"321610","sourceNumber":"321610","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nNesse caso, o tratamento adequado é o da indicação de","options":{"A":"aspirina e clopidogrel.","B":"anti-inflamatório não hormonal e colchicina.","C":"corticoesteroides e nitrato.","D":"heparina, aspirina e clopidogrel."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/321610.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-337466","number":"337466","sourceNumber":"337466","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De forma concordante, o uso de estatinas em pacientes com doença arterial\ncoronariana (DAC) parece estabilizar placas ateroscleróticas:","options":{"A":"Não podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear\nnão apenas entre a redução do LDL-c e a taxa de eventos doença cardiovascular CV, mas também\nentre o nível de LDL-c e a progressão do volume de ateroma em carótidas.","B":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e não para a\ntaxa de eventos doença cardiovascular CV, mas\ntambém entre o nível de LDL-c e a progressão do volume de ateroma em carótidas.","C":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e a taxa de\neventos doença cardiovascular CV, e não para o\nnível de LDL-c e a progressão do volume de ateroma em carótidas.","D":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e a taxa de\neventos doença cardiovascular CV, mas também\nentre o nível de LDL-c e a progressão do volume de ateroma em carótidas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-315764","number":"315764","sourceNumber":"315764","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Nos pacientes que chegam ao serviço de emergência com menos de 3h do início do\nquadro de dor:","options":{"A":"As Trop-US são significativamente mais sensíveis que a troponina convencional para diagnóstico\nde SCA, melhorando em 61% o poder diagnóstico\nde IAM naquele momento e em 100% se a\ncoleta for 6h após o início do quadro.","B":"As Trop-US são significativamente menos sensíveis que a troponina convencional para\ndiagnóstico de SCA, melhorando em 61% o poder diagnóstico de IAM naquele momento e em\n100% se a coleta for 6h após o início do quadro.","C":"As Trop-US são significativamente mais sensíveis que a troponina convencional para\ndiagnóstico de SCA, piorando em 61% o poder\ndiagnóstico de IAM naquele momento e em 100%\nse a coleta for 6h após o início do quadro.","D":"As Trop-US são significativamente mais sensíveis que a troponina convencional para\ndiagnóstico de SCA, melhorando em 61% o poder\ndiagnóstico de IAM naquele momento e em\n100% se a coleta for 1h após o início do quadro."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-315767","number":"315767","sourceNumber":"315767","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A dose de enoxaparina é de 1mg/kg administrado por via subcutânea (SC) duas vezes\nao dia. Na idade superior a 75 anos, a dose\ndeve ser reduzida para 0,75mg/kg duas vezes ao dia.\nSendo correto que:","options":{"A":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida por\n10, sendo então administrado 0,1mg/ kg (SC) uma\nvez ao dia.","B":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida\npela metade, sendo então administrado 1mg/ kg (SC)\nduas vezes ao dia.","C":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose não deve ser reduzida.","D":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida\npela metade, sendo então administrado 1mg/ kg (SC)\numa vez ao dia."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-300807","number":"300807","sourceNumber":"300807","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considerando as partes que recorrentemente classificam a anamnese, quanto ao\nelemento ?antecedentes pessoais?, é CORRETO afirmar:","options":{"A":"Pergunta-se sobre o início dos sintomas, como evoluíram e como estão no momento.","B":"Pergunta-se sobre a sua atual profissão e se o paciente utiliza algum equipamento de proteção.","C":"É de suma precisão para que se possa obter do paciente se ele possui algum tipo de alergia e\nintolerância a medicações e alimentos.","D":"Pergunta-se se o paciente é fumante ativo ou passivo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-315777","number":"315777","sourceNumber":"315777","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com a introdução das troponinas de alta sensibilidade (Trop-US), está correto o item:","options":{"A":"Passou a ser possível a detecção de níveis mais baixos de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","B":"Passou a ser impossível a detecção de níveis mais baixos de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","C":"Passou a ser possível a detecção de níveis mais elevados de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","D":"Passou a ser possível a detecção de níveis mais baixos de troponina, em maior tempo após\ninício do quadro de lesão miocárdica de causa isquêmica."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-316331","number":"316331","sourceNumber":"316331","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 24 anos, sem comorbidades, com histórico de internação recente por\ncovid-19, procura novamente o PS devido ao\nquadro de dor torácica com início há 3 dias com piora\ngradativa. Relata que ao decúbito e também a inspiração profunda apresenta piora significativa.\n\nRealizado o ECG (mostrado a seguir) logo na admissão junto com 2 coletas de marcadores de\nnecrose miocárdica - Troponina (VR <0,2) -> 1º: 0,45/ 2º:2,3. De acordo com o caso, qual o\ndiagnóstico mais provável?","options":{"A":"SCA com supradesnivelamento do segmento ST.","B":"SCA sem supradesnivelamento do segmento ST.","C":"Miopericardite.","D":"Sd. de Takotsubo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/316331.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-273207","number":"273207","sourceNumber":"273207","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considerando os evidentes benefícios da prática de atividade física para a saúde e\nseus possíveis riscos, uma exposição\nequilibrada de riscos e benefícios e uma avaliação das\ncaracterísticas e adaptações necessárias de determinados indivíduos e grupos são elementos\nessenciais de uma boa prática assistencial, a qual busca evitar o risco de agravos que derivam da\nprática de:","options":{"A":"Atividades de maior intensidade e menor duração na presença de condições favorecedoras,\ncomo lesões preexistentes e obesidade.","B":"Atividades de menor intensidade e maior duração na presença de condições desfavorecedoras,\ncomo lesões preexistentes e obesidade.","C":"Atividades de maior intensidade e maior duração na presença de condições favorecedoras,\ncomo lesões preexistentes e obesidade.","D":"Atividades de menor intensidade e menor duração na presença de condições desfavorecedoras,\ncomo lesões preexistentes e obesidade."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-254211","number":"254211","sourceNumber":"254211","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem 54 anos, obeso, hipertenso e diabético, admitido no PA com quadro de dor\ntorácica típica e eletrocardiograma\nevidenciando supradesnívelamento de segmento ST em D2, D3\ne avF. Ao exame físico, apresentava-se acordado, consciente, orientado, com taquidispneia,\nestertor crepitante bibasal, turgência jugular, PA 140x90mmHg, tempo de enchimento capilar 2seg.\nBaseadonos dados apresentados, pode-se classificar o paciente em qual classe de Killip:","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-229499","number":"229499","sourceNumber":"229499","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Nas síndromes coronarianas agudas que podem estar acompanhadas de elevação da\nPA, devido a um reflexo do miocárdio isquêmico, somente podemos CONCORDAR que:","options":{"A":"O aumento da RVP eleva a demanda de oxigênio miocárdico, pelo aumento da tensão parietal\ndo ventrículo esquerdo.","B":"Os nitratos IV reduzem a RVP, e pioram a perfusão coronariana.","C":"Os nitratos IV não possuem importante efeito vasodilatador sistêmico.","D":"Os nitratos IV reduzindo a pré-carga, mas não o consumo de oxigênio miocárdico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-249848","number":"249848","sourceNumber":"249848","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente S.G.A, do sexo masculino, de 66 anos, hipertenso, tabagista, diabético, em\nuso regular de losartana (50 mg/dia),\nmetformina (850 mg/dia) e de ácido acetilsalicílico (100\nmg/dia) há seis meses, deu entrada no pronto atendimento com dor precordial típica, de início há\ntrês horas e que melhorou com uso de nitrato. Após realizar os exames de emergência para\nsíndrome coronariana aguda (troponina positiva, creatinina 0,8 mg/dl, ureia 32 mg/dl e\neletrocardiograma). Nesse caso, o paciente","options":{"A":"deve ser estratificado invasivamente (cateterismo cardíaco), com urgência, por se tratar de uma\nsíndrome coronariana aguda com supra de ST.","B":"deve ser estratificado invasivamente (cateterismo cardíaco), de maneira precoce, por se tratar de\nalto risco cardiológico (TIMI RISK alto), com uma síndrome coronariana aguda sem supra de ST.","C":"deve ser encaminhado para estratificação não invasiva, por se tratar de um paciente de baixo\nrisco cardiológico (TIMI RISK baixo), com uma síndrome coronariana aguda sem supra de ST.","D":"deve ser trombolisado, por se tratar de síndrome coronariana aguda, na falta de estratificação\ninvasiva (cateterismo cardíaco)."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/249848.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-232225","number":"232225","sourceNumber":"232225","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Leia o caso clínico a seguir. Um paciente de 80 anos dá entrada no pronto-socorro com\nforte dor no peito, há 30 minutos, associada à sudorese. À admissão, observam-se um ritmo\nregular, FC = 80 bpm, PA = 80 x 55 mmHg e SatO? = 95%. O ECG mostrou supradesnivelamento\ndo segmento ST de V1 a V4. Nesse caso, a conduta imediata é:","options":{"A":"Dosar enzimas cardíacas.","B":"Avaliar função renal.","C":"Iniciar noradrenalina.","D":"Realizar revascularização percutânea."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-229866","number":"229866","sourceNumber":"229866","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Gilmar, 52 anos, gari, vem à consulta na Unidade Básica de Saúde com queixa de dor\nno peito há 2 meses. A dor aparece quando\nestá trabalhando e precisa correr ou carregar muito\npeso. Sente como um peso atrás do peito, que dura um 1 minuto e melhora quando fica em\nrepouso. Ele é tabagista, fuma 1 maço/dia há 20 anos, e hipertenso, faz uso de captopril quando a\npressão sobe. O risco cardiovascular calculado na consulta é de 34% e a probabilidade pré-teste\npara doença coronariana é maior que 90%. A alternativa que não corresponde ao caso de Gilmar é","options":{"A":"se o teste ergométrico não evidenciar sinais de isquemia miocárdica, é necessário iniciar\ninvestigação para outras etiologias de dor torácica como causas esofágicas e pulmonares;","B":"caso a dor de Gilmar apresente piora progressiva, com episódios de dor com duração maior e\ncom menor limiar de esforço, é necessário manejar como síndrome coronariana aguda;","C":"em caso de um episódio de dor torácica maior do que 20 minutos, no momento do atendimento\nmédico, é importante obter um\neletrocardiograma e oferecer 300 mg de ácido acetilsalicílico (AAS);","D":"no caso de Gilmar, é recomendado o início de beta-bloqueadores, que podem promover alívio\nsintomático da angina."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-247467","number":"247467","sourceNumber":"247467","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Doença Cardiovascular (CV) aterosclerótica é, em termos proporcionais, a principal\ncausa da mortalidade em países desenvolvidos e em muitos países em desenvolvimento como o\nBrasil. Nos últimos anos, ensaios clínicos randomizados e revisões sistemáticas vêm apontando\navanços no potencial de prevenção dessas doenças. Em relação a prevenção das doenças\ncardiovasculares tem-se o seguinte:","options":{"A":"a alimentação saudável é um dos pilares da prevenção cardiovascular, porém nenhuma\nintervenção nutricional específica mostrou-se efetiva na redução de eventos CV.","B":"evidências consistentes de estudos observacionais demonstram que a realização de atividade\nfísica está associada à redução do risco de\neventos CV tanto em homens quanto em mulheres,\nindependente da idade e intensidade desta atividade.","C":"em prevenção secundária, o uso de alguns fármacos anti-hipertensivos está associado a uma\nredução de eventos CV mesmo em pacientes sem hipertensão.","D":"ensaios clínicos randomizados recentes têm demonstrado que terapia de reposição hormonal\ndiminuiram os eventos CV."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-254291","number":"254291","sourceNumber":"254291","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Manoel é um homem de 55 anos, branco, sedentário, hipertenso, que chega até a\nunidade de saúde com a expectativa de fazer exames. Diz que utiliza losartana 50 mg de 12/12\nhoras há 10 anos e que acredita que a medicação esteja fraca, pois a pressão tem ficado\ndescontrolada. Entendendo o contexto de Manoel, você solicita exames complementares, os quais\nmostram os resultados a seguir: Colesterol total = 195; HDL = 40; LDL = 120; Triglicérides = 230;\nGlicemia de jejum = 108; Hemoglobina glicada = 5,6%; Creatinina = 0,7; EAS = sem alterações;\nEletrocardiograma = normal; Medida ambulatorial de pressão arterial (MAPA) = PA média de 145 x\n78 mmHg; Após analisá-los, você decide calcular o risco cardiovascular de Manoel por meio da\ncalculadora Framingham, cujo desfecho é de 21,40%. Diante do risco cardiovascular aferido, a\nmelhor conduta é:","options":{"A":"Prescrever AAS diário e estimular perda de peso.","B":"Prescrever ciprofibrato e sinvastatina, para repetir lipidograma em 3 meses.","C":"Prescrever sinvastatina e estimular exercícios físicos.","D":"Prescrever metformina e aumentar a dose de losartana."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-254292","number":"254292","sourceNumber":"254292","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Manoel é um homem de 55 anos, branco, sedentário, hipertenso, que chega até a\nunidade de saúde com a expectativa de\nfazer exames. Diz que utiliza losartana 50 mg de 12/12\nhoras há 10 anos e que acredita que a medicação esteja fraca, pois a pressão tem ficado\ndescontrolada. Entendendo o contexto de Manoel, você solicita exames complementares, os quais\nmostram os resultados a seguir: Colesterol total = 195; HDL = 40; LDL = 120; Triglicérides = 230;\nGlicemia de jejum = 108; Hemoglobina glicada = 5,6%; Creatinina = 0,7; EAS = sem alterações;\nEletrocardiograma = normal; Medida ambulatorial de pressão arterial (MAPA) = PA média de 145 x\n78 mmHg; Após analisá-los, você decide calcular o risco cardiovascular de Manoel por meio da\ncalculadora Framingham, cujo desfecho é de 21,40%. Imagine que Manoel retorne à UBS e relate o\nsurgimento, há 4 meses, de dor retroesternal ao realizar esforços mais intensos, com melhora ao\nrepouso, de caráter não progressivo. Para compreender melhor a probabilidade de se tratar de um\nquadro de doença arterial coronariana, você pesquisa pela tabela abaixo: Dentre as opções abaixo,\naquela que representa a melhor conduta diante da suspeita de angina é:","options":{"A":"Solicitar teste de esforço para estratificação de risco, devido à alta probabilidade pré-teste de\nangina estável.","B":"Encaminhar para serviço de urgência devido ao risco de angina instável.","C":"Solicitar cintilografia miocárdica para estabelecer diagnóstico definitivo.","D":"Manter a losartana 100 mg/dia e acrescentar AAS e furosemida."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/254292.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-201903","number":"201903","sourceNumber":"201903","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 56 anos procura o pronto-socorro por dor torácica, referindo pressão\nretroesternal, irradiada para a mandíbula, desencadeada por esforço, melhorando após 3 minutos\nem repouso, que não se altera com a posição ou com a ventilação. O paciente é atendido 1 hora\napós e no momento está assintomático. O eletrocardiograma é normal. A alternativa que melhor\nrelaciona a hipótese mas provável e a conduta, respectivamente, nesse momento, é:","options":{"A":"angina de peito ? dosagem de troponina","B":"infarto agudo do miocárdio - ecocardiograma","C":"infarto agudo do miocárdio - coronariografia","D":"dissecção de aorta ? radiografia de tórax","E":"angina de peito ? teste de esforço"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-218210","number":"218210","sourceNumber":"218210","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente com suspeita de Infarto Agudo do Miocárdio (IAM) realiza no pronto\natendimento um eletrocardiograma que revela\na presença de Bloqueio do Ramo Esquerdo (BRE).\nSobre o quadro acima exposto, assinale a alternativa CORRETA:","options":{"A":"A presença do BRE torna menos provável um quadro de IAM.","B":"Se o paciente apresentar no pronto atendimento um teste ergométrico realizado há 2 anos com\nBRE no traçado de repouso, fica menos\nprovável um quadro de IAM.","C":"Na vigência do BRE, a presença de uma elevação do segmento ST de 2 mm em V1 e V2 torna o\ntraçado favorável a um quadro de IAM, com provável acometimento de artéria descendente\nanterior.","D":"Na vigência do BRE, a presença de uma elevação do segmento ST de 1 mm em D1 e aVL com\ncomplexos QRS positivos torna o traçado favorável a um quadro de IAM."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-205559","number":"205559","sourceNumber":"205559","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A Calcificação Arterial Coronariana (CAC) está associada à mortalidade em pacientes\ncom diabetes, podendo ser considerada marcador\nde carga de placa aterosclerosclerótica, já\ndemonstrado em análise anatômica. Podemos assim, aceitar que:","options":{"A":"Em pacientes sem diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","B":"Em pacientes com diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","C":"Em pacientes com diabetes, CAC > 5 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","D":"Em pacientes com diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 12 sejam considerados de alto\nrisco cardiovascular."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-205573","number":"205573","sourceNumber":"205573","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A alternativa para o rastreio de isquemia é a ecocardiografia de estresse, usando\nexercício ou estresse farmacológico com\ndobutamina. Sensibilidade e especificidade são 81 e 85%,\nrespectivamente, em pacientes diabéticos assintomáticos. Sendo CORRETO que:","options":{"A":"O ecocardiograma de estresse não detecta possíveis anormalidades no movimento segmentar\nda parede ventricular, fornecendo informações\nsobre a intensidade da isquemia e a função\nventricular esquerda.","B":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento segmentar da\nparede ventricular, fornecendo informações sobre\na intensidade da isquemia e a função ventricular\nesquerda.","C":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento global apenas da\nparede ventricular, fornecendo informações sobre a intensidade da isquemia e a função ventricular\nesquerda.","D":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento segmentar da\nparede ventricular, não fornecendo informações sobre a intensidade da isquemia e a função\nventricular esquerda."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-217026","number":"217026","sourceNumber":"217026","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A respeito do manejo clínico da Síndrome Coronariana Aguda, assinale a alternativa\ncorreta.","options":{"A":"O uso de betabloqueador em pacientes com essa síndrome implica redução da mortalidade.","B":"Hipoperfusão, broncoespasmo e tabagismo são contraindicações ao betabloqueador.","C":"A enoxaparina apresenta maior incidência de plaquetopenia que a heparina não fracionada.","D":"Deve-se evitar o uso de nitratos no caso de crepitações ou na presença de B3.","E":"A prescrição de inibidor de ECA e do AAS deve ser precoce à admissão."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-216683","number":"216683","sourceNumber":"216683","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Sabe-se que a troponina, CPK e a fração MB, possuem valores diagnósticos no infarto\nagudo do miocárdio. Temos ciência de que a\ntroponina após o início da dor se eleva de 4-6 horas e\napresenta seu pico de 12-48 horas. Considerando-se essas informações, em quanto tempo ela se\nnormaliza?","options":{"A":"De 7 a 14 dias.","B":"De 1 a 3 dias.","C":"De 3 a 5 dias.","D":"Após 16 dias."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-174409","number":"174409","sourceNumber":"174409","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Diversos estudos utilizaram fibrinolíticos fora do ambiente hospitalar com condições\noperacionais apropriadas para seu uso, e para a monitorização tanto clínicas como\neletrocardiográfica pré-hospitalar dos pacientes e para o tratamento das taquiarritmias. Esses\nestudos consolidaram alguns conceitos, dos apresentados nas alternativas a seguir, assinale o\nINCORRETO.","options":{"A":"A utilização da terapêutica fibrinolítica pré hospitalar baseia-se no conceito clássico\nexperimental\nde que, ao se abreviar o tempo de isquemia\nmiocárdica aguda, reduz-se o tamanho do infarto do\nmiocárdio.","B":"Quanto mais precoce é administrada a terapêutica fibrinolítica, menores a mortalidade e o grau\nde disfunção ventricular.","C":"O retardo pré-hospitalar, intervalo entre o início dos sintomas isquêmicos e a chegada ao\nhospital, não é um dos determinantes do\ntamanho do infarto e da mortalidade pré e intra-hospitalar.","D":"O retardo pré-hospitalar, esse tempo é de, em média, 3 a 4 horas. A utilização pré-hospitalar da\nterapêutica fibrinolítica visa reduzir esse retardo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-175391","number":"175391","sourceNumber":"175391","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 56 anos procura o pronto-socorro por dor torácica, referindo pressão\nretroesternal, irradiada para a mandíbula, desencadeada por esforço, melhorando após 3 minutos\nem repouso, que não se altera com a posição ou com a ventilação. O paciente é atendido 1 hora\napós e no momento está assintomático. O eletrocardiograma é normal. A alternativa que melhor\nrelaciona a hipótese mais provável e a conduta, respectivamente, nesse momento, é:","options":{"A":"angina de peito ? dosagem de troponina","B":"infarto agudo do miocárdio ? ecocardiograma","C":"infarto agudo do miocárdio ? coronariografia","D":"dissecção de aorta ? radiografia de tórax","E":"angina de peito ? teste de esforço"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-174422","number":"174422","sourceNumber":"174422","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentro do uso de medicamentos para tratamento de Síndromes Coronarianas,\npodemos apenas afirmar como CORRETO o seguinte item a\nrespeito do Ácido acetilsalicílico:","options":{"A":"Um dos muitos antiinflamatórios indicados rotineiramente para todos os pacientes com suspeita\nde IAM.","B":"Pacientes com maior risco de doença coronária devem ser instruídos por seus médicos\nassistentes a tomar Ácido Acetilsalicílico (AAS) tamponado em situações emergenciais.","C":"É o antiplaquetário de eleição a ser utilizado no IAM, tendo sido demonstrado sua eficácia.","D":"Tem ação antagônica com o próprio fibrinolítico, levando à associação de ambos os\nmedicamentos a um acréscimo na mortalidade."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-174451","number":"174451","sourceNumber":"174451","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quanto ao uso de nitratos nas Síndromes Coronarianas Agudas, podemos considerar\ncomo INCORRETA a alternativa:","options":{"A":"Podem ser utilizados na formulação sublingual (nitroglicerina, mononitrato de isossorbida ou\ndinitrato de isossorbida), para reversão de eventual espasmo e/ou para alívio da dor anginosa.","B":"Não estão recomendados para controle da hipertensão arterial ou alívio da congestão pulmonar,\nse presentes.","C":"Estão contraindicados na presença de hipotensão arterial (Pressão Arterial Sistólica - PAS <\n90mmHg).","D":"Estão contraindicados com o uso prévio de sildenafil ou similares nas últimas 24 horas e quando\nhouver suspeita de comprometimento do\nVentrículo Direito (VD)."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-173504","number":"173504","sourceNumber":"173504","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"As complicações relacionadas com a doença coronária e, especificamente, com o\nInfarto Agudo do Miocárdio (IAM) são diversas e\nfrequentes. É uma complicação mecânica do IAM:","options":{"A":"Trombose coronariana.","B":"Dissecção coronariana.","C":"Aneurisma de ventrículo esquerdo.","D":"Bloqueio Atrioventricular Total (BAVT)."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-174433","number":"174433","sourceNumber":"174433","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Durante avaliação médica da sala de emergência coronariana, foi solicitado que você\ndesse um parecer fundamentado a respeito da\ncontraindicação de betabloqueadores. Dessa forma,\nem relação aos betabloqueadores, é CORRETO afirmar:","options":{"A":"Na ausência de contraindicações, essa classe de medicamentos deve ser iniciada, de\npreferência, por via endovenosa, após a admissão do paciente.","B":"A utilização de betabloqueador endovenoso deve ser feita com critério, sendo recomendado\natualmente de se utilizar o betabloqueador por via endovenosa nas primeiras 48 horas,\nreservando-se a via endovenosa para casos selecionados, como em pacientes hipertensos e\ntaquicardíacos.","C":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 60 batimentos por\nminutos.","D":"Pacientes com contraindicação para o uso precoce dos betabloqueadores não devem ser\nreavaliados para candidatos a essa terapia na prevenção secundária."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-173520","number":"173520","sourceNumber":"173520","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente dá entrada no pronto-socorro com síndrome coronariana aguda sem\nsupradesnivelamento do segmento ST. A qual tipo de conduta médica esse paciente não poderá\nser submetido?","options":{"A":"Aspirina.","B":"Heparina.","C":"Trombolítico.","D":"Betabloqueador."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-173531","number":"173531","sourceNumber":"173531","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher de 68 anos, hipertensa, fumante e diabética, dá entrada no pronto-socorro com\nforte dor no peito do tipo aperto e\nassociada a sudorese, náusea e palidez, iniciados há 45 minutos.\nO exame físico, o eletrocardiograma e as enzimas cardíacas, realizados imediatamente, foram\nnormais. Qual seria a conduta médica adequada?","options":{"A":"Administrar aspirina e clopidogrel, internar e seriar enzimas e ECG.","B":"Dar alta hospitalar e encaminhar para o ambulatório de cardiologia.","C":"Solicitar cateterismo cardiaco.","D":"Solicitar um teste isquêmico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-182490","number":"182490","sourceNumber":"182490","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 54 anos chega ao pronto atendimento referindo desconforto torácico\ndescrito como sensação de peso e a localiza\ncolocando a mão no esterno, com irradiação para o\nombro esquerdo. O desconforto foi desencadeado após esforço físico habitual. Nega sintomatologia\nsemelhante. A dor aliviou 20 minutos após a chegada ao hospital. Tem diagnóstico, há 3 anos, de\ndislipidemia, e está em uso de sinvastatina 20mg/d. Nesse caso, qual é a hipótese diagnóstica?","options":{"A":"embolia de pulmão","B":"esofagite","C":"síndrome coronariana aguda","D":"pneumotórax"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-185144","number":"185144","sourceNumber":"185144","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Na avaliação de um paciente com infarto agudo do miocárdio com supra de ST, cujos\nsintomas iniciaram há 18 horas, a coronariografia deve ser realizada","options":{"A":"em caráter de urgência, para a realização de angioplastia primária.","B":"na presença de isquemia refratária às medidas farmacológicas.","C":"apenas quando houver falência da terapia com fibrinolíticos.","D":"apenas nos pacientes de risco moderado a alto pelo escore TIMI."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-187602","number":"187602","sourceNumber":"187602","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino realizou um eletrocardiograma que evidenciou a presença de\ndepressão do segmento ST com inversão da\nonda T. O diagnóstico mais provável para o caso é:","options":{"A":"cardiopatia chagástica.","B":"hipertrofia de ventrículo direito.","C":"infarto agudo do miocárdio.","D":"bloqueio átrio ventricular;"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-178865","number":"178865","sourceNumber":"178865","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um adulto de 28 anos procura o serviço médico por causa de dores internas em região\ntorácica. Relata tratar-se de uma dor contínua em todo o hemitórax direito, que começou há\naproximadamente 2 dias, após um jogo de vôlei com os amigos. Em um Raio-X de tórax,\n\nobserva-se a seguinte condição: Após a realização do exame, o adulto refere que a dor piorou e\nobserva-se que ele está dispnéico, com FR = 28 irpm, e taquicárdico, com FC = 121 bpm. Pode-se\nconcluir que o paciente:","options":{"A":"está com um pneumotórax espontâneo que, devido aos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para um pneumotórax hipertensivo. A conduta é de\ntransferência para um serviço de saúde com maior capacidade; mas, caso o doente piore, é\nnecessário realizar a descompressão torácica.","B":"está com um provável tamponamento cardíaco que, em consequência dos sinais de instabilidade\nsúbitos após a realização do exame, está\naumentando rapidamente. A conduta é de tranferência\npara um serviço de saúde com maior capacidade; contudo, caso o doente piore, é necessário\nrealizar a punção de Marfan.","C":"está com uma pneumonia adquirida na comunidade que, pelos sinais de instabilidade súbitos\napós a realização do exame, está progredindo\npara um quadro séptico. A conduta é transferir para\num serviço de saúde com maior capacidade e iniciar hidratação.","D":"está com um tromboembolismo pulmonar que, pelos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para uma insuficiência respiratória. A conduta é é transferir\npara um serviço de saúde com maior capacidade, iniciar hidratação controlada e instalar cateter de\noxigênio a 2 L/min.","E":"está com um provável tumor pulmonar que, por causa dos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para uma insuficiência respiratória. A conduta é de\ntransferência para um serviço de saúde com maior capacidade, com sugestão de encaminhamento\npara o oncologista."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/178865.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-174465","number":"174465","sourceNumber":"174465","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação à necessidade do diagnóstico de Doença Aterosclerótica Coronariana\nSubclínica, marque a opção considerada INCORRETA:","options":{"A":"A identificação de indivíduos assintomáticos portadores de aterosclerose e, dessa forma, sob\nrisco de eventos cardiovasculares agudos, como o infarto e morte, é fundamental para se\ninstituírem medidas de tratamento e prevenção secundária.","B":"Diante da complexidade dessas interações, a atribuição intuitiva do risco frequentemente resulta\nem subestimação ou superestimação dos casos de\nmaior ou menor risco, respectivamente.","C":"Para contornar essa dificuldade, diversos algoritmos têm sido criados com base em análises de\nregressão de estudos populacionais, por meio dos quais a identificação do risco global é\nsubstancialmente aprimorada.","D":"A não identificação de indivíduos assintomáticos portadores de aterosclerose e, dessa forma,\nsob risco de eventos cardiovasculares agudos,\ncomo o infarto e morte, é de pouca importância em\ntermos de prevenção secundária."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-178766","number":"178766","sourceNumber":"178766","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, 71 anos, chega à unidade de saúde, trazida por seu filho, referindo dor\ntorácica em aperto há aproximadamente 30\nminutos, além de sudorese intensa e mal-estar geral.\nNa avaliação da paciente, entende-se que os sintomas são sugestivos de isquemia ou infarto.\n\nPortanto, qual é a melhor conduta?","options":{"A":"Realizar um eletrocardiograma (ECG); administrar aspirina na dose de 500 mg sublingual;\nconsiderar administrar oxigênio (se saturação de\noxigênio \"menor ou igual\" 94%) e nitroglicerina\nsublingual. Em caso de não haver allteração no ECG, por medida preventiva, encaminhar para um\nserviço especializado.","B":"Realizar um eletrocardiograma (ECG) devido à dor intensa; administrar morfina como primeira\nescolha (em solução decimal); considerar\nadministrar oxigênio (se saturação de oxigênio \"menor ou\nigual\" 92%) e aspirina 500 mg, se a dor persistir após morfina. Em caso de alteração no ECG,\ntransferir para uma unidade de saúde com maior capacidade de atendimento.","C":"Realizar um eletrocardiograma (ECG), se possível, de 12 derivações; administrar nitroglicerina\nem spray ou sublingual, como primeira escolha,\ndevido ao quadro álgico intenso; considerar\nadministrar oxigênio (se saturação de oxigênio \"menor ou igual\" 85%) e morfina, se o desconforto\ntorácico não for aliviado pela nitroglicerina. Em caso de não haver alteração no ECG, por medida\npreventiva, encaminhar para um serviço especializado.","D":"Realizar um eletrocardiograma (ECG), se possível, de 6 derivações; administrar aspirina na dose\nde 160 a 325 mg mastigável; considerar\nadministrar oxigênio (se saturação de oxigênio \" menor ou\nigual\" 85%) e morfina, se o desconforto torácico não for aliviado pela nitroglicerina. Em caso de\nnão\nhaver alteração no ECG, por medida preventiva, encaminhar para um serviço especializado.","E":"Realizar um eletrocardiograma (ECG), se possível, de 12 derivações; administrar aspirina na\ndose de 160 a 325 mg mastigável; considerar\nadministrar oxigênio (se saturação de oxigênio \"\nmenor ou igual\" 90%), nitroglicerina sublingual ou spray e, se o desconforto torácico não for\naliviado\npela nitroglicerina, morfina. Em caso de alteração no ECG, transferir para uma unidade de saúde\ncom maior capacidade de atendimento."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183345","number":"183345","sourceNumber":"183345","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O núcleo da equipe é formado por Médicos, Enfermeiras e especialistas em exercícios,\ncom a opção de agregar especialistas em\noutras disciplinas para fornecer ao paciente atendimento\ne educação completa (Nutricionista, Psicólogo, entre outros), dessa forma, podemos considerar\ncomo completamente adequado o item:","options":{"A":"Um programa de reabilitação cardiovascular RCV não necessita de ser integrado por uma\nequipe multidisciplinar.","B":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências: conhecimento\nbásico na área cardiovascular apenas.","C":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências:\nconhecimento básico nas áreas cardiovascular, pulmonar e\nmusculoesquelética, interpretação do eletrocardiograma, manejo de emergências médicas e\nconhecimentos em teoria e prática do exercício físico.","D":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências:\nconhecimento básico nas áreas cardiovascular, pulmonar e\nmusculoesquelética, interpretação do eletrocardiograma é desnecessária, manejo de emergências\nmédicas e conhecimentos em teoria e prática do exercício físico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183343","number":"183343","sourceNumber":"183343","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O cálculo do Índice de Massa Corporal (IMC) tem sido proposto pelo Instituto Nacional\nda Saúde dos Estados Unidos (NHLBI) e pela\nOrganização Mundial da Saúde (OMS) como o\nmétodo convencional para diagnosticar sobrepeso e obesidade. Sendo INCORRETO afirmar que:","options":{"A":"Embora o IMC seja um método simples para detectar sujeitos com aumento considerável de\ngordura corporal, particularmente em âmbito populacional, estudos recentes têm confirmado\ntotalmente a sua validade para diagnosticar obesidade individual.","B":"O obeso tem maior frequência e incidência de outros fatores de risco.","C":"O risco manifesta-se também de forma direta, uma vez que a gordura, particularmente a visceral\nintra-abdominal, é um órgão endócrino, metabolicamente ativo, que sintetiza e libera na circulação\nsanguínea diferentes peptídeos e outros compostos não peptídicos que participam da homeostase\ncardiovascular.","D":"O obeso perde em maior ou menor grau esse equilíbrio e assim o risco também aumenta."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183337","number":"183337","sourceNumber":"183337","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A presença de estenose significativa no Tronco de Coronária Esquerda - TCE tem\ngrande importância prognóstica e impacto na tomada\nde decisão. Em relação a isso, somente NÃO\npodemos concordar com a alternativa:","options":{"A":"Deve-se ter em mente ainda que doença no Tronco de Coronária Esquerda - TCE está\nraramente associada à doença em ramos\nsubsequentes, e a presença de estenoses significativas\nna artéria descendente anterior e/ou na artéria circunflexa pode sub ou superestimar o valor da RFF\nmedida na lesão no TCE.","B":"Presença de estenose significativa no Tronco de Coronária Esquerda - TCE tem grande\nimportância prognóstica, e a determinação do\nsignificado funcional de tais estenoses é fundamental\npara a decisão da estratégia terapêutica.","C":"Revascularização de lesões no Tronco de Coronária Esquerda - TCE não significativas, do ponto\nde vista funcional, pode levar à oclusão\nprecoce dos enxertos cirúrgicos, mesmo que condutos de\nartéria mamária interna esquerda sejam utilizados.","D":"Ademais, deve-se ter em mente que o TCE representa o local da árvore coronária em que a\navaliação angiográfica da gravidade da estenose é mais ambígua e variável."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157348","number":"157348","sourceNumber":"157348","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente homem, 65 anos, tabagista, hipertenso em tratamento adequeado, procura\natendimento de urgência queixando-se de dor em região epigástrica iniciado há 30 minutos. Com\nbase nessas informações e no eletrocardiograma a seguir, assinale a alternativa com o diagnóstico\nprovável. (Conforme imagem do caderno de questões).","options":{"A":"Infarto Agudo em Parede Inferior.","B":"Infarto Agudo em Parede Lateral Alta.","C":"Infarto Agudo em Parede Anterior.","D":"Infarto Agudo Anterior Extenso.","E":"Infarto Agudo em Parede Anterosseptal."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/157348.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-150722","number":"150722","sourceNumber":"150722","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente apresenta-se na emergência com diagnóstico de síndrome coronariana\naguda, com ECG normal, porém com elevação de\nmarcadores enzimáticos de necrose miocárdica.\nNessas condições, a conduta inicial, além das medidas gerais, deve ser:","options":{"A":"Terapia antiplaquetária dupla + terapia anticoagulante (enoxaparina).","B":"Terapia fibrinolítica.","C":"Angioplastia primária dentro das primeiras três horas do quadro.","D":"Terapia anticoagulante (enoxaparina), sem terapia antiplaquetária."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157410","number":"157410","sourceNumber":"157410","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino de 60 anos de idade foi internado no hospital com quadro de dor\ntorácica, estável pela manhã, mas com progressiva piora da dor torácica, que apesar de não\nocorrer positivação dos marcadores de lesão miocárdica, teve indicado cateterismo diagnóstico e\npossivelmente terapêutico por parte da cardiologia. Diversas condutas serão realizadas a fim de\nmelhorar os desfechos desse paciente, dentre eles o uso de medicações que interagem com\nplaquetas. A respeito dessa intervenção, assinale a alternativa considerada INADEQUADA:","options":{"A":"Na utilização de clopidogrel, é preciso ressaltar ainda que, dentre os pacientes submetidos à\ntrombólise, a dose de ataque de 300 mg não deve ser administrada em pacientes acima de 75\nanos.","B":"A dose dobrada de 150 mg/dia de clopidogrel deve ser restrita aos pacientes com baixo risco de\nsangramento.","C":"Em caso de intervenção cirúrgica, o clopidogrel deve ser suspenso 10 dias antes do\nprocedimento.","D":"Para uso de clopidogrel com dose de ataque de 600 mg em pacientes submetidos à ICPP, tem\nse baseado na inibição do receptor do ADP mais rápido que se obtém com essa dose."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-149245","number":"149245","sourceNumber":"149245","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino de 64 anos de idade, com intensa dor torácica, deu entrada no\nhospital com diagnóstico de infarto agudo do miocárdio. Dentre as condutas iniciais a serem\ntomadas para melhor prognóstico, podemos referenciar como ADEQUADO, quanto ao uso de\noxigênio, o seguinte:","options":{"A":"Indicado sempre que ocorrer desconforto respiratório, queda da saturação abaixo de 94% ou\ncongestão pulmonar.","B":"Seu uso, sem indicação precisa, sempre é considerado benéfico.","C":"Seu uso, quando desnecessário, pode provocar vasodilatação sistêmica.","D":"Seu uso, quando desnecessário, pode provocar queda do débito cardíaco."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-156520","number":"156520","sourceNumber":"156520","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Dentre os fatores de risco para doença cardiovascular podemos citar a deficiência de\ncomponentes do complemento.","B":"Segundo a organização mundial de saúde (OMS) as doenças cardiovasculares são as principais\ncausas de óbito no mundo. Somente no Brasil, mais de 300 mil pessoas morrem anualmente","C":"Dentre os Fatores modificáveis para doenças cardiovasculares podemos citar a predisposição\ngenética","D":"Dentre os fatores não modificáveis, para doenças cardiovasculares podemos citar corrigir os\nmaus hábitos de vida e alimentação"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157423","number":"157423","sourceNumber":"157423","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Podemos considerar a aterosclerose como uma doença inflamatória crônica de origem\nmultifatorial que ocorre em resposta à agressão endotelial, que acomete principalmente a camada\níntima de artérias de médio e grande calibres. A formação da placa aterosclerótica se relaciona com\no contido em uma das opções. Aponte-a.","options":{"A":"Agressão ao endotélio vascular devido a diversos fatores de risco, como dislipidemia,\nhipertensão arterial ou tabagismo.","B":"Pela disfunção endotelial diminui a permeabilidade da íntima às lipoproteínas plasmáticas,\nfavorecendo a retenção das mesmas no espaço subendotelial.","C":"As HDL sofrem oxidação, causando a exposição de diversos neo-epitopos e tornando-as\nimunogênicas.","D":"O depósito de lipoproteínas na parede arterial, processo-chave na parada da aterogênese."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157428","number":"157428","sourceNumber":"157428","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"De acordo com a importância epidemiológica das placas de aterosclerose e suas\nrelações com os eventos clínicos trombogênicos, assinale a alternativa CORRETA:","options":{"A":"Placas estáveis caracterizam-se por predomínio de colágeno, desorganizado em capa fibrosa\nespessa, muitas células inflamatórias e núcleo lipídico e necrótico de proporções menores.","B":"As placas instáveis apresentam atividade inflamatória reduzida, especialmente nas suas bordas\nlaterais, com grande atividade proteolítica, núcleo lipídico e necrótico proeminente e capa\nfibrótica\ntênue.","C":"A ruptura desta placa instável expõe material endotelial colágeno altamente trombogênico,\nlevando à formação de um trombo sobrejacente.","D":"O processo de aterotrombose é um dos principais determinantes das manifestações clínicas da\naterosclerose."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-157435","number":"157435","sourceNumber":"157435","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Para se entender a epidemiologia da estratificação de risco cardiovascular para\nadequada prevenção de eventos relacionados com a arteriosclerose, aponte a alternativa\nINCORRETA:","options":{"A":"Um evento coronário agudo é a primeira manifestação da doença aterosclerótica em menos de\num décimo dos indivíduos que apresentam essa\ncomplicação.","B":"Ocorre necessidade de identificação dos indivíduos assintomáticos que estão mais predispostos\npara a prevenção efetiva com a\n\ncorreta definição das metas terapêuticas individuais.","C":"Diversos algoritmos têm sido criados com base em análises de regressão de estudos\npopulacionais, por meio dos quais a identificação\ndo risco global é aprimorada substancialmente.","D":"A estimativa do risco de doença aterosclerótica resulta da somatória do risco associado a cada\num dos fatores de risco mais a potenciação\ncausada por sinergismos entre alguns desses fatores.\n\nDiante da complexidade destas interações, a atribuição\n\nintuitiva do risco frequentemente resulta em subestimação ou superestimação dos casos de maior\nou menor risco."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-138261","number":"138261","sourceNumber":"138261","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 62 anos é atendindo no pronto-socorro com diagnóstico de infarto agudo do\nmiocárdio com supradesnivel do segmento ST. Após realização de checklist, é submetido á\nfibrinólise com estreptoquinase. Após, a infusão da medicação, o paciente ainda refere dor e o ECG\nmantém o supradesnivel do seguimento ST. Nesse caso, o cateterismo cardiaco","options":{"A":"deve ser realizado em caráter de urgência.","B":"está indicado após controle dos sintomas.","C":"deve ser realizado antes da alta hospitalar para estratificação.","D":"está contraindicado após fibrinólise com estreptoquinase."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-127669","number":"127669","sourceNumber":"127669","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 75 anos, tabagista, hipertenso, diabético e dislipidêmico, relata início, há\nseis horas, de dor precordial tipo queimação,\nde forte intensidade, associada a náuseas e vômitos,\npiora com exercício leve, sem fatores de melhora e com irradiação para membro superior esquerdo.\nAo exame, apresenta ritmo cardíaco regular, pressão arterial de 170 x 100 mmHg; SatO? de 92%\nem ar ambiente e com o seguinte ECG: (VER IMAGEM) Nesse caso, a primeira conduta\nterapêutica a ser feita é:","options":{"A":"Encaminhar para cateterismo cardíaco (cineangiocoronariografia).","B":"Prescrever estreptoquinase 1.500.000 UI EV em uma hora.","C":"Prescrever morfina 2 mg EV.","D":"Prescrever aspirina 300 mg VO."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/127669.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-129840","number":"129840","sourceNumber":"129840","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 55 anos, do sexo masculino, se apresenta na emergência com dor\nretroesternal em queimação de forte\nintensidade, de início súbito, que evoluiu posteriormente com\ntonteira, mal-estar importante e dispneia. ECG mostrou supradesnível do segmento ST em D2, D3\ne aVF e BAVT. A artéria mais provavelmente acometida é:","options":{"A":"Artéria coronária direita.","B":"Tronco da coronária esquerda.","C":"Artéria descendente anterior.","D":"Artéria circunflexa."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-136598","number":"136598","sourceNumber":"136598","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente deu entrada no hospital com intensa dor torácica, típica de insuficiência\ncoronariana, seu ECG demonstrava alteração de\nregularização ventricular de V1 até V3. Como sua\npressão arterial era de 190 x 120 mmHg, foi medicado com Nitroglicerina, Atenolol, Captopril, ASS,\nClopidogrel além de Morfina. Qual das medicações listadas necessita de repouso endotelial a fim\nde manter o efeito da medicação?","options":{"A":"AAS.","B":"Nitroglicerina.","C":"Atenolol.","D":"Morfina."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-136615","number":"136615","sourceNumber":"136615","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, sabidamente usuário de substâncias ilícitas, dá entrada no hospital agitado,\ncom dor torácica, dispneia e mal-estar\ngeral. Seu monitor cardíaco demonstra alteração de\nrepolarização de VE, além de uma taquicardia de 180 bpm. Sua pressão é de 195 x 120 mmHg.\nAcompanhante refere uso de cocaína. Qual das condutas abaixo PODE agravar o quadro de\nintoxicação?","options":{"A":"Propranolol.","B":"Diazepam.","C":"Haloperidol.","D":"Nitroprussiato de Sódio."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-136608","number":"136608","sourceNumber":"136608","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente deu entrada no hospital com queixa de dor torácica em aperto e mal-estar de\ninício, aproximadamente, há 1 hora. Seu exame físico demonstra ausculta cardíaca normal e\nausculta pulmonar com murmúrio vesicular normal e sem ruídos adventícios. Sua PA é de 130 x 90\nmmHg, Saturação no oxímetro de pulso de 94%, ECG demonstra alteração de supra de ST em D2,\nD3 e aVF. Medicado com Morfina, Nitroglicerina, AAS, Clopidogrel e Oxigênio. Frente a esse caso,\nqual das condutas abaixo NÃO deve ser indicada?","options":{"A":"Morfina.","B":"Nitroglicerina.","C":"Oxigênio.","D":"Clopidogrel."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-136574","number":"136574","sourceNumber":"136574","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente deu entrada no hospital com quadro de dor torácica típica, de início há 6\nhoras, irradiando para pescoço. Seu ECG\ndemonstra supra de ST nas derivações V1 até V5. Seu\nexame físico demonstra galope em B3 e discreta congestão pulmonar bibasal. Qual das\nmedicações seguintes é contraindicação no momento?","options":{"A":"Nitroglicerina.","B":"Atenolol.","C":"Captopril.","D":"Clopidogrel."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-138643","number":"138643","sourceNumber":"138643","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 74 anos, hipertenso e tabagista foi admitido por dor torácica retroesternal de\nforte intensidade, em pressão, há 1 hora. Ao exame clínico: pulso de 100 bpm, frequência\nrespiratória 20 irpm, pressão arterial 180x100 mmHg em membro superior direito, pulsos\nassimétricos, bulhas cardíacas normofonéticas com sopro diastólico em foco aórtico 3+/6+.\n\nEletrocardiograma mostrou infarto agudo do miocárdio com supradesnivelamento do segmento ST\nde parede inferior. Qual a conduta\nfarmacológica necessária ao paciente neste momento na sala de\nemergência?","options":{"A":"Betabloqueador endovenoso.","B":"Trombólise.","C":"Anticoagulação.","D":"Antiagregação plaquetária."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-109337","number":"109337","sourceNumber":"109337","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A aterosclerose é uma doença sistêmica, na qual ocorre acúmulo de lipídio e de\nmaterial fibroso na camada","options":{"A":"endotelial.","B":"intimal.","C":"média.","D":"muscular."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-111423","number":"111423","sourceNumber":"111423","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Os betabloqueadores são excelentes fármacos que reduzem as morbimortalidades das\nsíndromes coronarianas agudas. Podem ser indicados em situações como:","options":{"A":"Doença Arterial periférica grave.","B":"Pacientes com disfunção grave de VE.","C":"Infarto Agudo do Miocárdio submetido à trombólise farmacológica.","D":"BAV de 2° e 3° graus.","E":"Nenhuma das situações acima."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-112353","number":"112353","sourceNumber":"112353","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A correta abordagem do infarto agudo do miocárdio com supradesnivelamento do\nsegmento ST é fundamental para a redução da morbimortalidade do quadro. Em relação a esta\nabordagem:","options":{"A":"O uso de aspirina é indicado após a terapia de reperfusão ter sido realizada com sucesso.","B":"A monitorização cardíaca contínua pode ser dispensada enquanto se aguarda a terapia de\nreperfusão.","C":"A angioplastia primária é a terapia de escolha com melhores resultados e menores riscos.","D":"A terapia de reperfusão está indicada após a confirmação diagnóstica com os marcadores de\nlesão miocárdica."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-101146","number":"101146","sourceNumber":"101146","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A presença do supradesnivelamento do segmento ST (supra de ST) ao ECG pode ser\nindicativo de:","options":{"A":"infarto agudo do miocárdio, angina de Prizmetal e endocardite.","B":"aneurisma ventricular, quando está presente em uma fase tardia de um infarto do miocárdio com\nsupra de ST.","C":"reperfusão, quando sua diminuição é maior que 25% na derivação de maior amplitude.","D":"infarto agudo do miocárdio, quando sua elevação é maior que 2 mm em mais de uma derivação\nfrontal contígua."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-110218","number":"110218","sourceNumber":"110218","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 67 anos foi admitido no pronto-socorro com quadro de dor torácica\nopressiva em repouso, com irradiação para a\nmandíbula, acompanhada de diaforese com duração\nde duas horas. Paciente é hipertenso, diabético, tabagista e dislipidêmico. O ECG apresenta\ninfradesnivelamento de ST de 2 mm em parede lateral. Relata quadro semelhante há um ano, com\nmelhora espontânea em casa. Diante do quadro clínico apresentado, quais medicações devem ser\nadministradas no pronto-socorro que as publicações científicas demonstram gerar redução de\nmortalidade em pacientes com esse diagnóstico?","options":{"A":"AAS; clopidogrel; heparinas.","B":"Nitratos, beta-bloqueadores, inibidores glicoproteína IIBIIIA.","C":"AAS; clopidogrel; morfina.","D":"Estatinas; morfina; nitratos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-110222","number":"110222","sourceNumber":"110222","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 67 anos foi admitido no pronto-socorro com quadro de dor torácica\nopressiva em repouso, com irradiação para a\nmandíbula, acompanhada de diaforese com duração\nde duas horas. Paciente é hipertenso, diabético, tabagista e dislipidêmico. O ECG apresenta\ninfradesnivelamento de ST de 2 mm em parede lateral. Relata quadro semelhante há um ano, com\nmelhora espontânea em casa. O paciente foi submetido ao protocolo de dor torácica com ECGs\nseriados e dosagem seriada de marcadores de necrose. Ao final de 12 horas após início da dor\nprecordial ele apresentava ECG sem sinais de isquemia, marcadores de necrose sem elevação em\nnenhuma das mensurações e clinicamente não apresentava mais a dor precordial. Nesse caso,\nqual a melhor estratégia de tratamento para o paciente?","options":{"A":"Alta hospitalar, com teste ergométrico em 7 dias.","B":"Internação hospitalar, com cateterismo cardíaco em 24 a 48 horas.","C":"Alta hospitalar, com ecocardiograma de stress em 7 dias.","D":"Alta hospitalar para seguimento ambulatorial precoce."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-84686","number":"84686","sourceNumber":"84686","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"No Infarto Agudo do Miocárdio, as derivações eletrocardiográficas indicam a região\ncoronária onde o trombo se instalou ou o\nespasmo se sucedeu. Sendo assim, pode-se afirmar que\nem um Infarto do Miocárdio de parede lateral, a presença de elevação de ST e ondas Q serão\nencontradas nas seguintes derivações:","options":{"A":"DI, DII e DIII.","B":"DI, AVL, V5 e V6","C":"V1 e V2.","D":"V1, V2, V3 e V4.","E":"DII, DIII e AVF."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-85411","number":"85411","sourceNumber":"85411","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A pesquisa de dor torácica é um desafio para o médico, já que são inúmeras as causas\netiológicas. Marque a alternativa em que os sintomas estão relacionados com o fator causal.","options":{"A":"Na pericardite, a dor é de natureza pleurítica e piora quando o paciente deita, respira ou\ndeglute,\ne melhora na posição sentada e inclinada para\nfrente. O atrito pericárdico é um sinal\npatognomônico.","B":"A embolia pulmonar apresenta, como sintoma mais comum, a dor torácica de início gradativo.\n\nDispneia é sintoma raro.","C":"O prolapso de válvula mitral se apresenta como dor bem localizada no ápice cardíaco e tem\nrelação bem definida com atividades físicas e com irradiação para o epigástrio.","D":"Doenças esofágicas causam dor com características bem distintas da dor coronariana. Não se\napresentam com dor em aperto ou em queimação."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-63218","number":"63218","sourceNumber":"63218","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Se Paulo sofrer um infarto agudo do miocárdio, NÃO recomendaríamos anticoagulação\nplena, se:","options":{"A":"Estiver programada angioplastia coronária transluminal percutânea.","B":"Houver fibrilação atrial ou insuficiência cardíaca de qualquer grau.","C":"Opção terapêutica inicial for de fibrinólise com estreptoquinase.","D":"O infarto for de parede anterior ou de grande extensão.","E":"O ECG não apresentar supradesnivelamento do segmento ST."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-62694","number":"62694","sourceNumber":"62694","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 65 anos, diabético, hipertenso, dislipidêmico, é admitido no serviço de\nemergência com dor precordial de forte\nintensidade, iniciada há quatro horas com irradiação para o\ndorso, associada com sudorese fria, náuseas e vômitos. Nega tabagismo, etilismo, história familiar\nde doença arterial coronariana e refere que ficou internado há 60 dias devido a AVC, sem sequelas.\nAo exame físico, encontrava-se orientado, com palidez cutâneo-mucosa, acianótico e com dispneia\nleve. PA = 90/60 mmHg e FC = 70 bpm, Sat 89%. A ausculta cardíaca apresentava RCR em 2T,\nsem sopros. Ausculta pulmonar normal. O ECG apresentava supradesnivelamento de segmento ST\nem D2, D3 e AVF de 3 mm. Qual das opções terapêuticas oferecidas na admissão, além do\noxigênio, AAS e nitrato sublingual, é a mais apropriada?","options":{"A":"Meperidina e trombolítico.","B":"Betabloqueador e heparinização plena.","C":"Clopidogrel e angioplastia coronariana percutânea primária.","D":"Ticagrelor e trombolítico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-47300","number":"47300","sourceNumber":"47300","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O aumento de mortalidade no infarto agudo do miocárdio está associado ao uso de:","options":{"A":"diltiazem.","B":"anlopidina.","C":"nifedipina.","D":"verapamil."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-51006","number":"51006","sourceNumber":"51006","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O senhor Pedro, um executivo de 56 anos, é admitido ao hospital com dor no peito de 2\nhoras de duração. Sua frequência cardíaca é de 42 bpm, com bradicardia sinusal no ECG, o qual\ntambém revelou supradesnivelamento de ST nas derivações II, III e aVF. Qual o diagnóstico mais\nprovável do senhor Pedro?","options":{"A":"tônus vagal aumentado.","B":"infarto do miocárdio de parede inferior.","C":"aneurisma de aorta.","D":"intoxicação por atropina.","E":"infarto do miocárdio de parede posterior."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-48219","number":"48219","sourceNumber":"48219","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 50 anos apresenta dor tipo pleuropericárdica e febre, que iniciou cerca de 4\nsemanas após infarto agudo do miocárdio. A hipótese diagnóstica mais provável é:","options":{"A":"Síndrome de Dressler.","B":"Pericardite epistenocárdica.","C":"Pericardite bacteriana.","D":"Aneurisma de ventrículo esquerdo.","E":"Reinfarto do miocárdio."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-48245","number":"48245","sourceNumber":"48245","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 60 anos, sem comorbidades conhecidas, refere dor precordial que o obriga\na reduzir as passadas no meio de suas\ncaminhadas diárias, mas que alivia ao repouso. Traz ECG\nnormal. Qual exame para diagnóstico de doença coronariana você solicita:","options":{"A":"Teste ergométrico","B":"Holter cardíaco de 24 horas","C":"Cintilografia miocárdica com dobutamina","D":"Ecocardiograma transesofágico","E":"Ecocardiograma transtorácico com estresse farmacológico"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-47702","number":"47702","sourceNumber":"47702","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 55 anos é admitido no pronto-socorro com dor retroesternal iniciada há\n30 minutos, como irradiação para região\ncervical e dorso, de forte intensidade, sem fator de alívio,\nacompanhada de sudorese fria, náuseas e vômitos. Antecedentes: refere hipertensão arterial\nsistêmica, diabetes mellitus, tabagismo e dislipidemia. Eletrocardiograma: supradesnivelamento do\nsegmento ST de 3 mm em DII, DIII e AVF. Nesse paciente, pode-se encontrar a seguinte alteração:","options":{"A":"Bradicardia com hipotensão devido ao reflexo vagal de Bezold-Jarisch, comum no infarto agudo\nde parede anterior;","B":"Supradesnivelamento do segmento ST em V1 , V3R e V4R, secundário ao infarto agudo do\nventrículo direito;","C":"Presença de pulsos assimétricos, o que exclui o diagnóstico de IAM concomitante à dissecção\nde aorta;","D":"Cineangiocoronariografia demonstrando oclusão da coronária circunflexa."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-48504","number":"48504","sourceNumber":"48504","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 62 anos foi admitido na emergência com quadro de dor precordial de forte\nintensidade, de aproximadamente 50 minutos de duração, acompanhada de sudorese, náuseas e\nvômitos. Foi diagnosticado, através do ECG, infarto agudo do miocárdio inferoapical. As derivações\nque exploram essa lesão incluem D2, D3, AVF e:","options":{"A":"V1 e V2","B":"V3 e V4","C":"V5 e V6","D":"V7 e V8","E":"V1 e V3"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-48160","number":"48160","sourceNumber":"48160","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em um paciente com síndrome coronariana aguda, porém com fatores de risco\ncontrolados, o colesterol LDL deve ser abaixo de:","options":{"A":"200 mg/dL","B":"160 mg/dL","C":"130 mg/dL","D":"100 mg/dL","E":"70 mg/dL"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35616","number":"35616","sourceNumber":"35616","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma mulher de 66 anos, tabagista há 28 anos, obesa, tossidora crônica, em uso de\nenalapril, amlodipina e glimepirida, procura o pronto-socorro com história de ter apresentado, nas\núltimas 4 horas, 2 episódios de dor retroesternal em aperto, com irradiação para as costas e\nduração de cerca de 30 minutos; o último foi há 1 hora. Nos últimos 6 meses procurou atendimento\nde urgência duas vezes por aumento da tosse e dispneia. Está eupneica, com pulso e pressão\narterial normais. É colocada na sala de emergência, ligado o monitor cardíaco e obtido acesso\nvenoso. Solicita-se e eletrocardiograma. É recomendável que receba de imediato:","options":{"A":"Oxigênio, ácido acetilsalicílico e betabloqueador VO.","B":"Morfina EV.","C":"Betabloqueador EV em dose baixa.","D":"Oxigênio em dose baixa e se aguarde o eletrocardiograma antes de qualquer medicação.","E":"Oxigênio em dose baixa e ácido acetilsalicílico."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35628","number":"35628","sourceNumber":"35628","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 56 anos hipertenso e diabético deu entrada no pronto-socorro com duas\nhoras de dor precordial de forte\nintensidade, irradiada para membro superior esquerdo e\nacompanhada de sudorese. O eletrocardiograma apresentava 2 mm de supradesnivelamento do\nsegmento ST em DII, DIII e aVF. Ao exame estava em bom estado geral com palidez cutânea +/++,\nPA = 100 x 70 mmHg, P = 60 (2 extrassístoles por minuto). Coração e pulmão sem alterações.\n\nNega cirurgias ou traumas recentes. Teve infarto há cerca de 4 meses quando recebeu\nestreptoquinase. Qual alternativa contém diagnóstico e o grupo hemodinâmico correto pela\nclassificação de Forrester?","options":{"A":"Infarto inferior, grupo I.","B":"Infarto anterior, grupo I.","C":"Infarto inferior, grupo II.","D":"Infarto anterior, grupo II.","E":"Não se pode fazer o diagnóstico definitivo de IAM sem a dosagem das enzimas cardíacas."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35630","number":"35630","sourceNumber":"35630","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 56 anos hipertenso e diabético deu entrada no pronto-socorro com duas\nhoras de dor precordial de forte\nintensidade, irradiada para membro superior esquerdo e\nacompanhada de sudorese. O eletrocardiograma apresentava 2 mm de supradesnivelamento do\nsegmento ST em DII, DIII e aVF. Ao exame estava em bom estado geral com palidez cutânea +/++,\nPA = 100 x 70 mmHg, P = 60 (2 extrassístoles por minuto). Coração e pulmão sem alterações.\n\nNega cirurgias ou traumas recentes. Teve infarto há cerca de 4 meses quando recebeu\nestreptoquinase. Qual das medicações abaixo não deve ser administrada a este paciente?","options":{"A":"Morfina.","B":"Nitrato sublingual.","C":"Estreptoquinase.","D":"Ácido acetilsalicílico.","E":"Meperidina."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35804","number":"35804","sourceNumber":"35804","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual das opções abaixo é mais indicada para abordagem inicial na suspeita de infarto\nagudo do miocárdio?","options":{"A":"Estreptoquinase, aas, heparina e nitrato.","B":"Morfina, oxigênio, nitrato e aas.","C":"Estreptoquinase, aas, heparina e betabloqueador.","D":"Oxigênio, betabloqueador, nitrato e aas.","E":"Estreptoquinase, aas, oxigênio e adalat."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35810","number":"35810","sourceNumber":"35810","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 65 anos, masculino, tabagista, IMC de 31, procura o pronto-socorro de\nortopedia por apresentar dor torácica, braquialgia esquerda, sudorese e mal-estar, surgidos após\njogo de futebol onde teve \"bola dividida\" com outro jogador, tendo inclusive sido jogado ao chão.\nSua primeira atenção propedêutica visaria a possibilidade de:","options":{"A":"Luxação de ombro.","B":"Trauma torácico na \"bola dividida\".","C":"Dor anginosa.","D":"Pneumonia.","E":"RGE com esofagite."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-26941","number":"26941","sourceNumber":"26941","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Raimundo, 48 anos, branco, tabagista inveterado, sedentário, foi atendido em posto de\nsaúde com quadro de dor epigástrica de forte\nintensidade com duração de 2 horas. Ao exame\nfísico, apresentava sudorese profusa e fria, palidez cutane omucosa, náuseas e vômitos, PA =\n130/70 mmHg, FC = 58 bpm irregular. ECG demonstrou bloqueio AV intermitente e infarto de\nparede inferior. Rx de tórax demonstrou área cardíaca normal sem alargamento de mediastino.\n\nTransferido à UTI após 45 minutos, apresenta-se com PA = 70/40 mmHg, bulhas cardíacas\nabafadas e com turgência jugular. Rx de tórax\nsem alterações em relação ao anterior. ECG com\nQRS de baixa amplitude. O mais provável é:","options":{"A":"Dissecção aórtica","B":"Infarto de ventrículo direito","C":"Infarto anterior","D":"Disfunção de músculo papilar","E":"Ruptura ventricular"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-27197","number":"27197","sourceNumber":"27197","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Qual o diagnóstico provável em situação de: dor precordial intensa, palidez cutânea,\nsudorese profusa, náuseas, com elevação de ck mb e troponina?","options":{"A":"Pericardite aguda.","B":"Taquicardia ventricular.","C":"Edema agudo de pulmão.","D":"Infarto agudo miocárdio.","E":"Dissecção de aorta."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-23009","number":"23009","sourceNumber":"23009","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Nas cirurgias de revascularização do miocárdio,","options":{"A":"os enxertos de veia safena estão sendo menos utilizados.","B":"a artéria radial é o enxerto arterial mais utilizado.","C":"os enxertos de veia safena ocluem cerca de 30% no primeiro ano após a cirurgia.","D":"o uso de dupla mamária está contraindicado em pacientes diabéticos pelo maior risco de\ndeiscência e infecção do esterno."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-22977","number":"22977","sourceNumber":"22977","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em implantes de stents coronarianos após angioplastia,","options":{"A":"o período de maior ocorrência de reestenose é entre três e seis meses.","B":"a trombose intra-stent é prevenida com uso de anticoagulante, mantendo-se o RNI entre 2,5 e 3.","C":"o stent de metal é preferível ao stent farmacológico nas lesões em coronárias de menor\ndiâmetro, segmentares longas e de tronco de coronária esquerda.","D":"a utilização do clopidogrel por um ano previne a reestenose nos stents farmacológicos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-27026","number":"27026","sourceNumber":"27026","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Ao interpretar o resultado do teste ergométrico de um aviador de 35 anos de idade,\nassintomático, o médico deverá considerar que:","options":{"A":"o valor preditivo positivo será muito baixo","B":"o valor preditivo negativo será muito baixo","C":"o teste não tem indicação no caso","D":"o teste tem baixa especificidade","E":"o teste tem baixa sensibilidade"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-11100","number":"11100","sourceNumber":"11100","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Na abordagem inicial do infarto agudo do miocárdio podemos afirmar que:","options":{"A":"O uso de opiódes endovenoso é indicado para diminuir a dor e ansiedade.","B":"A aspirina associada a heparina contraindica o uso de fibrinoliticos.","C":"O uso de betabloqueadores associado a morfinomiméticos aumenta o risco de depressão\nrespiratória.","D":"Alterações do segmento ST, com supradesnível nas derivações D2, D3 e a VF reflete\nobstruções na parede antero-lateral do ventrículo esquerdo.","E":"N.r.a."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-216365","number":"216365","sourceNumber":"216365","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Ao avaliar um paciente com dor torácica aguda, escores de risco como o TIMI ou o\nGRACE se prestam a definir:","options":{"A":"Necessidade de realizar eletrocardiograma na sala de emergência.","B":"Candidatos à estratificação invasiva precoce num contexto de provável síndrome coronariana\nsem supra ST.","C":"Revascularização cirúrgica versus percutânea em pacientes com IAM com supra de ST.","D":"O tipo de dor torácica em: definitivamente anginosa, definitivamente não-anginosa,\nprovavelmente anginosa ou provavelmente não-anginosa."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-105710","number":"105710","sourceNumber":"105710","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 72 anos, masculino, dislipidêmico e diabético controlado, em uso de\nsinvastatina e metformina não é hipertenso.\nNo momento, assintomático. Em avaliação cardiológica\nde rotina, fez ecocardiograma que mostrou: hipertrofia concêntrica de VE, fração de ejeção\npreservada e uma doença valvar pura, além de ausência de hipertensão pulmonar e de quaisquer\noutras alterações nas demais câmaras cardíacas e nas demais valvas. Considerando a valvopatia\nmais provável nesse contexto clínico-epidemiológico, não é correto afirmar sobre essa doença:","options":{"A":"A etiologia mais provável é a degeneração fibrocalcificante. Além disso, sua patogênese parece\nter em comum diversas características da\naterosclerose vascular, incluindo disfunção endotelial.","B":"Há relevante associação estatística de doença coronariana nesses pacientes. A angina de\nesforço é sintoma típico dessa valvopatia.\nTal sintoma pode ser consequência da Doença Arterial\nCoronariana (DAC), da própria fisiopatologia da valvopatia ou mesmo de ambos os mecanismos.","C":"Dispneia aos esforços, ortopneia e edema agudo de pulmão ocorrem precocemente na sua\nhistória natural.","D":"A síncope geralmente ocorre durante esforço físico, devido à vasodilatação periférica causada\npela atividade sem o aumento compensatório do\ndébito cardíaco.","E":"Nos pacientes sintomáticos, o tratamento é eminentemente cirúrgico. Diurético de alça pode ser\nutilizado em pacientes com risco cirúrgico proibitivo ou como ponte para a cirurgia. Além disso, o\nuso não cauteloso, nesses pacientes, de medicamentos, que reduzem a pré-carga, a pós-carga\ne/ou o inotropismo, podem causar hipotensão severa e síndrome de baixo débito."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-105682","number":"105682","sourceNumber":"105682","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Após angioplastia coronariana com stent farmacológico, a prevenção da reestenose de\nenxerto é melhor realizada com:","options":{"A":"Ácido acetilsalicílico + clopidogrel + varfarina ou outro anticoagulante por pelo menos 12\nmeses.","B":"Ácido acetilsalicílico ou clopidogrel por toda a vida.","C":"Ácido acetilsalicílico ou clopidogrel por pelo menos 12 meses.","D":"Ácido acetilsalicílico por toda a vida + clopidogrel por pelo menos 15 dias.","E":"Ácido acetilsalicílico por toda a vida + clopidogrel por pelo menos 12 meses."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-62659","number":"62659","sourceNumber":"62659","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente, 62 anos, recebido no serviço de Urgência/Emergência com queixa de dor\nprecordial, em repouso com duração > 10 minutos. Relata dois episódios semelhantes há uma\nsemana, porém de menor intensidade que o quadro atual. Apresenta história de tabagismo,\ndislipidemia e HAS. Realizou ECG que não mostrou alteração do segmento ST, coletado troponina\nsérica que foi normal na 1ª e 6ª hora. Em relação ao caso, é correto afirmar, EXCETO:","options":{"A":"Caracteriza um quadro de angina instável.","B":"Está indicado uso de inibidor IIb-IIIa plaquetário.","C":"Está indicada realização de cineangiocoronariografia precoce (até 48h).","D":"Não está indicado o CATE na vigência de dor recorrente com hipotensão, apesar da terapia\nanti-isquêmica.","E":"Está indicado uso de heparina não fracionada, betabloqueador, AAS e clopidogrel."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-47478","number":"47478","sourceNumber":"47478","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentre estes marcadores de lesão miocárdica, o que mais rapidamente retorna ao\nnormal após um infarto do miocárdio é:","options":{"A":"Troponina I cardíaca","B":"Troponina T cardíaca","C":"CKMB-massa","D":"Mioglobina","E":"Relação CPK/CKMB"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35750","number":"35750","sourceNumber":"35750","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 60 anos de idade com um histórico de hipertensão e dislipidemia realiza\numa avaliação devido angina. Ele afirma que, rotineiramente, sente dispneia, fadiga e dor torácica\nretroesternal na realização de atividades, como caminhadas ao redor do quarteirão ou subindo as\nescadas dentro de sua casa. Além de tomar medicamentos para a hipertensão e\nhipercolesterolemia, ele usa nitrato, que alivia com sucesso seus sintomas, porém lhe causa\ntaquicardia. Ele não apresenta esta sensação em outro momento. Qual a conduta mais adequada\npara controlar este fenômeno?","options":{"A":"Descontinuar o nitrato.","B":"Aumentar a dose do nitrato.","C":"Usar nifedipina ao invés de nitrato.","D":"Continuar nitrato e iniciar isoproterenol.","E":"Continuar nitrato e iniciar betabloqueador."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-35706","number":"35706","sourceNumber":"35706","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"São critérios para suspensão do tratamento com estatinas:","options":{"A":"TGP > 3x limite superior da normalidade (LSN) e CPK > 5x LSN.","B":"TGP > 10x LSN e CPK > 3x LSN.","C":"Mialgia insuportável embora a CPK seja normal.","D":"TGP > 3x LSN e CPK > 10x LSN.","E":"C e D são corretas."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-11471","number":"11471","sourceNumber":"11471","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Marque a resposta correta:","options":{"A":"A aterosclerose é uma doença inflamatória crônica de origem multifatorial que ocorre em\nresposta a agressão endotelial, acometendo\nprincipalmente a camada média de artérias de médio e\ngrande calibre.","B":"O diagnóstico de síndrome metabólica requer a presença de obesidade abdominal como\ncondição essencial. A pressão arterial sistólica > ou = 135 mmHg não é critério obrigatório.","C":"Os fitosterois, que são encontrados apenas nos vegetais, reduzem a colesterolemia e a\ntrigliceridemia por competirem com absorção destes na luz intestinal.","D":"As estatinas reduzem a mortalidade cardiovascular e incidência de eventos isquêmicos\ncoronários agudos e a necessidade de\nrevascularização do miocárdio; entretanto, não\napresentaram efeito benéfico na redução de incidência de acidente vascular cerebral (AVC).","E":"O ácido nicotínico reduz a ação na lipase tecidual nos adipócitos; levando à redução do\ntriglicerídio e do colesterol LDL e aumentando o colesterol HDL."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-311491","number":"311491","sourceNumber":"311491","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 54 anos, diabético, admitido com dor retroesternal intensa irradiada para\nmandíbula e MSE há 50 minutos. ECG de entrada com ST supra de 5mm de V1 a V6, D1 e AVL.\nQual diagnóstico provável e melhor conduta?","options":{"A":"IAM de parede lateral. Administrar AAS 300mg, clopidogrel 300mg, heparinização plena e\ncateterismo cardíaco.","B":"Espasmo coronário difuso grave. Iniciar nitroglicerina IV e seriar enzimas cardíacas.","C":"IAM de parede anterior extenso. Administrar AAS 300mg, ticagrelor 180mg e encaminhar para\nangioplastia primária em caráter emergencial.","D":"Dissecção aguda de aorta. Solicitar angiotomografia de aorta torácica de urgência.","E":"TEP com repercussão eletrocardiográfica. Heparinização plena e providenciar angiotomografia\nde artérias pulmonares."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-302039","number":"302039","sourceNumber":"302039","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando o profissional de saúde orienta mudanças no estilo de vida é fundamental\nidentificar qual o estágio motivacional que o\nusuário se encontra para poder elaborar a melhor\nestratégia. Prochaska, DiClemente e Norcross (1992) desenvolveram um Modelo de Avaliação do\nGrau de Motivação para a Mudança, descrevendo etapas que podem ser identificadas no discurso\nda pessoa quando indagada acerca de sua vontade de mudança de hábito e de seus planos para\nmudança. Assinale a alternativa que relaciona a fala do paciente e o estágio motivacional quando\nse aborda a cessação do tabagismo.","options":{"A":"Preparação: \"\"Eu tenho tentado parar de fumar de um tempo para cá\"\"","B":"Ação: \"\"Eu não quero parar de fumar\"\".","C":"Pré-contemplação: \"\"Eu voltei a fumar regularmente\"\".","D":"Contemplação: \"\"Eu parei de fumar\"\".","E":"Recaída: \"\"Eu tenho feito uso descontínuo do cigarro de um mês para cá\"\"."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-250391","number":"250391","sourceNumber":"250391","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 68 anos, internado com quadro de angina instável. Qual, dentre as alternativas\nabaixo, NÃO constitui estratificador de alto\nrisco nesta condição clínica?","options":{"A":"Angina noturna.","B":"Dor em repouso prolongada (> 20 minutos) e contínua.","C":"Angina com hipotensão.","D":"Angina associada a sopro sistólico de regurgitação em foco mitral.","E":"Angina em repouso com alterações dinâmicas de ST (igual ou maior do que 1mm)."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-218043","number":"218043","sourceNumber":"218043","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente admitido na unidade coronariana com quadro compatível com IAM anterior\ncom menos de 8 horas de duração. Como não\nexistia hemodinâmica disponível, foi submetido a\ntrombólise com estreptoquinase. Após 30 minutos da infusão inicia arritmia no monitor. Feito um\nECG com o traçado mostrado abaixo. Pergunta-se sobre este paciente: Qual o ritmo registrado no\nECG?","options":{"A":"Fibrilação atrial.","B":"Fibrilação ventricular.","C":"Taquicardia supraventricular com aberrância.","D":"Ritmo idioventricular acelerado.","E":"Ritmo sinusal."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/218043.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-203195","number":"203195","sourceNumber":"203195","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher, 69 anos, é submetida a cateterismo cardíaco para avaliação de uma angina\nestável que não obteve resposta ao tratamento\nclínico. A complicação mais comum do cateterismo\ncardíaco e da angiografia coronariana é:","options":{"A":"Insuficiência renal aguda.","B":"Taquiarritmias.","C":"Bradiarritmia.","D":"Infarto do miocárdio.","E":"Sangramento do local de acesso vascular."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-154409","number":"154409","sourceNumber":"154409","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem, 35 anos, tabagista, hipertenso, refere dor na região anterior do tórax, que piora\ncom decúbito, de início há 8 horas. À admissão, apresentava PA = 160 x 100 mmHg, FC = 120\nbpm, FR = 32 mrpm, Temperatura = 38,0°C. Eletrocardiograma evidenciava elevação difusa de\nsegmento ST com concavidade para cima. Qual das hipótese diagnóstica mais provável?","options":{"A":"Cardiomiopatia hipertrófica.","B":"Dissecção aórtica.","C":"Síndrome coronariana aguda.","D":"Taquiarritmia supraventricular por reentrada.","E":"Pericardite aguda."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-103951","number":"103951","sourceNumber":"103951","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, com 65 anos, foi internado nesta unidade hospitalar com\nquadro de apendicite aguda e será submetido\na procedimento cirúrgico laparoscópico, dentro das 6\nhoras após o diagnóstico clínico e de imagem do quadro. O paciente citado é usuário de AAS de\nlonga data por doença coronária. Marque afirmativa correta:","options":{"A":"Sangue e plaquetas vão dar segurança ao procedimento.","B":"O procedimento deverá ser adiado.","C":"Entrar com antibiótico para esfriar o processo e esperar.","D":"Pós-operatório imediato na unidade de terapia intensiva não será necessário.","E":"A raquianestesia e a cirurgia aberta deverão ser indicadas."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-89551","number":"89551","sourceNumber":"89551","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Na vigência de síndrome coronariana aguda, qual alternativa contempla apenas\nindicações de nitroglicerina endovenosa?","options":{"A":"Dor refratária, congestão pulmonar e hipertensão de difícil controle.","B":"Presença de terceira bulha, arritmia ventricular intermitente e supradesnivelamento do segmento\nST.","C":"Infarto com supra em DII, DIII, aVF, V3R e V4R, insuficiência cardíaca e contraindicação aos\ninibidores de ECA.","D":"Instabilidade hemodinâmica, instabilidade elétrica e dor refratária.","E":"Congestão pulmonar, presença de quarta bulha e insuficiência mitral grave."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-65600","number":"65600","sourceNumber":"65600","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo masculino, 54 anos, queixa-se de dor torácica de início súbito, de\nmoderada a grande intensidade.\nTaquipneico, taquicárdico, com FC = 120 bpm, realizou ECG onde\nse evidencia bloqueio de ramo esquerdo novo ou supostamente novo, não se observa elevação de\nsegmento ST. Devemos considerar como diagnóstico e conduta:","options":{"A":"Angina instável sendo tratada como IAM sem elevação do segmento ST;","B":"A dissecção aguda da aorta, devendo-se realizar anticoagulação plena;","C":"IAM sem supra de segmento ST, devendo ser tratado como tal;","D":"IAM sem supra de ST, porém deve ser considerado e tratado como se fosse IAM com supra de\nST;","E":"Não é uma síndrome coronariana aguda, devendo ser tratado com analgesia."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-65613","number":"65613","sourceNumber":"65613","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O dinitrato de isossorbida deve ser administrado precocemente em pacientes com\nsuspeita de síndrome coronariana aguda,\npreferencialmente após realização do ECG, se este\npuder ser feito rapidamente. Dentre as afirmações abaixo, qual não corresponde à contraindicação\nao seu uso?","options":{"A":"Pressão arterial sistólica inferior a 100 mmHg.","B":"IAM de ventrículo direito.","C":"Uso prévio de Sildenafil nas últimas 24h.","D":"Bradicardia abaixo de 60 bpm.","E":"Bloqueio de ramo esquerdo."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-308317","number":"308317","sourceNumber":"308317","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Sobre a Pericardite Aguda, assinale a afirmativa correta.","options":{"A":"A radiografia de tórax é geralmente alterada, pois pequenos volumes de líquido no pericárdio 30\na 50 mL alteram a silhueta cardíaca.","B":"A grande maioria dos pacientes com pericardite aguda não apresenta dor torácica.","C":"A pericardite aguda pode se manifestar com uma variedade de sinais e sintomas inespecíficos,\ndependendo da etiologia subjacente. No ECG, pode-se observar novo supradesnivelamento do\nsegmento ST generalizado e depressão do PR.","D":"O derrame pericárdico hemorrágico normalmente tem como causa a infecção viral."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-308319","number":"308319","sourceNumber":"308319","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, 52 anos, com história médica pregressa de hipertensão arterial\nsistêmica e síndrome de Marfan, chega à\nemergência com queixa de dor torácica retroesternal em\naperto, com irradiação para o dorso. Nega tabagismo, dislipidemia ou diabetes. Ao exame, paciente\nse apresenta inquieto pela dor constante, sem alívio após uso de nitrato 5 mg sublingual. PA = 200\nx 110 mmHg na chegada e 220 x 110 mmHg 3 minutos após uso de nitrato. Saturação de O? = 96\n\n% em ar ambiente, ausculta cardíaca: ritmo regular, sopro sistólico +++/6 em foco mitral e sopro\ndiastólico ++++/6 foco aórtico. Ausculta\npulmonar sem alterações. Realizou ECG: ritmo sinusal,\nsinais de sobrecarga ventricular, associado a infradesnível do segmento ST em derivações V1 e V2\ne supradesnível em derivações DII, DIII e avF. Após 20 minutos na emergência, paciente evolui\ncom hipotensão e sinais clínicos de choque. A melhor explicação fisiopatológica para o caso é\ninfarto agudo do miocárdio em parede.","options":{"A":"Inferodorsal, causado por dissecção da aorta e insuficiência aórtica aguda e comprometimento\ndo óstio do seio coronário direito, hipotensão\ne choque justificados por provável envolvimento do\nventrículo direito.","B":"Anterosseptal, causando ruptura de cordoalhas do folheto mitral, com consequente choque\nassociado à piora com o uso de nitrato sublingual.","C":"Inferior, causado pela crise hipertensiva e pela síndrome de Marfan. Posterior hipotensão,\njustificada pelo uso de nitrato sublingual.","D":"Inferodorsal, causado por dissecção da aorta e insuficiência aórtica aguda e seu\ncomprometimento da válvula mitral, causando\ninsuficiência mitral aguda e posterior choque devido\na edema agudo de pulmão cardiogênico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-316004","number":"316004","sourceNumber":"316004","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 54 anos chega ao pronto atendimento referindo desconforto torácico\ndescrito como sensação de peso e a localiza\ncolocando a mão no esterno, com irradiação para o\nombro esquerdo. O desconforto foi desencadeado após esforço físico habitual. Nega sintomatologia\nsemelhante. A dor aliviou 20 minutos após chegada ao hospital. Tem diagnóstico, há 3 anos, de\ndislipidemia, e está em uso de sinvastatina 20mg/d. Nesse caso, qual é hipótese diagnóstica?","options":{"A":"Embolia de pulmão","B":"Esofagite","C":"Síndrome coronariana aguda","D":"Pneumotórax","E":"Dissecção de aorta"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-308386","number":"308386","sourceNumber":"308386","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente M. C. S. de 35 anos vem para consulta médica com queixa de ganho de 15 kg\nnos últimos 24 meses, após sua última\ngestação. Refere que tem preferência por doces, não faz\nlanches, passa o dia trabalhando e come mais à noite, quando chega em casa. É sedentária, nega\ntabagismo, nega diagnósticos prévios e não faz uso de qualquer medicação. Teve 3 gestações e 3\npartos vaginais, sem intercorrências. Sua mãe é diabética e seu pai morreu aos 57 anos de infarto\nagudo do miocárdio. Ao exame: peso 89 kg, estatura 155 cm, PA 140 x 85 mmHg, cintura 97 cm.\n\nTraz os seguintes exames: glicemia 104 mg/dL; colesterol total 225 mg/dL; triglicerídeos 188 mg/dL;\nHDL 33mg/dL. Marque a afirmativa correta.","options":{"A":"A paciente apresenta obesidade grau III, pois seu IMC é de 37.","B":"A paciente apresenta diagnóstico de Diabetes Mellitus tipo 2, por apresentar obesidade central\nassociada a alterações na glicemia de jejum.","C":"A paciente deve ser incentivada a iniciar programa de Modificação de Estilo de Vida\nimediatamente, instituindo atividade física regular,\nalimentação saudável e manutenção do peso\nideal.","D":"O diagnóstico de Síndrome Metabólica ainda não pode ser firmado devido à falta de alguns\nexames diagnósticos na história clínica."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-313414","number":"313414","sourceNumber":"313414","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher, 67 anos, hipertensa e diabética de longa data, chega à unidade com quadro de\ndor torácica típica após realização de esforço físico. Realizado eletrocardiograma abaixo: Qual o\ndiagnóstico mais provável?","options":{"A":"Infarto agudo do miocárdio de parede lateral;","B":"Infarto agudo do miocárdio de parede inferior;","C":"Síndrome coronariana aguda sem supra de ST;","D":"Infarto agudo do miocárdio com bloqueio de ramo esquerdo."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/313414.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-274111","number":"274111","sourceNumber":"274111","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher de 41 anos de idade internou no HUJM por dor precordial e dispneia aos\nmoderados esforços. História prévia de\nhipertensão arterial, dislipidemia mista, tabagismo e lúpus\neritematoso sistêmico, desde os 21 anos. Nos últimos meses, queixou-se de quadro de dor\nprecordial do tipo pleurítica, que piorava no decúbito e melhorava com posição sentada.\n\nAntecedente de anemia e convulsões, atribuídas ao lúpus há 2 anos. Ao exame físico, paciente em\nrazoável estado geral, hidratada, eupneica, FC 115 bpm, PA 110 x 70 mmHg. Ausculta pulmonar\nnormal e ausculta cardíaca revelou bulhas rítmicas, hipofonese do componente aórtico da segunda\nbulha e sopro sistólico ++++/6+. O exame do abdome foi normal, não havendo edema e os pulsos,\nsimétricos. O ECG revelou ritmo sinusal, frequência cardíaca de 109 bpm, com ondas T apiculadas\ne elevação do segmento ST. Assinale a alternativa que apresenta os dados semiológicos\nidentificados compatíveis com a fisiopatologia/histologia.","options":{"A":"Miocardite necrotizante eosinofílica ? alterações degenerativas da fibra com hipertrofia e\nfibrose\ninstersticial; sopro sistólico grave ++++/6+.","B":"Pericardite constritiva ? espessamento fibroso acentuado e aderências dos folhetos visceral e\nparietal e calcificação extensa ou em placas; ondas T apiculadas e elevação do segmento ST.","C":"Doença arterial coronariana ? ? de IL-6 associado ao ? de cálcio coronário e TNF-? e IL-17\naumentam a resistência à insulina; PA normal associado à taquicardia com ritmo sinusal.","D":"Insuficiência mitral ? espessamento dos folhetos valvares, áreas de calcificação, fusão\ncomissural e encurtamento de cordoalhas;\nhipofonese do componente aórtico da segunda bulha."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-288136","number":"288136","sourceNumber":"288136","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Todo paciente com dor torácica, atendido num pronto atendimento, deve ser\ninvestigado quanto à presença de doença\nisquêmica coronariana. No ECG, quando surge o\nsupradesnivelamento do segmento ST de pelo menos 2 mm em duas derivações precordiais\nadjacentes, o paciente deve ser considerado candidato ao tratamento de reperfusão. Em relação ao\ninfarto agudo do miocárdio (IAM), assinale a afirmativa CORRETA.","options":{"A":"A creatinofosfoquinase (CK) eleva-se durante o período de 4 a 8 h e geralmente retorna ao\nnormal em 48 a 72 horas.","B":"A troponina T não é um bom biomarcador cardíaco num IAM.","C":"A morfina não é um analgésico eficaz no tratamento da dor em um paciente com IAM e ainda\npode aumentar a constrição arteriolar.","D":"A fibrinólise deve ser iniciada mesmo se houver contraindicações, como sangramento ativo."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-283991","number":"283991","sourceNumber":"283991","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher, 67 anos, hipertensa e diabética de longa data, chega à unidade com quadro de\ndor torácica típica após realização de esforço físico. Realizado eletrocardiograma abaixo: Qual o\ndiagnóstico mais provável?","options":{"A":"Infarto agudo do miocárdio de parede lateral.","B":"Infarto agudo do miocárdio de parede inferior.","C":"Síndrome coronariana aguda sem supra de ST.","D":"Infarto agudo do miocárdio com bloqueio de ramo esquerdo."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/283991.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-244785","number":"244785","sourceNumber":"244785","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma mulher jovem apresenta quadro de febre recorrente por acometimento das vias\naéreas superiores, acompanhada de dor torácica, que varia com a respiração e a posição do tórax,\nvariando, também, de intensidade e duração. Seu exame físico revela a presença de um atrito\npericárdico. Das situações a seguir, qual não indica a necessidade de internação hospitalar?","options":{"A":"Elevação de enzimas de necrose miocárdica","B":"Febre acima de 38°C e leucocitose","C":"Derrames pericárdicos volumosos, com ou sem tamponamento cardíaco","D":"Acometimento em imunocomprometidos","E":"Presença de bloqueio do ramo esquerdo no eletrocardiograma"},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-221391","number":"221391","sourceNumber":"221391","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A eficácia do AAS durante as primeiras 24 horas do IAMCSST foi demonstrada\ninicialmente. A dose apresenta a seguinte alternativa como CORRETA:","options":{"A":"No entanto, a utilização de doses altas de AAS não associada a aumento significante das taxas\nde sangramento menor.","B":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), foi evidenciada diferença significante entre os dois grupos no desfecho primário de morte\ncardiovascular, IAM ou AVC até 30 dias de acompanhamento.","C":"No entanto, a utilização de doses altas de AAS esteve associada a aumento insignificante das\ntaxas de sangramento menor.","D":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), não foi evidenciada diferença significante entre os dois grupos no desfecho primário de morte\ncardiovascular, IAM ou AVC até 30 dias de acompanhamento."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-221398","number":"221398","sourceNumber":"221398","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A eficácia e segurança da terapia antiplaquetária dupla TAD pós-intervenção coronária\npercutânea ICP em pacientes com alto risco de sangramento tem sido avaliada em estudos\nrecentes. Podemos apenas concordar com o item:","options":{"A":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes não representa um\ndesafio na prática clínica devido ao elevado risco de\ncomplicações hemorrágicas associada à terapia tripla.","B":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nsem uso de anticoagulantes ainda representa\num desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas associada à terapia tripla.","C":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda representa um desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas associada à terapia tripla.","D":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda representa um desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas não associadas à terapia tripla."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-221389","number":"221389","sourceNumber":"221389","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Ticagrelor é um novo fármaco antagonista reversível do receptor não tienopiridínico\nP2Y12, sendo adequado o seguinte ao seu respeito:","options":{"A":"Necessita de processo de conversão metabólica para um componente ativo.","B":"Não necessita de processo de conversão metabólica para um componente inativo.","C":"Não necessita de processo de conversão metabólica para um componente ativo.","D":"Não necessita de processo de desconversão metabólica para um componente ativo."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-214586","number":"214586","sourceNumber":"214586","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 55 anos, hipertenso e tabagista, deu entrada no PA com queixa de\ndesconforto epigástrico há uma hora. Ao exame\nfísico, apresenta-se com PA = 80 x 50 mmHg; FC\n\n= 60 bpm; pálido e sudoreico, com pulsos filiformes, pulmões sem estertores, ausência de B3 ou\nsopros cardíacos. ECG mostra\nsupradesnivelamento do segmento ST de 3 mm nas derivações D2,\nD3 e aVF. Qual é o diagnóstico e a conduta mais adequada?","options":{"A":"Infarto inferior com repercussão hemodinâmica; iniciar infusão de dobutamina + noradrenalina e\navaliar V3R e V4R.","B":"Infarto de ventrículo direito; iniciar infusão de volume com cristaloide e dobutamina.","C":"Infarto de ventrículo direito; iniciar infusão de volume com cristaloide e noradrenalina.","D":"Infarto inferior com hipotensão arterial importante; iniciar infusão de volume com cristaloides e\navaliar V3R e V4R."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-208559","number":"208559","sourceNumber":"208559","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 50 anos foi admitido em unidade de pronto atendimento com relato de\ndor torácica súbita, de leve intensidade, em\naperto, iniciado a 15 minutos de sua admissão. Após\nrápida coleta de enzimas de injuria miocárdica, seu eletrocardiograma revelou corrente de lesão\nsubepicárdica nas derivações D2, D3 e aVF. Ao exame físico, apresentava PA=160x80 mmHg e\nFC=100bpm. Em se tratando de infarto agudo do miocárdio, qual dos critérios a seguir determina a\nreperfusão coronariana imediata?","options":{"A":"característica da dor torácica","B":"achado eletrocardiográfico","C":"nível de pressão arterial","D":"frequência cardíaca","E":"valores das enzimas cardíacas"},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-177321","number":"177321","sourceNumber":"177321","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 69 anos apresenta quadro de angina instável e deve ser submetido a\ncateterismo cardíaco. Ele está internado em unidade coronariana, com pressão arterial controlada e\nFC = 66 bpm. A creatinina é de 1,2 mg%. A complicação mais esperada para essa angiografia é:","options":{"A":"lesão renal aguda intrínseca","B":"infarto agudo do miocárdio","C":"taquiarritmia pós-procedimento","D":"sangramento do local de punção","E":"obstrução arterial aguda em femoral"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-158189","number":"158189","sourceNumber":"158189","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente diabético foi submetido à angioplastia primária e implante de stent na artéria\ndescendente anterior por IAM. Apresentou evolução satisfatória e a coronariografia não mostrou\nlesões significativas nas demais coronárias. Após 5 dias, recebeu alta hospitalar. NÃO é droga\nutilizada na prevenção secundária desse paciente:","options":{"A":"Nitrato.","B":"Estatina.","C":"Clopidogrel.","D":"IECA."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-136992","number":"136992","sourceNumber":"136992","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação ao Infarto Agudo do Miocárdio, pode-se afirmar:","options":{"A":"A administração de fibrinolítico pré-hospitalar pode ser realizada para reduzir a mortalidade\ne grau de disfunção ventricular, sendo\nestreptoquinase a melhor opção.","B":"A presença de condução lenta e fragmentada favorece o surgimento de arritmias\nventriculares por reentrada; o ECG de alta resolução pode ajudar na estratificação de risco.","C":"As troponinas são proteínas do complexo de regulação miofibrilar cardíaco, por isso a Troponina\nC é um marcador específico cardíaco.","D":"A realização do ECG no local do atendimento e sua interpretação por médico habilitado não\nresultam em impacto na redução do tempo porta-agulha ou porta-balão."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-137000","number":"137000","sourceNumber":"137000","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Considerando a doença arterial coronária em diabéticos, assinale a afirmativa correta.","options":{"A":"Devido ao alto risco de doença arterial coronária em diabéticos, pelo menos um exame de\nimagem para estratificação deve ser realizado após os 50 anos.","B":"AAS 81 ? 100 mg/dia está indicado para prevenção de eventos cardiovasculares em\ntodos os pacientes diabéticos, independente do sexo e idade.","C":"As tiazolinedionas, agentes que melhoram a sensibilidade à insulina, são de escolha\npara o controle da glicemia após o IAM,\ndevido à ausência de efeitos colaterais cardiovasculares.","D":"Estatinas devem ser administradas a pacientes diabéticos com doença cerebrovascular\nconhecida ou com idade > 40 anos,\nindependentemente do nível de colesterol."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-85032","number":"85032","sourceNumber":"85032","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente sexo masculino, 77 anos, diabético tipo 2, coronariopata, com\nrevascularização do miocárdio cirúrgica há 8\nanos, chegou ao pronto-socorro com quadro de dor\nprecordial com as mesmas características do infarto agudo do miocárdio ocorrido há 9 anos,\nacompanhado de palidez e sudorese. Exame físico: PA: 140 × 90 mmHg; FC: 80 bpm; peso: 80 kg.\nBom estado geral, ansioso, pálido, hidratado, afebril. Em uso de ácido acetilsalicílico 100 mg/dia,\nmetformina 850 mg 3×/dia, captopril 50 mg 3×/dia, atenolol 25 mg/dia, sinvastatina 20 mg/dia.\n\nForam realizadas 3 troponinas negativas e CK-MB = 100 (normal até 25 mg/dl). Qual a hipótese\ndiagnóstica e o destino desse paciente?","options":{"A":"Angina Instável/Hemodinâmica.","B":"Angina Instável/Unidade de Terapia Intensiva (UTI).","C":"Infarto Agudo do Miocárdio/Hemodinâmica.","D":"Infarto Agudo do Miocárdio/Enfermaria de Cardiologia."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-88433","number":"88433","sourceNumber":"88433","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente 45 anos, tabagista, obeso e hipertenso apresenta dor pré-cordial com\nirradiação para o membro superior esquerdo\nmesmo em repouso, ECG não apresenta supra de ST,\nlaboratório sem elevações de marcadores, diagnóstico mais provável:","options":{"A":"Infarto Agudo do Miocárdio.","B":"Infarto Agudo do Miocárdio sem supra-ST.","C":"Angina instável.","D":"Angina estável."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-301651","number":"301651","sourceNumber":"301651","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com relação ao Brasil, não existem dados suficientes para análise detalhada quanto à\nevolução do consumo percentual de gorduras:","options":{"A":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, não mostraram diminuição significativa nas despesas domiciliares com\nóleos e gorduras.","B":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram\ndiminuição significativa nas despesas domiciliares com óleos e\ngorduras.","C":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram aumento significativo nas despesas domiciliares com óleos e\ngorduras.","D":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram diminuição não significativa nas despesas domiciliares com\nóleos e gorduras."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-284213","number":"284213","sourceNumber":"284213","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em coronariopatas estáveis, a Reabilitação Cardiovascular (RCV) é uma estratégia\nque, em termos de custo-efetividade, está de\nacordo com o item:","options":{"A":"Não é capaz de superar procedimentos amplamente utilizados no país, tais como a intervenção\ncoronariana percutânea (ICP).","B":"Supera, com larga margem, procedimentos amplamente utilizados no país, tais como a\nintervenção coronariana percutânea (ICP).","C":"Supera, com larga margem, procedimentos amplamente utilizados no país, exceto a intervenção\ncoronariana percutânea (ICP).","D":"Nunca supera, somente a coronariana não percutânea."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-239610","number":"239610","sourceNumber":"239610","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Nos últimos 30 anos, o tratamento dos fatores de risco cardiovascular resultou na\nredução de 50% das mortes por DAC, em\ngrande parte devido ao advento das estatinas. Podemos\naceitar que:","options":{"A":"A doença arterial coronariana (DAC) não é a principal causa de mortalidade no mundo ocidental.","B":"As estatinas são hoje a droga mais prescrita no mundo, atrás apenas dos anti-hipertensivos.","C":"A eficácia comprovada e o bom perfil de segurança, aliados ao baixo custo, têm sido os\nprincipais determinantes do aumento do uso.","D":"O grande debate atual sobre a prevenção de doenças cardiovasculares refere-se cada vez mais\nà questão de como e não quando usar estatinas no controle efetivo do risco cardiovascular mesmo\ncom banalização e supertratamento com potencial aumento de efeitos adversos."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-239611","number":"239611","sourceNumber":"239611","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A fisiopatologia do IAM perioperatório difere um pouco da do IAM espontâneo. O item\nerrado é:","options":{"A":"No IAM perioperatório, a ruptura de placa ocorre em aproximadamente metade dos casos; o\nrestante se dá por um desequilíbrio prolongado entre a redução da oferta de oxigênio para o\nmiocárdio (anemia, baixo fluxo etc.) e o aumento da demanda arterial coronariana (taquicardia e\nhipertensão).","B":"TE - teste de esforço é uma ferramenta segura, útil e eficaz para a detecção de isquemia\nmiocárdica, tendo justamente como mecanismo\nproduzir este desbalanço entre oferta e demanda.","C":"Detecção de anormalidades durante execução TE - teste de esforço possa ser reprodutível\ndurante o perioperatório e seus variados\nníveis de estresse.","D":"Deve se considerar que, quanto menor a prevalência da doença coronária em determinada\npopulação, maior será também o valor preditivo positivo do TE."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-243736","number":"243736","sourceNumber":"243736","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"João, 49 anos, IMC de 39, tabagista, hipertenso e diabético em uso regular de\nhidroclorotiazida, anlodipina e metformina.\nEstá com dor do tipo aperto em região torácica anterior\nesquerda iniciada há alguns minutos, após subir 3 lances de escada para chegar ao ambulatório.\nDurante a anamnese, conta sobre crises frequentes de \"dor no coração\" com piora ao estresse\nemocional e às atividades físicas. Exame físico normal, sem reprodução de dor à palpação de\nregião torácica e ECG de repouso normal. Ao final do exame ele não sente mais dor. Sobre o caso,\né possível afirmar que:","options":{"A":"muitos pacientes com dor torácica referem que a dor pode ser de origem cardíaca, mas isso não\ntem nenhum valor semiológico","B":"o eletrocardiograma de repouso sem alterações e a melhora espontânea da dor permitem\nafastar a possibilidade de cardiopatia\nisquêmica","C":"apresentar dor torácica não reprodutível à palpação e com piora ao realizar atividade física\ntorna\nmuito provável que a causa seja doença arterial coronariana","D":"em pacientes diabéticos, o padrão de apresentação de angina é diferente de pacientes não\ndiabéticos, fazendo com que a queixa de dor torácica não seja tão importante"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-239620","number":"239620","sourceNumber":"239620","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O aumento da sensibilidade dos kits disponíveis das troponinas propiciou uma maior\nacurácia e rapidez no diagnóstico ou não do IAM em pacientes com dor torácica na sala de\nemergência. Não podemos apenas concordar com o item:","options":{"A":"No perioperatório de operações não cardíacas, as evidências científicas disponíveis incluem\ntodas as troponinas (I e T) e todos métodos\nutilizados para sua dosagem, que apresentam limites\nde detecção e valores de referência diferentes.","B":"O limite de detecção significa o mínimo valor que é detectado pelo método.","C":"O valor de referência da normalidade é determinado utilizando o percentil 99, que é obtido\nrealizando-se o exame em uma população normal e significa que 99% dos indivíduos normais\napresentam valores abaixo deste cut-off.","D":"Os kits de troponina podem ser classificados em baixa (convencionais), média (contemporâneos\nou sensíveis) ou alta sensibilidade."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-239621","number":"239621","sourceNumber":"239621","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Definir a melhor maneira de tratar esses pacientes submetidos à ICP Intervenção\nCoronária Percutânea torna-se fundamental,\nprincipalmente quanto à associação de medicamentos\nantiplaquetários e anticoagulantes. Não podemos aceitar que:","options":{"A":"Aproximadamente 6 a 8% dos pacientes submetidos à ICP têm indicação concomitante de\nutilização de anticoagulantes orais em longo prazo.","B":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como FA ou valvas biológicas.","C":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como valvas mecânicas.","D":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como o tromboembolismo."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-221224","number":"221224","sourceNumber":"221224","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A eficácia do AAS durante as primeiras 24 horas do IAMCSST foi demonstrada\ninicialmente. A dose apresenta a seguinte alternativa\n\ncomo CORRETA:","options":{"A":"No entanto, a utilização de doses altas de AAS não associada a aumento significante das taxas\nde sangramento menor","B":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), foi evidenciada diferença\n\nsignificante entre os dois grupos no desfecho primário de morte cardiovascular, IAM ou AVC até 30\ndias de acompanhamento","C":"No entanto, a utilização de doses altas de AAS esteve associada a aumento insignificante das\ntaxas de sangramento menor.","D":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), não foi evidenciada\n\ndiferença significante entre os dois grupos no desfecho primário de morte cardiovascular, IAM ou\nAVC até 30 dias de\n\nacompanhamento."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-221253","number":"221253","sourceNumber":"221253","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A eficácia e segurança da terapia antiplaquetária dupla TAD pós-intervenção coronária\npercutânea ICP em pacientes com alto risco de\n\nsangramento tem sido avaliada em estudos recentes. Podemos apenas concordar com o item:","options":{"A":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes não\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","B":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nsem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","C":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","D":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nnão associadas à terapia tripla."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-216819","number":"216819","sourceNumber":"216819","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 75 anos, tabagista, hipertenso, chega ao pronto-socorro com dor\nretroesternal em aperto, a dor é intensa, e\npersiste durante o deslocamento do paciente até o\nhospital mais próximo (45 minutos). Ao exame físico, paciente apresenta-se sudoreico, pálido, com\nB4 à ausculta cardíaca. O ECG feito na admissão revelou inversão de onda T e a troponina\nencontrava-se elevada. Qual é o seu provável diagnóstico?","options":{"A":"Miocardite.","B":"Infarto agudo do miocárdio com supra de segmento ST.","C":"Infarto agudo do miocárdio sem supra de segmento ST.","D":"Angina instável."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-214099","number":"214099","sourceNumber":"214099","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher com 50 anos, obesa, hipertensa não controlada, recém-separada do marido,\napresenta-se à consulta médica com dor torácica típica, teste ergométrico positivo e\ncineangiocoronariografia normal. No que diz respeito ao tema esquematizado nesse exemplo,\nassinale a alternativa correta.","options":{"A":"Durante testes de estresse como Teste Ergométrico, muitos desses pacientes desenvolvem dor\ntorácica e alterações eletrocardiográficas de isquemia, porém alterações cintilográficas de isquemia\nnão são presentes.","B":"Durante os perídos de maior demanda de oxigênio pelo miocárdio como exercícios físicos, esses\npacientes não produziram evidência bioquímica consistente de isquemia como elevados níveis de\nlactato pelo miocárdio.","C":"Não foram produzidas evidências de disfunção microvascular com reserva vasodilatadora\ninadequada nesses indivíduos.","D":"Aumento da sensibilidade à dor e distúbios psiquiátricos não foram correlacionados a indivíduos\ncom essa síndrome.","E":"A incidência de calcificação coronária nas imagens de tomografia computodorizada com\nmúltiplos cortes é igual a dos indivíduos-controle."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-214101","number":"214101","sourceNumber":"214101","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dá entrada na maternidade uma mulher de 40 anos, G3P2A0 com 36 semanas da\ngestação, precordialgia intensa típica iniciada há 60 minutos. O ECG demostra\nsupradesnivelamento de 3 mm do segmento ST em parede anterior. Sobre isso, é correto afirma\nque","options":{"A":"o infarto agudo do miocárdio é raro em mulheres em idade fértil, e a gestação não é fator de\nrisco para IAM.","B":"a dissecção da artéria coronária é a causa mais provável de IAM no período periparto.","C":"o IAM pode ocorrer durante qualquer estágio da gestação e é mais freguente em primíparas,\nsendo que a maioria dos eventos ocorre em\nmulheres menor que 30 anos e na maior parte do\ntempo a localização é a parede inferior.","D":"os fatores de risco tradicionais não estão presentes com frequência entre aquelas que\nexperimentam IAM durante a gestação, incluindo\ntabagismo, hiperlipidemia, hipertensão e diabetes.","E":"a angiocoronariografia de urgência deve ser evitada nessas situações."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-177891","number":"177891","sourceNumber":"177891","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um paciente de 70 anos procura o ambulatório de cardiologia com sintomas típicos de\nangina pectoris. Tem história prévia de IAM a cerca de 7 anos e há 4 meses iniciou dor\nretroesternal típica. Faz uso regular de antiadesivo plaquetário, além de isossorbida e\nbetabloqueador em doses tradicionais. O exame físico encontra-se praticamente normal, apenas\ncom bloqueio de ramo esquerdo no ECG de repouso. Em relação à propedêutica, qual seria o\nmelhor exame para avaliar o quadro clínico desse paciente?","options":{"A":"Ecocardiograma com stress farmacológico.","B":"Cateterismo cardíaco.","C":"Ressonância nuclear magnética do miocárdio.","D":"Cintilografia perfusional miocárdica.","E":"Teste ergométrico."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-187414","number":"187414","sourceNumber":"187414","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente masculino, motorista de ônibus, 55 anos, tabagista, sedentário, que ingere em\nmédia duas cervejas por dia. Procurou serviço médico contando ser assintomático e ter sido\ndetectada pressão arterial elevada em exame para renovação de carteira de motorista.\n\nAntecedentes familiares positivos: pai teve infarto agudo do miocárdio aos 50 anos. Exame físico:\npeso=85 Kg; altura=168 cm; circunferência de cintura= 104 cm; pressão arterial=160 X 96 mmHg\n(medida três vezes nas posições deitado e sentado); frequência cardíaca= 84 bpm. Restante do\nexame físico sem alterações. Avaliação laboratorial demonstrou: ECG normal; creatinina=0,8\nmg/dL; glicemia=90 mg/dL; colesterol total= 260 mg/dL; HDL-C= 50 mg/dL; VLDL-C= 35 mg/dL;\ntriglicerídeos= 175 mg/dL; K+ = 4,5 mEq/L; ácido úrico= 6,8 mg/dL; urina I normal. Trata-se de\npaciente com:","options":{"A":"Risco cardiovascular alto","B":"Risco cardiovascular baixo","C":"Risco cardiovascular médio","D":"Risco cardiovascular muito alto","E":"Sem risco cardiovascular"},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-183517","number":"183517","sourceNumber":"183517","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, com antecedente de hipertensão arterial com\ntratamento irregular, dá entrada em sala de\npronto atendimento com história de dor torácica há 2\nhoras. O ECG de entrada é: Assinale a alternativa que fornece CORRETAMENTE o diagnóstico e a\nconduta.","options":{"A":"Síndrome coronariana aguda com supra do segmento ST inferolaterodorsal. Trombólise química\nou angioplastia primária.","B":"Síndrome coronariana aguda com supra do segmento ST inferolaterodorsal: solicitar enzimas\ncardíacas e CT de tórax para descartar dissecção de aorta.","C":"Pericardite aguda. Supradifuso do segmento ST: solicitar ecocardiograma e introduzir\nibuprofeno.","D":"Tromboembolismo pulmonar. S1Q3T3: solicitar CT de tórax e ecocardiograma para avaliar\nfunção do VD. Trombólise caso VD com disfunção sistólica.","E":"Dissecção de aorta: solicitar CT de tórax com urgência."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-152285","number":"152285","sourceNumber":"152285","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher de 40 anos de idade, hipertensa, fumante e com histórico de uso de\nanticoncepcional oral, procura atendimento\nmédico com dor no ombro esquerdo, dispneia e\ndiaforese. Realizado avaliação física encontra sudorese fria e pegajosa, dispneia, taquipneia e\nestertores crepitantes bi basais. ECG demonstra supra de ST em V1, V2, V3 e V4. Dessa forma,\nassinale a alternativa CORRETA.","options":{"A":"Indicar angioplastia facilitada.","B":"Contraindicar beta bloqueador.","C":"Contraindicar oxigênio suplementar.","D":"Contraindicar analgésico com opioide."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-152291","number":"152291","sourceNumber":"152291","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher de 54 anos de idade, hipertensa, fumante e com histórico de uso de\nanticoncepcional oral, procura atendimento médico com dor no ombro esquerdo, dispneia e\ndiaforese. Realizado avaliação física encontra sudorese fria, dispneia, taquipneia e estertores\ncrepitantes bi-basais. ECG demonstra supra de ST em V1, V2 e V3. Dessa forma, o tratamento\nADEQUADO deve ser feito com:","options":{"A":"Atenolol oral.","B":"Metoprolol venoso.","C":"Aspirina.","D":"Trombolítico seguido de angioplastia (facilitada)."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-152264","number":"152264","sourceNumber":"152264","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente com cirurgia de revascularização do miocárdio prévia refere dor precordial,\ncom 2 horas de evolução e apresenta\nsupradesnivelamento de segmento S-T em parede\ndiafragmática e marcadores cardíacos alterados. Nesse caso, qual é a conduta IMEDIATA?","options":{"A":"Encaminhamento para estudo hemodinâmico.","B":"Administração de fibrinolítico em Unidade Coronariana.","C":"Avaliação de fatores de risco e acompanhamento com marcadores cardíacos.","D":"Encaminhamento para cirurgia cardíaca."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-107003","number":"107003","sourceNumber":"107003","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A necessidade de doses cada vez maiores e a perda de eficiência da medicação\nanti-hipertensiva e antianginosa das famílias dos ditos nitratos, está MELHOR explicada pela\nafirmativa:","options":{"A":"filtração renal.","B":"metabolismo hepático.","C":"metabolismo endotelial.","D":"resistência cárdica."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-106937","number":"106937","sourceNumber":"106937","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando classificamos a gravidade das doenças, interessa-nos a correlação com a\nmortalidade das mesmas. Nesse aspecto, a classificação de Infarto Agudo do Miocárdio de Killip\nmostra-se bastante interessante, utilizando como parâmetros básicos:","options":{"A":"O eletrocardiograma.","B":"O ecocardiograma.","C":"A hemodinâmica.","D":"O exame físico."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-106996","number":"106996","sourceNumber":"106996","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Das alternativas abaixo, aponte a que pode ser considerada como diagnóstico\nalternativo de dor torácica cardíaca de origem não isquêmica.","options":{"A":"Pericardite, Prolapso Mitral e Dissecção Aórtica.","B":"Ponte Miocárdica e Síndrome Cardíaca X.","C":"Angina de Prinzmetal.","D":"Espasmo Esofágico e Refluxo Esofágico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-81211","number":"81211","sourceNumber":"81211","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Assinale a alternativa que contenha, apenas, patologias que são diagnósticos\ndiferenciais de infarto agudo do miocárdio:","options":{"A":"Pericardite, derrame pericárdio, amigdalite, traqueobronquite.","B":"Dissecção aguda de aorta, colecistopatia, pancreatite, infecção do trato urinário.","C":"Dissecção aguda de aorta, colecistopatia, pancreatite, pneumotórax, pneumonia, traumatismo\ncranioencefálico.","D":"Dissecção aguda de aorta, espasmo de esôfago, pneumotórax, pancreatite, patologias da\ncoluna vertebral.","E":"Cisto de ovário roto, litíase biliar e Aneurisma da veia da Galeno."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-81216","number":"81216","sourceNumber":"81216","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Assinale a alternativa que contém, somente, contraindicações absolutas para o uso de\ntrombolíticos:","options":{"A":"Gravidez, arritmia cardíaca, pneumonia e tromboembolismo pulmonar.","B":"Hemorragia digestiva alta, acidente vascular cerebral hemorrágico, massagem cardíaca externa\ntraumática e menstruação.","C":"Hemorragia digestiva alta ativa, acidente vascular cerebral hemorrágico, dor abdominal difusa e\ngravidez.","D":"Hemorragia digestiva ativa, acidente vascular cerebral hemorrágico e dissecção aguda de aorta.","E":"Hipertensão arterial sistêmica controlada, diabetes, insuficiência renal aguda e DPOC."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-60288","number":"60288","sourceNumber":"60288","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Quando empregamos fibrinolíticos, qual das contraindicações absolutas não está\ncorreta?","options":{"A":"Sangramento intracraniano.","B":"Período menstrual.","C":"AVC isquêmico nos últimos 6 meses.","D":"Neoplasia do sistema nervoso central.","E":"Suspeita de dissecção de aorta."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-64952","number":"64952","sourceNumber":"64952","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 60 anos de idade, hipertenso e diabético, procura o serviço de emergência\npor precordialgia em aperto iniciada há 3 horas,\nirradiada ao dorso, de forte intensidade, associada\na náuseas, palidez e sudorese. Ao exame físico geral, encontra-se com fácies de dor, sudoreico e\ncom tiragem de intercostal, com PA de 135 x 90 mmHg e pulso de 48 bpm (rítmico). Ao exame\nespecífico, verifica-se a presença de crepitações inspiratórias em bases pulmonares. Sem outras\nanormalidades nos demais aparelhos. Submetido ao seguinte ECG: (VER IMAGEM). Qual é a\nabordagem terapêutica inicial?","options":{"A":"Monitorização cardíaca, oxigenioterapia, acesso venoso e administração de AAS.","B":"Cineangiocoronariografia imediata para abertura da artéria relacionada ao infarto.","C":"Fibrinólise imediata com rt-PA.","D":"Monitorização cardíaca, expansão volêmica, nitrato sublingual e oxigenioterapia.","E":"Monitorização cardíaca, oxigenioterapia, administração de AAS e dobutamina."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/64952.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-64956","number":"64956","sourceNumber":"64956","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 60 anos de idade, hipertenso e diabético, procura o serviço de emergência\npor precordialgia em aperto iniciada há 3 horas,\nirradiada de dorso, de forte intensidade, associada\na náuseas, palidez e sudorese. Ao exame físico geral, encontra-se com fácies de dor, sudoreico e\ncom tiragem de intercostal, com PA de 135 x 90 mmHg e pulso de 48 bpm (rítmico). Ao exame\nespecífico, verifica-se a presença de crepitações inspiratórias em bases pulmonares. Sem outras\nanormalidades nos demais aparelhos. Submetido ao seguinte ECG: (VER IMAGEM). Qual é o\ndiagnóstico e a classificação correta do evento?","options":{"A":"IAM de parede anterior extenso Killip II.","B":"IAM de parede inferior Killip I.","C":"IAM de parede anterior Killip I.","D":"IAM de parede septal Killip II.","E":"IAM de parede inferior Killip II."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/64956.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-34546","number":"34546","sourceNumber":"34546","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com relação ao Infarto Agudo do Miocárdio com Supradesnível ST, assinale a\nalternativa INCORRETA:","options":{"A":"Para o diagnóstico de IAM tardio, o marcador de necrose mais útil é a troponina, que permanece\nelevada por até 2 semanas após o início do quadro.","B":"Para o diagnóstico de reinfarto precoce, a CKMB deve ser escolhida, em virtude de sua rápida\nnormalização em até 48 horas.","C":"O uso de CPK e de mioglobina isoladamente como marcador de necrose miocárdica é\nfortemente desaconselhada.","D":"O marcador de necrose miocárdica preferencial para diagnóstico de IAM é a troponina cardíaca,\npela sua elevada sensibilidade e\nespecificidade.","E":"A CKMB massa é considerada a melhor opção, apresentando acurácia maior que a da\ntroponina."},"answer":"E","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-25774","number":"25774","sourceNumber":"25774","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação ao tratamento do infarto agudo do miocárdio (IAM) assinale a\nALTERNATIVA INCORRETA:","options":{"A":"Aspirina deve ser a primeira medicação administrada a todos os pacientes com dor torácica\nsugestiva de isquemia aguda;","B":"O oxigêneo deve ser mantido em todos pacientes com IAM nas primeiras 24hs.","C":"Os nitratos promovem vasodilatação venosa e arterial ocasionando redução da pré e pós-carga.","D":"Os betabloqueadores são contra indicados em pacientes com DPOC e bloqueio atrioventricular\nde segundo e terceiro graus.","E":"História de lesão expansiva cereblral conhecida é uma contra indicação absoluta para o uso de\nfibrinolíticos."},"answer":"B","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-8749","number":"8749","sourceNumber":"8749","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em relação ao tratamento do infarto agudo do miocárdio (IAM), assinale a alternativa\nincorreta:","options":{"A":"a Aspirina deve ser a primeira medicação administrada a todos os pacientes com dor torácica\nsugestiva de isquemia aguda.","B":"o oxigênio deve ser mantido em todos os pacientes com IAM nas primeiras 24 horas.","C":"os nitratos promovem vasodilatação venosa e arterial ocasionando redução da pré e pós-carga.","D":"os betabloqueadores são contra-indicados em pacientes com DPOC e bloqueio atrioventricular\nde 2º e 3º graus.","E":"história de lesão expansiva cerebral conhecida é uma contra-indicação absoluta para o uso de\nfibrinolíticos."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-359377","number":"359377","sourceNumber":"359377","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 64 anos foi atendido no pronto-socorro de um hospital que não possui\nserviço de hemodinâmica. Foi diagnosticado\ncom infarto agudo do miocárdio (IAM) com\nsupraelevação do segmento ST. Recebeu tratamento trombolítico com alteplase, apresentou\nresposta clínica e eletrocardiográfica (ECG pós-reperfusão sem anormalidades) e permaneceu sob\nmonitorização. Encontrava-se assintomático e apresentava os seguintes dados vitais: FC 68bpm,\nFR 18ipm, SpO2 95% (ar ambiente), PA 136/84mmHg, quando foi observado o seguinte traçado\neletrocardiográfico: Assinale a alternativa que apresenta a conduta MAIS ADEQUADA neste\nmomento em relação à abordagem da alteração eletrocardiográfica observada:","options":{"A":"Administração de amiodarona pela via IV.","B":"Cardioversão elétrica sincronizada.","C":"Conduta expectante e suporte clínico.","D":"Transferência para cateterismo de urgência (em até 1 hora)."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-149917","number":"149917","sourceNumber":"149917","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 66 anos, admitido com infarto agudo do miocárdio acometendo parede\ninferior do ventrículo esquerdo com seis\nhoras de evolução, apresenta-se com níveis pressóricos\nreduzidos, sinais de pressão venosa aumentada e pulmões limpos à ausculta. Qual afecção abaixo\nexplica MELHOR este quadro clínico?","options":{"A":"Edema agudo de pulmão.","B":"Falência ventricular esquerda.","C":"Infarto agudo do ventrículo direito.","D":"Síndrome pós-infarto do miocárdio."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-127492","number":"127492","sourceNumber":"127492","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Homem de 56 anos encontra-se no quinto dia após Infarto Agudo do Miocárdio,\napresentando onda Q, evoluindo com estabilidade\nhemodinâmica e sem congestão pulmonar, mas\npassa a apresentar atrito pericárdico à ausculta e relato de dor torácica com irradiação para a\ntopografia do músculo trapézio à esquerda. Diante deste contexto assinale a alternativa ERRADA:","options":{"A":"Deve se tratar de dor torácica associada com a ventilação e que melhora após assumir a\nposição sentada.","B":"Este quadro, geralmente, não necessita de tratamento específico, mas o uso de ácido\nacetilsalicílico auxilia no alívio da dor.","C":"Uso de indometacina e corticoides podem alterar a cicatrização do infarto e predispor à ruptura\ndo miocárdio.","D":"Do ponto de vista fisiopatológico, trata-se de fenômeno autoimune e pode recorrer após\nsemanas a meses."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-60337","number":"60337","sourceNumber":"60337","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Em face do traçado eletrocardiográfico abaixo reproduzido, seria lícito esperar que o\npaciente referisse a seguinte queixa: (VER IMAGEM)","options":{"A":"Dor precordial irradiada para a borda do músculo trapézio esquerdo, aliviada pela posição\nsentada, com o tórax inclinado para frente, e\nagravada pela inspiração profunda e pelo decúbito\ndorsal.","B":"Dor precordial irradiada para a borda do músculo trapézio esquerdo, aliviada pela inspiração\nprofunda e agravada pela posição sentada, com o tórax inclinado para frente.","C":"Dor precordial irradiada para o braço esquerdo, aliviada pelo decúbito dorsal e agravada pela\ninspiração profunda e pela posição sentada, com o tórax inclinado para frente.","D":"Dor precordial irradiada para o dorso, aliviada pelo decúbito dorsal e agravada pela posição\nsentada, com o tórax inclinado para frente."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/60337.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-52418","number":"52418","sourceNumber":"52418","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Mulher de 74 anos, internada em unidade de terapia intensiva há 48 horas com o\ndiagnóstico de Infarto Agudo do Miocárdio\n(IAM) de parede inferior, desenvolve, subitamente,\nquadro de dispneia. O exame objetivo mostra PA = 140 x 80 mmHg, FP = FC = 100 bpm, FR = 36\nipm, palidez cutânea, vasoconstrição periférica, taquidispneia, crepitações pulmonares bilaterais na\nmetade inferior do tórax, B3, B4, sopro sistólico grau III/VI, rude, na borda esternal esquerda\nmédia.\nQual é o diagnóstico mais provável?","options":{"A":"Falência de bomba pós-IAM","B":"Infarto de ventrículo direito","C":"Ruptura de septo interventricular","D":"Tromboembolismo pulmonar"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-22880","number":"22880","sourceNumber":"22880","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O diagnóstico da doença coronariana estável, pelas evidências atuais, se sustenta nos\nseguintes conceitos, EXCETO:","options":{"A":"A história e o exame clínicos ainda permanecem como os principais elementos diagnósticos.","B":"O eletrocardiograma de repouso realizado fora das crises é de baixo valor preditivo negativo.","C":"O eletrocardiograma de esforço possui sensibilidade e especificidade aceitáveis, mas depende\nda probabilidade pré-teste para sua interpretação.","D":"O cateterismo cardíaco é o exame padrão-ouro, porque revela não somente as placas estáveis\ncomo também as placas instáveis, com risco de infarto."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-359305","number":"359305","sourceNumber":"359305","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"É CORRETO afirmar que o uso de corticosteroides no tratamento da pericardite aguda\nestá indicado para","options":{"A":"pacientes que não responderam aos anti-inflamatórios não hormonais e à colchicina.","B":"todos os pacientes, independente de comorbidades anteriores.","C":"casos de etiologia viral.","D":"pacientes com alergia ao ácido acetilsalicílico."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-340700","number":"340700","sourceNumber":"340700","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A recomendação da dupla antiagregação plaquetária DAPT, com associação de ácido\nacetilsalicílico e um inibidor de P2Y12 (clopidogrel, ticagrelor ou prasugrel) após intervenção\ncoronária percutânea ICP, varia conforme o contexto clínico (doença arterial aguda ou crônica) e\ntipo de stent utilizado. Sobre isso, podemos afirmar que:","options":{"A":"Em pacientes submetidos à ICP fora da vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses, podendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","B":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 2 meses, podendo\na terapia ser reduzida para 6 dias ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","C":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses,\npodendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","D":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses,\npodendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, mas não o risco\nisquêmico."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-340706","number":"340706","sourceNumber":"340706","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"No contexto de Doença Arterial Coronariana (DAC) crônica, a recomendação atual é a\nrealização de dupla antiagregação plaquetária (DAPT):","options":{"A":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 3 a\n12 meses para os stents farmacológicos, com\nabreviação excepcionalmente em 30 dias, a\ndepender do risco de sangramento e geração do stent implantado.","B":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 2\nmeses para os stents farmacológicos, com\nabreviação excepcionalmente em 3 dias, a depender do\nrisco de sangramento e geração do stent implantado.","C":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 3 a\n12 meses para os stents farmacológicos, com\nabreviação excepcionalmente em 30 dias,\nindependente do risco de sangramento e geração do stent implantado.","D":"Durante tempo mínimo de 4 a 6 semanas para stents farmacológicos, e geralmente de 3 a 12\nmeses para os stents não farmacológicos, com\nabreviação excepcionalmente em 30 dias, a\ndepender do risco de sangramento e geração do stent implantado."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-346210","number":"346210","sourceNumber":"346210","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A pericardite é caracterizada por inflamação do pericárdio, podendo levar a um\nimportante derrame pericárdico e sintomas como\ndor torácica e dispneia. O exame físico pode ser\ncaracterizado pela presença de atrito pericárdico à ausculta cardíaca e o seu prognóstico depende\ndo acometimento e da causa. Sabendo disso, marque a alternativa que apresenta a causa mais\ncomum de pericardite.","options":{"A":"Doença bacteriana.","B":"Doença fúngica.","C":"Neoplasias.","D":"Doença viral.","E":"Lúpus eritematoso sistêmico."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-340764","number":"340764","sourceNumber":"340764","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O desempenho de exercícios resistidos em 2 a 3 dias por semana também pode ser\nrecomendado.","options":{"A":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 900 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado.","B":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 50 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado.","C":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade não vigorosa, ou uma combinação equivalente dos\nmesmos, idealmente com exercício diário supervisionado.","D":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-278836","number":"278836","sourceNumber":"278836","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A dor torácica é o principal sintoma sugestivo de Síndrome Coronária Aguda (SCA) com\ncaracterísticas da dor torácica sugestivas de isquemia miocárdica. Sendo correto que:","options":{"A":"Pacientes com dor anginosa em repouso com mais de 60 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA.","B":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor não são sugestivas de SCA.","C":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de ambulatório\nde cardiologia, já que essas características da dor são sugestivas de SCA.","D":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-260533","number":"260533","sourceNumber":"260533","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"A elevação do segmento ST, localizada em V1 e V2 não pode ser detectada no traçado\neletrocardiogràfico de :","options":{"A":"Padrão de Brugada.","B":"Hipercalcemia.","C":"Hipertrofia ventricular direita.","D":"Hiperpotassemia."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-260534","number":"260534","sourceNumber":"260534","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Dentre as doenças a seguir a que cursa mais habitualmente com pulso paradoxal é:","options":{"A":"Tamponamento Cardíaco.","B":"Insuficiência cardíaca diastólica.","C":"Insuficiência aórtica.","D":"Dissecção aórtica."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-260257","number":"260257","sourceNumber":"260257","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Com relação às Síndromes Coronarianas Agudas Sem Supradesnivelamento do\nSegmento ST (SCASST), assinale a alternativa INCORRETA.","options":{"A":"Os betabloqueadores devem ser iniciados precocemente, na ausência de contraindicações.","B":"O emprego da nitroglicerina deve ser considerado quando houver precordialgia persistente,\ncongestão pulmonar e/ou hipertensão arterial\nrefratária.","C":"A mortalidade dos pacientes com SCASST, em longo prazo, é inferior à dos pacientes com\nsíndrome coronariana aguda com supradesnivelamento do segmento ST.","D":"O escore GRACE (Global Registry of Acute Coronary Events) permite avaliar a gravidade dos\npacientes, fornecendo uma estratificação de risco precisa tanto na admissão quanto na alta."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-253900","number":"253900","sourceNumber":"253900","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Analise as alternativas abaixo e marque o betabloqueador que não está aprovado para\ntratamento clínico da cardiopatia isquêmica:","options":{"A":"Propranolol","B":"Metoprolol","C":"Carvedilol","D":"Bisoprolol"},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-253902","number":"253902","sourceNumber":"253902","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Uma opção terapêutica nos pacientes com doença coronariana crônica estável é a\ninibição do metabolismo de ácidos graxos pelos miócitos, que passam a utilizar vias metabólicas\nmais eficientes, diminuindo a isquemia. O medicamento que possui este mecanismo de ação é:","options":{"A":"Neprisilina","B":"Levosimendan","C":"Ivabradina","D":"Trimetazidina"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-244513","number":"244513","sourceNumber":"244513","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Estudos sugerem que a terapia com AAS pode estar associada a uma diminuição do\nAVC entre mulheres diabéticas. Dos itens\nabaixo, qual apresenta erro?","options":{"A":"Ocorre uma diminuição do infarto agudo do miocárdio (IAM) entre homens diabéticos.","B":"Ocorrem que as reduções de risco obtidas com baixas doses (75 mg/dia) foram tão significativas\nquanto às obtidas com doses mais elevadas (650\nmg/dia).","C":"Baixa dose de AAS era benéfica para a prevenção primária de DCV nos pacientes de alto risco e\nque a decisão sobre o tratamento com AAS\ndeveria ser feita coletivamente.","D":"Indicação da terapia antiplaquetária nos pacientes de muito alto risco, incluindo aqueles com\nDACL e eventos cardiovasculares prévios\n(prevenção secundária), o benefício é estabelecido."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-238640","number":"238640","sourceNumber":"238640","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Após a administração de fibrinolítico no infarto agudo do miocárdio com\nsupradesnivelamento do segmento ST, indica-se a\nintervenção coronariana percutânea de resgate\nna seguinte situação:","options":{"A":"Quando há aumento de troponina após seis horas de administração do fibrinolítico.","B":"Sempre e imediatamente após o término da fibrinólise.","C":"Manutenção da dor torácica e/ou se não houver redução de pelo menos 50% do\nsupradesnivelamento do ST no eletrocardiograma.","D":"Se o paciente apresentar ritmo idioventricular acelerado ao eletrocardiograma."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-219404","number":"219404","sourceNumber":"219404","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente sexo feminino de 32 anos apresentando piora dor torácica retroesternal nos\núltimos 7 dias. Ela se queixa de dispneia e edema de membros inferiores. Faz uso de\nhidroxicloroquina para lesão facial fotossensível, rash e úlceras orais. Rx tórax com aumento da\nsilhueta cardíaca. Qual a descrição mais característica do seu pulso?","options":{"A":"Anacrótico","B":"Bífido","C":"Colapsante","D":"Baixa amplitude"},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-201647","number":"201647","sourceNumber":"201647","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Um homem de 45 anos, portador de dislipidemia e diabetes, é admitido no Hospital da\nPolícia Militar queixando-se de dor torácica retroesternal, ventilatório-dependente, que melhora na\nposição sentada e inclinado para a frente, associada à dispneia leve, de início há 6 horas. Nega\nuso de entorpecentes. Realizado o ECG apresentado abaixo. Troponina = 0,2 ng/ml (VR = 0,01\nng/ml). Sobre esse caso, marque a alternativa CORRETA:","options":{"A":"Trata-se de infarto agudo do miocárdio de parede anterior extenso, sendo indicado cateterismo\nde urgência ou trombólise.","B":"Deve-se realizar angiotomografia de tórax ou cintilografia pulmonar de ventilação e perfusão na\nurgência e iniciar anticoagulação plena.","C":"A realização de ecocardiograma não contribui para o diagnóstico e a avaliação da gravidade.","D":"Anti-inflamatório, colchicina e repouso são medidas que devem ser prontamente instituídas."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/201647.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-203929","number":"203929","sourceNumber":"203929","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 52 anos com quadro de dor torácica de moderada intensidade, em aperto,\ncom irradiação para MSE, duração de 8 minutos e\nassociada a dispneia e sudorese. Paciente é\nhipertenso e diabético. Apresenta ECG a seguir: De acordo com a principal hipótese diagnóstica\npara o quadro descrito, são medicamentos que podem fazer parte do tratamento do paciente,\nEXCETO:","options":{"A":"Alteplase.","B":"Isordil.","C":"Clopidogrel.","D":"Ticagrelor."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/203929.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-210452","number":"210452","sourceNumber":"210452","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Analise o caso abaixo: um paciente de 52 anos foi admitido na UPA/Oeste com quadro\nde dor torácica típica para insuficiência\ncoronariana aguda. O ECG mostrava supradesnivelamento\nde ST em DII, DIII e AVF, além de V3R e V4R (derivações feitas como imagem em espelho de V3 e\nV4 tradicionais, mais à direita). Não apresentava crepitações à ausculta pulmonar, mas exibia\nhipotensão e confusão mental. Ao exame, também apresentava elevação paradoxal da veia jugular\nexterna durante a inspiração. Assinale a alternativa que representa as informações consideradas\nCORRETAS sobre o caso descrito:","options":{"A":"O paciente apresenta um quadro de infarto agudo do miocárdio de parede inferior de VE com\ninfarto de ventrículo direito e sinal de Kussmaul.","B":"O edema agudo dos pulmões pode se apresentar com ausculta pulmonar normal se o paciente\ntiver infarto da artéria circunflexa.","C":"O paciente apresenta-se também com sinais de tromboembolismo pulmonar maciço ou\ndissecção aguda da aorta, sendo necessário\nsaber pelo menos as enzimas cardíacas para indicar a\ntrombólise.","D":"O quadro desse paciente se confunde com pericardite constritiva crônica com sinais de baixo\ndébito cardíaco e, nesse caso, o ecocardiograma é necessário para o diagnóstico diferencial."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181241","number":"181241","sourceNumber":"181241","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"O uso da Ecocardiografia sob estresse na doença aterosclerótica coronariana crônica,\nsomente não apresenta a seguinte característica descrita a seguir:","options":{"A":"O ecocardiografia sob estresse é um método não invasivo, estabelecido para a avaliação de\npacientes com DAC obstrutiva suspeita ou conhecida, para a determinação do diagnóstico e\nprognóstico, na avaliação do impacto de terapias de revascularização, mas não na detecção de\nviabilidade miocárdica.","B":"O estresse cardiovascular causa isquemia miocárdica em regiões supridas por uma artéria com\ngrau significativo de estenose, e esse fenômeno é manifestado por alteração transitória da\ncontração segmentar.","C":"A ecocardiografia bidimensional permite a avaliação de todos os segmentos miocárdicos do\nventrículo esquerdo com grande resolução\nespacial e temporal, tornando-se a ferramenta ideal para\na avaliação não invasiva da isquemia miocárdica.","D":"Os métodos disponíveis para a indução do estresse são o esforço físico (esteira ou bicicleta\nergométrica), a estimulação atrial transesofágica, e o uso de drogas vasodilatadoras (dipiridamol e\nadenosina) ou de estimulantes adrenérgicos (dobutamina)."},"answer":"A","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181253","number":"181253","sourceNumber":"181253","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Durante última visita em grupo da cardiologia, você foi indicado para explicar aos\ncolegas sobre o uso de Marcadores de Lesão\nMiocárdica, sua apresentação foi bastante elogiada,\nmas o chefe do setor não concordou com uma de suas afirmações. De acordo com as últimas\ndiretrizes aceitas, aponte essa possível afirmação:","options":{"A":"Embora as troponinas sejam importantes fatores prognósticos de risco, elas não devem ser\nutilizadas isoladamente para definir o risco de pacientes com SCA.","B":"A maior parte dos pacientes que desenvolvem complicações apresenta troponinas normais;\nnenhum marcador bioquímico é perfeitamente acurado para determinar dano miocárdio.","C":"As Troponinas nos paciente que se apresentam em menos de 3 horas do início dos sintomas,\nestão dentro do valor de normalidade, não\nsendo sempre necessária a mensuração seriada do\nmarcador.","D":"As troponinas na admissão estão dentro do valor de normalidade em até um quinto dos\npacientes que depois confirmam diagnóstico de IAM."},"answer":"C","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-3-181027","number":"181027","sourceNumber":"181027","collectionBlock":"medcurso:medcurso-cardiologia-car-3","collectionLabel":"Medcurso · CAR 3","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 3","subtopic":"","stem":"Paciente de 64 anos com história prévia de radioterapia com irradiação do tórax\napresenta-se com sintomas gradualmente\nprogressivos de fadiga, ascite, edema de membros\ninferiores e elevação da pressão venosa jugular ao longo dos últimos 4 meses. A radiografia do\npaciente é mostrada abaixo. A respeito do provável diagnóstico é CORRETO afirmar:","options":{"A":"O paciente irá apresentar a onda Y do pulso venoso jugular atenuada.","B":"A tomografia de tórax é menos precisa que o ecocardiograma para demonstrar o diagnóstico.","C":"A tuberculose não é causa importante do diagnóstico nos países em desenvolvimento.","D":"Pode haver Knock pericárdico na diástole."},"answer":"D","source":"Cardiologia/CAR 3/CAR 3.txt","sourceLabel":"Medcurso · CAR 3","images":["question_bank/media/medcurso/medcurso-cardiologia-car-3/181027.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
